select ac_cargar_unidad($ac${"slug":"animales-1","rama":"animales","orden":1,"nivel":1,"titulo_es":"La trama de la vida","bajada_es":"Genes, especies y ecosistemas: qué es la biodiversidad, cómo se conectan los seres vivos y por qué perder una especie mueve toda la red.","objetivos_es":["Definir la biodiversidad en sus tres niveles","Armar cadenas y redes tróficas con productores, consumidores y descomponedores","Explicar el papel de las especies clave y los ingenieros de ecosistemas","Relacionar adaptaciones de animales argentinos con su ambiente","Reconocer los servicios que la fauna presta a las personas"],"repasa":["tronco-1"],"requiere_tronco":1,"fuentes":["ipbes-global","iucn-red-list","sib-apn","sarem-2019","aves-argentinas","parques-nacionales","gbif"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-1.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es la biodiversidad","bajada_es":"Genes, especies y ecosistemas: tres niveles de la variedad de la vida.","minutos":11,"pasos":[{"slug":"animales-1.s1.p1","orden":1,"grupo":"animales-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres niveles","cuerpo":["Biodiversidad es la variedad de la vida en todas sus formas. Se mira en tres niveles: la diversidad genética (las diferencias entre individuos de una misma especie), la diversidad de especies (cuántas y cuáles especies hay) y la diversidad de ecosistemas (selvas, pastizales, humedales, mares).","Los tres importan. Una especie con poca diversidad genética es más vulnerable a enfermedades o cambios del clima. Un paisaje con un solo tipo de ecosistema ofrece menos hábitats."]},"solucion":{}},{"slug":"animales-1.s1.p2","orden":2,"grupo":"animales-1.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué nivel de la biodiversidad se refiere cada ejemplo?","grupos":[{"id":"g1","nombre":"Genética"},{"id":"g2","nombre":"De especies"},{"id":"g3","nombre":"De ecosistemas"}],"items":[{"id":"i1","texto":"Los distintos colores de pelaje en una población de zorros"},{"id":"i2","texto":"Las aves distintas que viven en una laguna"},{"id":"i3","texto":"Selvas, humedales y estepas en un mismo país"},{"id":"i4","texto":"Las muchas variedades de maíz de los pueblos andinos"},{"id":"i5","texto":"La cantidad de especies de ranas en las Yungas"},{"id":"i6","texto":"Bosques y pastizales en una misma provincia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La biodiversidad no es solo contar especies: también son las diferencias dentro de ellas y entre paisajes."}},{"slug":"animales-1.s1.p3","orden":3,"grupo":"animales-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuántas especies hay","cuerpo":["La ciencia describió alrededor de 2 millones de especies, pero se estima que existen muchas más: solo de animales, plantas, hongos y otros organismos con células complejas podría haber alrededor de 8 a 9 millones. La mayoría son insectos y otros invertebrados, muchos todavía sin nombre.","Argentina, con su enorme variedad de climas, tiene alrededor de 1.000 especies de aves y unas 400 de mamíferos, además de miles de especies de plantas, peces, anfibios, reptiles e invertebrados."],"destacado":{"valor":"≈ 1.000","texto":"especies de aves viven en Argentina: una de las avifaunas más ricas del mundo."}},"solucion":{}},{"slug":"animales-1.s1.p4","orden":4,"grupo":"animales-1.s1.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas especies de seres vivos describió la ciencia hasta hoy.","min":10000,"max":100000000,"paso":1,"unidad":"especies","escala":"log"},"solucion":{"valor":2000000,"banda":"log","explicacion":"Alrededor de 2 millones. Y se estima que existen varias veces más, sobre todo insectos y organismos chicos."}},{"slug":"animales-1.s1.p5","orden":5,"grupo":"animales-1.s1.p5","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos grupos de animales por cantidad de especies descriptas en el mundo, de más a menos.","items":[{"id":"i1","texto":"Insectos"},{"id":"i2","texto":"Peces"},{"id":"i3","texto":"Aves"},{"id":"i4","texto":"Mamíferos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los insectos dominan la biodiversidad animal. Los mamíferos, el grupo que más miramos, son una fracción mínima.","valores":{"i1":"alrededor de un millón","i2":"más de 30.000","i3":"unas 11.000","i4":"unas 6.500"}}},{"slug":"animales-1.s1.p6","orden":6,"grupo":"animales-1.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayoría de las especies del planeta ya fueron descubiertas y descriptas por la ciencia.","razones":[{"id":"r1","texto":"Porque se estima que existen varias veces más de las descriptas"},{"id":"r2","texto":"Porque ya no quedan lugares por explorar"},{"id":"r3","texto":"Porque todas las especies son grandes y fáciles de ver"}]},"solucion":{"valor":false,"explicacion":"Se describieron alrededor de 2 millones, pero se estima que existen varias veces más. Cada año se describen miles de especies nuevas.","clave":["r1"]}},{"slug":"animales-1.s1.p7","orden":7,"grupo":"animales-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué importa la variedad","cuerpo":["Un ecosistema con muchas especies suele ser más estable: si una especie falla por una sequía o una enfermedad, otras pueden cumplir funciones parecidas. Es como una red con muchos hilos: si se corta uno, no se cae todo.","La biodiversidad también es la fuente de alimentos, medicinas, materiales y de muchos servicios que la naturaleza da gratis, como la polinización o el control de plagas."]},"solucion":{}},{"slug":"animales-1.s1.p8","orden":8,"grupo":"animales-1.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un cultivo con una sola variedad es más frágil.","items":[{"id":"i1","texto":"Todas las plantas del campo son genéticamente iguales"},{"id":"i2","texto":"Aparece una enfermedad que afecta a esa variedad"},{"id":"i3","texto":"Ninguna planta tiene defensas distintas"},{"id":"i4","texto":"Se pierde todo el cultivo"},{"id":"i5","texto":"Las plantas iguales se protegen entre sí"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La diversidad genética es un seguro. Por eso se conservan semillas de muchas variedades en bancos de germoplasma."}},{"slug":"animales-1.s1.p9","orden":9,"grupo":"animales-1.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios trae la biodiversidad a las personas? Marcá todos.","opciones":[{"id":"o1","texto":"Alimentos variados"},{"id":"o2","texto":"Medicinas"},{"id":"o3","texto":"Polinización de cultivos"},{"id":"o4","texto":"Ecosistemas más estables"},{"id":"o5","texto":"Más enfermedades en los cultivos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La biodiversidad es la base de lo que comemos, de muchos remedios y de la estabilidad de los ecosistemas."}},{"slug":"animales-1.s1.p10","orden":10,"grupo":"animales-1.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ecosistema argentino con un animal característico.","izquierda":[{"id":"a1","texto":"Selva Paranaense"},{"id":"a2","texto":"Estepa Patagónica"},{"id":"a3","texto":"Esteros del Iberá"},{"id":"a4","texto":"Altos Andes"}],"derecha":[{"id":"b1","texto":"Yaguareté"},{"id":"b2","texto":"Guanaco"},{"id":"b3","texto":"Ciervo de los pantanos"},{"id":"b4","texto":"Cóndor andino"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada ecosistema tiene su fauna. La diversidad de ecosistemas trae diversidad de especies."}},{"slug":"animales-1.s1.p11","orden":11,"grupo":"animales-1.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La biodiversidad incluye genes, especies y ecosistemas."},{"id":"s2","texto":"Biodiversidad es solo la cantidad de animales grandes de un lugar."},{"id":"s3","texto":"Argentina tiene alrededor de 1.000 especies de aves."},{"id":"s4","texto":"Un ecosistema con menos especies es más estable."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La biodiversidad es mucho más que los animales que vemos.","por_opcion":{"s2":"Incluye todos los seres vivos y los tres niveles, no solo animales grandes.","s4":"Suele ser al revés: más especies dan más estabilidad."}}},{"slug":"animales-1.s1.p12","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 2 millones de especies y se estima que existen 8 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"2 ÷ 8 × 100 = 25 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p12.v2","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 2 millones de especies y se estima que existen 10 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"2 ÷ 10 × 100 = 20 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p12.v3","orden":12,"grupo":"animales-1.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se describieron 1,5 millones de especies y se estima que existen 6 millones, ¿qué porcentaje conocemos?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"1,5 ÷ 6 × 100 = 25 %. La mayor parte de la vida del planeta todavía no tiene nombre científico."}},{"slug":"animales-1.s1.p13","orden":13,"grupo":"animales-1.s1.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie con poca diversidad genética es más vulnerable a una enfermedad nueva.","razones":[{"id":"r1","texto":"Porque sin variación, lo que afecta a uno afecta a casi todos"},{"id":"r2","texto":"Porque las enfermedades no afectan a los animales"},{"id":"r3","texto":"Porque la diversidad genética aumenta las enfermedades"}]},"solucion":{"valor":true,"explicacion":"Si todos los individuos son parecidos, una enfermedad que afecta a uno puede afectar a casi todos. La variación genética es un seguro.","clave":["r1"]}},{"slug":"animales-1.s1.p14","orden":14,"grupo":"animales-1.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La biodiversidad se mira en tres niveles: {{0}}, de {{1}} y de {{2}}.","banco":[{"id":"w1","texto":"genética"},{"id":"w2","texto":"especies"},{"id":"w3","texto":"ecosistemas"},{"id":"w4","texto":"química"},{"id":"w5","texto":"ciudades"},{"id":"w6","texto":"climas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres niveles de la variedad de la vida, en una sola línea."}}]},{"slug":"animales-1.s2","orden":2,"tipo":"leccion","titulo_es":"Quién come a quién","bajada_es":"Productores, consumidores y descomponedores: cadenas y redes tróficas con animales argentinos.","minutos":11,"pasos":[{"slug":"animales-1.s2.p1","orden":1,"grupo":"animales-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los papeles de la red","cuerpo":["En un ecosistema, los productores —plantas, algas— fabrican su alimento con la luz del sol. Los consumidores comen a otros seres vivos: los herbívoros comen plantas, los carnívoros comen animales y los omnívoros comen de todo. Los descomponedores —hongos, bacterias, lombrices— transforman los restos de los seres muertos en nutrientes que vuelven al suelo.","Una cadena trófica muestra quién come a quién en línea: pasto, cuis, zorro. Pero en la realidad, cada especie come y es comida por varias: se forma una red trófica."]},"solucion":{}},{"slug":"animales-1.s2.p2","orden":2,"grupo":"animales-1.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué papel cumple cada ser vivo en el ecosistema?","grupos":[{"id":"g1","nombre":"Productor"},{"id":"g2","nombre":"Consumidor"},{"id":"g3","nombre":"Descomponedor"}],"items":[{"id":"i1","texto":"Pasto del pastizal"},{"id":"i2","texto":"Ñandú"},{"id":"i3","texto":"Hongos del suelo"},{"id":"i4","texto":"Algas de una laguna"},{"id":"i5","texto":"Puma"},{"id":"i6","texto":"Lombrices"},{"id":"i7","texto":"Carpincho"},{"id":"i8","texto":"Bacterias"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g2","i8":"g3"},"explicacion":"Sin productores no entra energía; sin descomponedores, los nutrientes no vuelven al suelo."}},{"slug":"animales-1.s2.p3","orden":3,"grupo":"animales-1.s2.p3","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená esta cadena trófica del pastizal, del productor al último consumidor.","items":[{"id":"i1","texto":"Pasto"},{"id":"i2","texto":"Tucura (saltamontes)"},{"id":"i3","texto":"Sapo"},{"id":"i4","texto":"Culebra"},{"id":"i5","texto":"Aguilucho"}],"extremos":["Productor","Último consumidor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La energía del sol entra por el pasto y va pasando, escalón por escalón, hasta el aguilucho."}},{"slug":"animales-1.s2.p4","orden":4,"grupo":"animales-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La energía se achica en cada escalón","cuerpo":["Como viste en el tronco, en cada escalón pasa alrededor del 10 % de la energía al siguiente: el resto se usa para vivir y se pierde como calor. Por eso hay mucho más pasto que tucuras, más tucuras que sapos y muy pocos aguiluchos.","También por eso los grandes carnívoros, como el puma o el yaguareté, necesitan territorios enormes: tienen que recorrer mucho para encontrar suficiente alimento."]},"solucion":{}},{"slug":"animales-1.s2.p5","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 10.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"Herbívoros: 10.000 × 0,1 = 1.000. Carnívoros: × 0,1 = 100. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p5.v2","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 50.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"Herbívoros: 50.000 × 0,1 = 5.000. Carnívoros: × 0,1 = 500. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p5.v3","orden":5,"grupo":"animales-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pastizal captura 100.000 unidades de energía. Si pasa el 10 % a cada escalón, ¿cuántas llegan al tercer escalón (pasto → herbívoro → carnívoro)?","unidad":"unidades","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"Herbívoros: 100.000 × 0,1 = 10.000. Carnívoros: × 0,1 = 1.000. Por eso hay tan pocos carnívoros grandes."}},{"slug":"animales-1.s2.p6","orden":6,"grupo":"animales-1.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un yaguareté necesita un territorio grande porque está en lo alto de la red trófica.","razones":[{"id":"r1","texto":"Porque llega poca energía a lo alto de la red"},{"id":"r2","texto":"Porque los yaguaretés comen pasto"},{"id":"r3","texto":"Porque no pueden dormir en el mismo lugar dos veces"}]},"solucion":{"valor":true,"explicacion":"Llega poca energía a lo alto de la red, así que un carnívoro grande necesita recorrer mucha superficie para encontrar presas suficientes.","clave":["r1"]}},{"slug":"animales-1.s2.p7","orden":7,"grupo":"animales-1.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Redes, no cadenas","cuerpo":["En una laguna pampeana, las algas y las plantas acuáticas son comidas por caracoles, peces chicos y patos. Las mojarras comen insectos y plancton; las tarariras comen mojarras; las garzas comen mojarras, ranas y tarariras chicas; los biguás bucean por peces. Todos, al morir, alimentan a los descomponedores.","En una red, si una especie desaparece, las que la comían buscan otro alimento, y las que eran comidas por ella pueden multiplicarse. Los efectos viajan por los hilos de la red."]},"solucion":{}},{"slug":"animales-1.s2.p8","orden":8,"grupo":"animales-1.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar si en una laguna se pescan casi todas las tarariras.","items":[{"id":"i1","texto":"Se pescan casi todas las tarariras"},{"id":"i2","texto":"Las mojarras tienen menos depredadores"},{"id":"i3","texto":"Aumenta mucho la cantidad de mojarras"},{"id":"i4","texto":"Las mojarras comen más plancton que filtra el agua"},{"id":"i5","texto":"El agua puede volverse más turbia"},{"id":"i6","texto":"Las mojarras se convierten en tarariras"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un cambio arriba de la red puede bajar en cascada hasta el agua. Es una cascada trófica."}},{"slug":"animales-1.s2.p9","orden":9,"grupo":"animales-1.s2.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con lo que suele comer.","izquierda":[{"id":"a1","texto":"Carpincho"},{"id":"a2","texto":"Garza blanca"},{"id":"a3","texto":"Hornero"},{"id":"a4","texto":"Puma"}],"derecha":[{"id":"b1","texto":"Pastos y plantas acuáticas"},{"id":"b2","texto":"Peces y ranas"},{"id":"b3","texto":"Insectos y larvas"},{"id":"b4","texto":"Guanacos, liebres y otros mamíferos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada animal ocupa un lugar en la red según lo que come."}},{"slug":"animales-1.s2.p10","orden":10,"grupo":"animales-1.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué pasaría en un bosque si desaparecieran todos los descomponedores?","opciones":[{"id":"o1","texto":"Se acumularían restos y faltarían nutrientes en el suelo"},{"id":"o2","texto":"Las plantas crecerían más rápido porque habría menos competencia"},{"id":"o3","texto":"No pasaría nada: los descomponedores no cumplen ninguna función"},{"id":"o4","texto":"Los animales vivirían más años"}]},"solucion":{"clave":["o1"],"explicacion":"Los descomponedores cierran el ciclo de la materia que viste en el tronco. Sin ellos, todo se detiene.","por_opcion":{"o3":"Son los que devuelven los nutrientes al suelo: sin ellos, el ciclo se corta."}}},{"slug":"animales-1.s2.p11","orden":11,"grupo":"animales-1.s2.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son omnívoros (comen plantas y animales)? Marcá todos.","opciones":[{"id":"o1","texto":"Zorro gris"},{"id":"o2","texto":"Comadreja overa"},{"id":"o3","texto":"Ñandú"},{"id":"o4","texto":"Puma"},{"id":"o5","texto":"Guanaco"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El zorro, la comadreja y el ñandú comen frutos, semillas, insectos y pequeños animales. El puma es carnívoro; el guanaco, herbívoro."}},{"slug":"animales-1.s2.p12","orden":12,"grupo":"animales-1.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los productores fabrican su alimento con la luz del sol."},{"id":"s2","texto":"Hay más aguiluchos que tucuras en un pastizal."},{"id":"s3","texto":"Los hongos son descomponedores."},{"id":"s4","texto":"Cada especie come a una sola especie y es comida por una sola."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Redes, no cadenas, y menos energía en cada escalón.","por_opcion":{"s2":"Es al revés: arriba de la red llega menos energía y hay menos individuos.","s4":"En la realidad se forman redes: cada especie come y es comida por varias."}}},{"slug":"animales-1.s2.p13","orden":13,"grupo":"animales-1.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las plantas son {{0}}, los animales son {{1}} y los hongos y bacterias que reciclan restos son {{2}}.","banco":[{"id":"w1","texto":"productores"},{"id":"w2","texto":"consumidores"},{"id":"w3","texto":"descomponedores"},{"id":"w4","texto":"predadores"},{"id":"w5","texto":"parásitos"},{"id":"w6","texto":"polinizadores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Los tres papeles básicos de cualquier ecosistema."}}]},{"slug":"animales-1.s3","orden":3,"tipo":"leccion","titulo_es":"Especies que sostienen a otras","bajada_es":"Depredadores tope, polinizadores e ingenieros de ecosistemas: algunas especies pesan mucho más que su número.","minutos":12,"pasos":[{"slug":"animales-1.s3.p1","orden":1,"grupo":"animales-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Especies clave","cuerpo":["Algunas especies tienen un efecto sobre el ecosistema mucho mayor de lo que haría pensar su cantidad: si desaparecen, el ecosistema cambia mucho. Se las llama especies clave.","Los depredadores tope, como el yaguareté o el puma, suelen ser especies clave: regulan a los herbívoros, que a su vez afectan a las plantas. Sin ellos, los herbívoros pueden multiplicarse y sobrepastorear."]},"solucion":{}},{"slug":"animales-1.s3.p2","orden":2,"grupo":"animales-1.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar cuando desaparece un depredador tope.","items":[{"id":"i1","texto":"Desaparece el depredador tope de una región"},{"id":"i2","texto":"Los herbívoros tienen menos depredadores"},{"id":"i3","texto":"Aumentan mucho los herbívoros"},{"id":"i4","texto":"Comen más plantas de las que se regeneran"},{"id":"i5","texto":"Cambia la vegetación y todo el ecosistema"},{"id":"i6","texto":"Las plantas se multiplican porque hay menos carnívoros"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un efecto en cascada que baja desde lo alto de la red hasta el suelo."}},{"slug":"animales-1.s3.p3","orden":3,"grupo":"animales-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ingenieros de ecosistemas","cuerpo":["Otras especies son ingenieras: modifican el ambiente y crean hábitats para otras. Las vizcachas cavan vizcacheras que usan muchos otros animales; los horneros construyen nidos que después ocupan otras aves; las lombrices airean y mezclan el suelo.","Pero un ingeniero también puede ser destructivo fuera de su lugar: el castor, traído de América del Norte a Tierra del Fuego, construye diques que inundan y matan bosques nativos que no evolucionaron con él."]},"solucion":{}},{"slug":"animales-1.s3.p4","orden":4,"grupo":"animales-1.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ingeniero con lo que hace.","izquierda":[{"id":"a1","texto":"Vizcacha"},{"id":"a2","texto":"Hornero"},{"id":"a3","texto":"Lombriz"},{"id":"a4","texto":"Castor en Tierra del Fuego"}],"derecha":[{"id":"b1","texto":"Cava cuevas que usan otros animales"},{"id":"b2","texto":"Construye nidos que después ocupan otras aves"},{"id":"b3","texto":"Airea y mezcla el suelo"},{"id":"b4","texto":"Hace diques que inundan bosques nativos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los ingenieros cambian el ambiente. En su lugar de origen lo enriquecen; fuera de él, pueden destruirlo."}},{"slug":"animales-1.s3.p5","orden":5,"grupo":"animales-1.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El castor es un ingeniero de ecosistemas que beneficia a los bosques de Tierra del Fuego.","razones":[{"id":"r1","texto":"Porque es invasor y sus diques matan bosques que no evolucionaron con él"},{"id":"r2","texto":"Porque los castores no construyen diques"},{"id":"r3","texto":"Porque en Tierra del Fuego no hay bosques"}]},"solucion":{"valor":false,"explicacion":"Allí es una especie exótica invasora: sus diques inundan y matan bosques de lenga y ñire que no evolucionaron con castores.","clave":["r1"]}},{"slug":"animales-1.s3.p6","orden":6,"grupo":"animales-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Polinizadores y dispersores","cuerpo":["Los polinizadores —abejas, mariposas, picaflores, murciélagos— permiten que se reproduzcan muchas plantas, incluidos cultivos. Los dispersores de semillas —aves, murciélagos, monos, tapires, zorros— llevan las semillas lejos de la planta madre.","Si faltan, las plantas que dependen de ellos dejan de reproducirse o se quedan en un solo lugar. En selvas donde se cazaron los grandes dispersores, algunos árboles de semillas grandes casi no logran regenerarse."]},"solucion":{}},{"slug":"animales-1.s3.p7","orden":7,"grupo":"animales-1.s3.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales pueden dispersar semillas? Marcá todos.","opciones":[{"id":"o1","texto":"Zorzal"},{"id":"o2","texto":"Tapir"},{"id":"o3","texto":"Murciélago frugívoro"},{"id":"o4","texto":"Zorro"},{"id":"o5","texto":"Lombriz"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los animales que comen frutos llevan las semillas en su interior y las dejan lejos. Las lombrices mezclan el suelo, pero no dispersan semillas grandes."}},{"slug":"animales-1.s3.p8","orden":8,"grupo":"animales-1.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el yaguareté se considera una especie clave en la selva?","opciones":[{"id":"o1","texto":"Porque regula a sus presas, y eso mueve todo"},{"id":"o2","texto":"Porque es el animal más numeroso de la selva"},{"id":"o3","texto":"Porque dispersa las semillas de los árboles"},{"id":"o4","texto":"Porque come los frutos que caen al suelo"}]},"solucion":{"clave":["o1"],"explicacion":"Su efecto sobre el ecosistema es mucho mayor que su número, que es chico.","por_opcion":{"o3":"No es dispersor: su papel es el de depredador tope."}}},{"slug":"animales-1.s3.p9","orden":9,"grupo":"animales-1.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Volver a traerlos","cuerpo":["Cuando una especie clave desaparece de una región, a veces se puede reintroducir. En los Esteros del Iberá, en Corrientes, proyectos de conservación reintrodujeron especies que habían desaparecido de la zona, como el oso hormiguero, el pecarí de collar, el guacamayo rojo, la nutria gigante y el yaguareté, que volvió a nacer en libertad allí después de décadas.","Esto se llama restauración o renaturalización: devolver a un ecosistema las piezas que le faltaban para que vuelva a funcionar."]},"solucion":{}},{"slug":"animales-1.s3.p10","orden":10,"grupo":"animales-1.s3.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta especie fue reintroducida en los Esteros del Iberá o no?","grupos":[{"id":"g1","nombre":"Reintroducida"},{"id":"g2","nombre":"No (nunca desapareció de allí o no es de la zona)"}],"items":[{"id":"i1","texto":"Yaguareté"},{"id":"i2","texto":"Carpincho"},{"id":"i3","texto":"Oso hormiguero"},{"id":"i4","texto":"Yacaré"},{"id":"i5","texto":"Guacamayo rojo"},{"id":"i6","texto":"Pingüino de Magallanes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Carpinchos y yacarés siguieron en los esteros. El pingüino es del mar patagónico, no de Corrientes."}},{"slug":"animales-1.s3.p11","orden":11,"grupo":"animales-1.s3.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos efectos de reintroducir un depredador tope, del más inmediato al más lejano.","items":[{"id":"i1","texto":"Aparece un depredador que caza herbívoros"},{"id":"i2","texto":"Los herbívoros cambian su comportamiento y su número"},{"id":"i3","texto":"La vegetación se recupera en algunas zonas"},{"id":"i4","texto":"Se recupera la estructura completa del ecosistema"}],"extremos":["Más inmediato","Más lejano"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los efectos de una especie clave se despliegan con el tiempo, como los retrasos que viste en el tronco.","valores":{"i1":"inmediato","i2":"meses a años","i3":"años","i4":"décadas"}}},{"slug":"animales-1.s3.p12","orden":12,"grupo":"animales-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El yaguareté volvió a nacer en libertad en los Esteros del Iberá."},{"id":"s2","texto":"Los depredadores tope no afectan a las plantas."},{"id":"s3","texto":"Las vizcachas cavan cuevas que usan otros animales."},{"id":"s4","texto":"Todo ingeniero de ecosistemas es beneficioso en cualquier lugar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Algunas especies pesan mucho más que su número. Y el contexto importa.","por_opcion":{"s2":"Al regular a los herbívoros, afectan indirectamente a la vegetación.","s4":"Fuera de su lugar de origen, como el castor en Tierra del Fuego, puede ser destructivo."}}},{"slug":"animales-1.s3.p13","orden":13,"grupo":"animales-1.s3.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie con pocos individuos nunca puede ser importante para el ecosistema.","razones":[{"id":"r1","texto":"Porque algunas especies escasas tienen efectos enormes"},{"id":"r2","texto":"Porque solo importan las especies más abundantes"},{"id":"r3","texto":"Porque los depredadores tope son siempre los más numerosos"}]},"solucion":{"valor":false,"explicacion":"Las especies clave, como los depredadores tope, suelen ser pocas y sin embargo cambian todo el ecosistema.","clave":["r1"]}},{"slug":"animales-1.s3.p14","orden":14,"grupo":"animales-1.s3.p14","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son ingenieros de ecosistemas? Marcá todos.","opciones":[{"id":"o1","texto":"Vizcacha"},{"id":"o2","texto":"Hornero"},{"id":"o3","texto":"Lombriz de tierra"},{"id":"o4","texto":"Castor"},{"id":"o5","texto":"Mariposa espejito"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todos modifican el ambiente. El castor también, aunque en Tierra del Fuego para mal. La mariposa poliniza, pero no construye ni transforma el hábitat."}},{"slug":"animales-1.s3.p15","orden":15,"grupo":"animales-1.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un depredador {{0}} como el yaguareté regula a los herbívoros; un {{1}} de ecosistemas modifica el ambiente y crea hábitats para otros.","banco":[{"id":"w1","texto":"tope"},{"id":"w2","texto":"ingeniero"},{"id":"w3","texto":"exótico"},{"id":"w4","texto":"turista"},{"id":"w5","texto":"productor"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para entender por qué algunas especies importan tanto."}}]},{"slug":"animales-1.s4","orden":4,"tipo":"leccion","titulo_es":"Adaptados a su lugar","bajada_es":"Guanacos, pingüinos, playeros y peludos: cómo el cuerpo y el comportamiento de los animales responden a su ambiente.","minutos":12,"pasos":[{"slug":"animales-1.s4.p1","orden":1,"grupo":"animales-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es una adaptación","cuerpo":["Una adaptación es una característica —del cuerpo, del funcionamiento o del comportamiento— que ayuda a un organismo a sobrevivir y reproducirse en su ambiente. Aparece a lo largo de muchas generaciones, por selección natural: los individuos con esa característica sobreviven y dejan más crías.","Las adaptaciones explican por qué cada ambiente tiene animales tan particulares."]},"solucion":{}},{"slug":"animales-1.s4.p2","orden":2,"grupo":"animales-1.s4.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ejemplos argentinos","cuerpo":["El guanaco tiene una sangre muy eficiente para captar oxígeno, lo que le permite vivir en la altura, y puede sobrevivir con poca agua en la estepa. El pingüino de Magallanes tiene plumas muy apretadas y grasa que lo aíslan del agua fría. El peludo (un tipo de armadillo) tiene un caparazón y garras para cavar. El ñandú, que no vuela, corre a gran velocidad por los pastizales."]},"solucion":{}},{"slug":"animales-1.s4.p3","orden":3,"grupo":"animales-1.s4.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con una adaptación a su ambiente.","izquierda":[{"id":"a1","texto":"Guanaco"},{"id":"a2","texto":"Pingüino de Magallanes"},{"id":"a3","texto":"Peludo"},{"id":"a4","texto":"Ñandú"}],"derecha":[{"id":"b1","texto":"Sangre eficiente para la altura y resistencia a la sequía"},{"id":"b2","texto":"Plumas apretadas y grasa contra el frío"},{"id":"b3","texto":"Garras para cavar madrigueras"},{"id":"b4","texto":"Patas largas para correr en el pastizal"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada adaptación responde a un desafío del ambiente: altura, frío, depredadores, distancias."}},{"slug":"animales-1.s4.p4","orden":4,"grupo":"animales-1.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una adaptación del cuerpo o del comportamiento?","grupos":[{"id":"g1","nombre":"Del cuerpo"},{"id":"g2","nombre":"Del comportamiento"}],"items":[{"id":"i1","texto":"El pelaje blanco de invierno de algunos animales de montaña"},{"id":"i2","texto":"Migrar en invierno"},{"id":"i3","texto":"Las garras del peludo"},{"id":"i4","texto":"Cazar de noche"},{"id":"i5","texto":"El pico largo del picaflor"},{"id":"i6","texto":"Enterrarse en las horas de más calor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las adaptaciones no son solo de forma: también son formas de actuar."}},{"slug":"animales-1.s4.p5","orden":5,"grupo":"animales-1.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Grandes viajeros","cuerpo":["Algunas aves hacen migraciones enormes. El playero rojizo viaja cada año unos 15.000 kilómetros en cada sentido, entre el Ártico de Canadá, donde se reproduce, y la costa de Tierra del Fuego, donde pasa el verano austral. En el camino necesita parar en ciertas playas para alimentarse.","Si esas paradas se degradan, la especie no puede completar su viaje. Por eso la conservación de aves migratorias requiere cooperación entre muchos países."],"destacado":{"valor":"≈ 15.000 km","texto":"recorre en cada sentido el playero rojizo entre el Ártico y Tierra del Fuego."}},"solucion":{}},{"slug":"animales-1.s4.p6","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 500 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"15.000 ÷ 500 = 30 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p6.v2","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 600 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"15.000 ÷ 600 = 25 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p6.v3","orden":6,"grupo":"animales-1.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un playero rojizo recorre 15.000 km en su migración a un promedio de 750 km por día de vuelo, ¿cuántos días de vuelo necesita?","unidad":"días","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"15.000 ÷ 750 = 20 días de vuelo, sin contar las paradas para comer. Por eso las playas de descanso son vitales."}},{"slug":"animales-1.s4.p7","orden":7,"grupo":"animales-1.s4.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué perder una playa de descanso afecta al playero rojizo.","items":[{"id":"i1","texto":"Se construye sobre una playa de descanso"},{"id":"i2","texto":"Los playeros no encuentran alimento en su viaje"},{"id":"i3","texto":"Llegan débiles o no llegan al destino"},{"id":"i4","texto":"Se reproducen menos y la población baja"},{"id":"i5","texto":"Los playeros aprenden a volar sin parar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una especie migratoria depende de una cadena de lugares. Si falla uno, falla todo el viaje."}},{"slug":"animales-1.s4.p8","orden":8,"grupo":"animales-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un animal puede \"decidir\" adaptarse a un ambiente nuevo en pocos días.","razones":[{"id":"r1","texto":"Porque las adaptaciones aparecen en muchas generaciones"},{"id":"r2","texto":"Porque los animales nunca cambian"},{"id":"r3","texto":"Porque las adaptaciones las eligen los individuos"}]},"solucion":{"valor":false,"explicacion":"Las adaptaciones aparecen por selección natural a lo largo de muchas generaciones. Un individuo puede cambiar su comportamiento, pero no su cuerpo, de un día para otro.","clave":["r1"]}},{"slug":"animales-1.s4.p9","orden":9,"grupo":"animales-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando el ambiente cambia rápido","cuerpo":["Las adaptaciones funcionan para el ambiente en el que evolucionaron. Si el ambiente cambia muy rápido —por el cambio climático, un desmonte o una especie invasora—, muchas especies no tienen tiempo de adaptarse. Algunas pueden moverse a otros lugares; otras, no."]},"solucion":{}},{"slug":"animales-1.s4.p10","orden":10,"grupo":"animales-1.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el cambio climático rápido es un problema para muchas especies?","opciones":[{"id":"o1","texto":"Porque cambia más rápido de lo que pueden adaptarse"},{"id":"o2","texto":"Porque todas las especies prefieren el frío extremo"},{"id":"o3","texto":"Porque los animales no sienten la temperatura"},{"id":"o4","texto":"Porque los animales solo viven en ciudades"}]},"solucion":{"clave":["o1"],"explicacion":"La selección natural necesita generaciones. Si el ambiente cambia en décadas, muchas especies quedan desacopladas.","por_opcion":{"o3":"La sienten, y justamente sus adaptaciones dependen de ella."}}},{"slug":"animales-1.s4.p11","orden":11,"grupo":"animales-1.s4.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pueden hacer las especies ante un ambiente que cambia? Marcá las posibilidades.","opciones":[{"id":"o1","texto":"Moverse a otras zonas más adecuadas"},{"id":"o2","texto":"Cambiar algunos comportamientos"},{"id":"o3","texto":"Adaptarse si hay tiempo y variación genética"},{"id":"o4","texto":"Cambiar su cuerpo en una semana a voluntad"},{"id":"o5","texto":"Detener el cambio del clima"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Moverse, cambiar comportamientos o adaptarse en generaciones. Si ninguna alcanza, la especie declina."}},{"slug":"animales-1.s4.p12","orden":12,"grupo":"animales-1.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El pingüino de Magallanes tiene plumas y grasa que lo aíslan del frío."},{"id":"s2","texto":"El guanaco se volvió resistente a la sequía porque quiso."},{"id":"s3","texto":"El playero rojizo migra miles de kilómetros."},{"id":"s4","texto":"Cualquier especie se adapta sin problema a cambios rápidos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las adaptaciones son lentas. El problema actual es la velocidad del cambio.","por_opcion":{"s2":"Las adaptaciones aparecen por selección natural en muchas generaciones, no por voluntad.","s4":"Muchas no tienen tiempo de adaptarse a cambios muy rápidos."}}},{"slug":"animales-1.s4.p13","orden":13,"grupo":"animales-1.s4.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un animal del Monte pasa las horas de más calor enterrado y sale a buscar comida de noche. ¿Qué tipo de adaptación es?","opciones":[{"id":"o1","texto":"Una adaptación de comportamiento"},{"id":"o2","texto":"Una adaptación de la forma del cuerpo"},{"id":"o3","texto":"Una costumbre que aprendió de las personas"},{"id":"o4","texto":"Una enfermedad que le impide salir de día"}]},"solucion":{"clave":["o1"],"explicacion":"Cambiar el horario de actividad es una de las adaptaciones más comunes en los desiertos.","por_opcion":{"o3":"Es una conducta heredada que lo ayuda a evitar el calor y perder menos agua."}}},{"slug":"animales-1.s4.p14","orden":14,"grupo":"animales-1.s4.p14","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué características ayudan a un animal a soportar el frío? Marcá todas.","opciones":[{"id":"o1","texto":"Una capa gruesa de grasa"},{"id":"o2","texto":"Pelaje o plumas densos"},{"id":"o3","texto":"Un cuerpo compacto"},{"id":"o4","texto":"Refugiarse en madrigueras"},{"id":"o5","texto":"Orejas enormes y finas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las orejas grandes y finas sirven para perder calor: son típicas de animales de desiertos cálidos, no de zonas frías."}},{"slug":"animales-1.s4.p15","orden":15,"grupo":"animales-1.s4.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las adaptaciones aparecen por selección {{0}} a lo largo de muchas {{1}}.","banco":[{"id":"w1","texto":"natural"},{"id":"w2","texto":"generaciones"},{"id":"w3","texto":"artificial"},{"id":"w4","texto":"semanas"},{"id":"w5","texto":"horas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Por eso los cambios muy rápidos del ambiente son tan peligrosos."}}]},{"slug":"animales-1.s5","orden":5,"tipo":"leccion","titulo_es":"Lo que la fauna hace por nosotros","bajada_es":"Polinizar, controlar plagas, limpiar y dispersar: el trabajo invisible de los animales.","minutos":12,"pasos":[{"slug":"animales-1.s5.p1","orden":1,"grupo":"animales-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Trabajo gratis","cuerpo":["Los animales prestan servicios que las personas necesitan: polinizan cultivos y plantas silvestres, controlan plagas, dispersan semillas que regeneran bosques, reciclan nutrientes y eliminan cadáveres. Si hubiera que reemplazar esos servicios con trabajo humano o máquinas, costaría fortunas, y muchas veces sería imposible."]},"solucion":{}},{"slug":"animales-1.s5.p2","orden":2,"grupo":"animales-1.s5.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con el servicio que presta.","izquierda":[{"id":"a1","texto":"Abejas nativas"},{"id":"a2","texto":"Murciélagos insectívoros"},{"id":"a3","texto":"Cóndor andino"},{"id":"a4","texto":"Zorzal"}],"derecha":[{"id":"b1","texto":"Polinizar flores y cultivos"},{"id":"b2","texto":"Comer insectos que pueden ser plagas"},{"id":"b3","texto":"Eliminar cadáveres de animales"},{"id":"b4","texto":"Dispersar semillas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro trabajos que hacen los animales sin cobrar."}},{"slug":"animales-1.s5.p3","orden":3,"grupo":"animales-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Murciélagos, lechuzas y plagas","cuerpo":["Un murciélago insectívoro puede comer cientos de insectos en una noche, incluidos mosquitos y polillas que dañan cultivos. Una familia de lechuzas del campanario puede cazar cientos o miles de roedores en un año. Por eso, en muchos campos se colocan cajas nido para lechuzas como control natural de roedores.","Matar murciélagos o lechuzas por miedo o superstición termina trayendo más plagas."]},"solucion":{}},{"slug":"animales-1.s5.p4","orden":4,"grupo":"animales-1.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué matar lechuzas puede traer más ratas.","items":[{"id":"i1","texto":"Se matan las lechuzas de un campo"},{"id":"i2","texto":"Hay menos depredadores de roedores"},{"id":"i3","texto":"Los roedores se multiplican"},{"id":"i4","texto":"Aumentan los daños en los cultivos y los riesgos sanitarios"},{"id":"i5","texto":"Las lechuzas traen las ratas al campo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un depredador natural es un control de plagas que trabaja todas las noches, gratis."}},{"slug":"animales-1.s5.p5","orden":5,"grupo":"animales-1.s5.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los murciélagos son animales dañinos que conviene eliminar.","razones":[{"id":"r1","texto":"Porque controlan insectos y dispersan semillas"},{"id":"r2","texto":"Porque todos los murciélagos se alimentan de sangre"},{"id":"r3","texto":"Porque los murciélagos no comen nada"}]},"solucion":{"valor":false,"explicacion":"La mayoría de los murciélagos de Argentina come insectos o frutos: controlan plagas y dispersan semillas. No hay que tocarlos con las manos, pero tampoco eliminarlos.","clave":["r1"]}},{"slug":"animales-1.s5.p6","orden":6,"grupo":"animales-1.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Carroñeros: el servicio de limpieza","cuerpo":["Los carroñeros, como el cóndor andino, los jotes, los caranchos y muchos insectos, comen cadáveres de animales. Así evitan que los restos se pudran durante semanas y que se propaguen enfermedades.","El cóndor andino, una de las aves voladoras más grandes del mundo, con unos 3 metros de envergadura, está amenazado sobre todo por envenenamientos: comen cadáveres con cebos tóxicos que se ponen para matar a otros animales."]},"solucion":{}},{"slug":"animales-1.s5.p7","orden":7,"grupo":"animales-1.s5.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un cebo envenenado mata cóndores.","items":[{"id":"i1","texto":"Se pone veneno en un cadáver para matar zorros o pumas"},{"id":"i2","texto":"Un grupo de cóndores come del cadáver"},{"id":"i3","texto":"Los cóndores se envenenan"},{"id":"i4","texto":"Mueren varios cóndores de una sola vez"},{"id":"i5","texto":"El veneno solo afecta a la especie buscada"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los venenos no eligen: matan a todo lo que come del cebo. Por eso están prohibidos y son tan dañinos."}},{"slug":"animales-1.s5.p8","orden":8,"grupo":"animales-1.s5.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué servicios prestan los carroñeros? Marcá todos.","opciones":[{"id":"o1","texto":"Eliminan cadáveres"},{"id":"o2","texto":"Reducen la propagación de enfermedades"},{"id":"o3","texto":"Reciclan nutrientes"},{"id":"o4","texto":"Polinizan flores"},{"id":"o5","texto":"Fabrican oxígeno"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Son el servicio de limpieza de la naturaleza. Sin ellos, los cadáveres duran mucho más y pueden contagiar enfermedades."}},{"slug":"animales-1.s5.p9","orden":9,"grupo":"animales-1.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El valor de lo que no se ve","cuerpo":["Según la plataforma científica IPBES, alrededor de las tres cuartas partes de los tipos de cultivos alimentarios del mundo dependen, al menos en parte, de la polinización animal. Muchos de ellos son frutas, verduras y frutos secos que aportan vitaminas y minerales esenciales.","Casi nunca vemos estos servicios en acción, y por eso es fácil subestimarlos. Se notan cuando faltan."],"destacado":{"valor":"≈ 75 %","texto":"de los tipos de cultivos alimentarios del mundo dependen en parte de la polinización animal."}},"solucion":{}},{"slug":"animales-1.s5.p10","orden":10,"grupo":"animales-1.s5.p10","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los tipos de cultivos alimentarios del mundo depende, al menos en parte, de polinizadores animales.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Alrededor de tres de cada cuatro. No todos dependen del mismo modo, pero sin polinizadores muchas frutas y verduras rendirían mucho menos."}},{"slug":"animales-1.s5.p11","orden":11,"grupo":"animales-1.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué medida es mejor para controlar roedores en un campo a largo plazo?","opciones":[{"id":"o1","texto":"Instalar cajas nido para lechuzas"},{"id":"o2","texto":"Poner cebos envenenados por todo el campo"},{"id":"o3","texto":"Matar a los zorros y las lechuzas que hay"},{"id":"o4","texto":"Quemar los pastizales cercanos"}]},"solucion":{"clave":["o1"],"explicacion":"Aliarse con los depredadores naturales es barato, permanente y no envenena a otras especies.","por_opcion":{"o3":"Sacarías justamente a los depredadores que controlan a los roedores."}}},{"slug":"animales-1.s5.p12","orden":12,"grupo":"animales-1.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las lechuzas cazan muchos roedores."},{"id":"s2","texto":"Hay que matar a los murciélagos porque traen plagas."},{"id":"s3","texto":"El cóndor andino come cadáveres."},{"id":"s4","texto":"Poner veneno en un cadáver solo mata al zorro que se busca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La fauna trabaja para nosotros. Atacarla suele salir caro.","por_opcion":{"s2":"Los murciélagos insectívoros comen insectos que pueden ser plagas.","s4":"Los cebos envenenados matan a todo lo que come de ellos, incluidos cóndores."}}},{"slug":"animales-1.s5.p13","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 200 murciélagos insectívoros come en promedio 300 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":60000,"tolerancia":1200,"explicacion":"200 × 300 = 60.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p13.v2","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 500 murciélagos insectívoros come en promedio 500 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":250000,"tolerancia":5000,"explicacion":"500 × 500 = 250.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p13.v3","orden":13,"grupo":"animales-1.s5.p13","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una colonia de 1.000 murciélagos insectívoros come en promedio 400 insectos por murciélago por noche. ¿Cuántos insectos come la colonia en una noche?","unidad":"insectos","decimales":0},"solucion":{"valor":400000,"tolerancia":8000,"explicacion":"1.000 × 400 = 400.000 insectos por noche. En un verano, decenas de millones: un control de plagas gratuito."}},{"slug":"animales-1.s5.p14","orden":14,"grupo":"animales-1.s5.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá la envergadura (de punta a punta de las alas) de un cóndor andino adulto.","min":0.5,"max":6,"paso":0.1,"unidad":"m","escala":"lineal"},"solucion":{"valor":3,"banda":"lineal","explicacion":"Alrededor de 3 metros. Es una de las aves voladoras más grandes del mundo, y aprovecha las corrientes de aire para planear horas sin aletear."}},{"slug":"animales-1.s5.p15","orden":15,"grupo":"animales-1.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los murciélagos y las lechuzas controlan {{0}}; los cóndores eliminan {{1}}; y las abejas {{2}} cultivos.","banco":[{"id":"w1","texto":"plagas"},{"id":"w2","texto":"cadáveres"},{"id":"w3","texto":"polinizan"},{"id":"w4","texto":"semillas"},{"id":"w5","texto":"nidos"},{"id":"w6","texto":"envenenan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres servicios que la fauna presta gratis todos los días."}}]},{"slug":"animales-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la trama de la vida","bajada_es":"Biodiversidad, redes tróficas, especies clave, adaptaciones y servicios, mezclados.","minutos":8,"pasos":[{"slug":"animales-1.s6.p1","orden":1,"grupo":"animales-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La trama de la vida». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la laguna de los Álamos","bajada_es":"En una laguna pampeana algo se desequilibró. Con los datos, encontrá la causa y proponé qué hacer.","minutos":10,"pasos":[{"slug":"animales-1.s7.p1","orden":1,"grupo":"animales-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La laguna","cuerpo":["Los vecinos de una laguna pampeana notan que el agua está cada vez más turbia y verde, y que casi no se ven tarariras. Desde hace tres años, un grupo pesca con redes todas las tarariras que encuentra para venderlas. Los pescadores deportivos cuentan que hay \"mojarras por todos lados\".","Un estudio de la universidad midió la cantidad de mojarras: se triplicó en tres años. El plancton que filtra el agua bajó a la mitad."]},"solucion":{}},{"slug":"animales-1.s7.p2","orden":2,"grupo":"animales-1.s7.p2","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena más probable de lo que pasó en la laguna.","items":[{"id":"i1","texto":"Se pescan casi todas las tarariras"},{"id":"i2","texto":"Las mojarras pierden a su principal depredador"},{"id":"i3","texto":"Las mojarras se triplican"},{"id":"i4","texto":"Comen mucho del plancton que filtra el agua"},{"id":"i5","texto":"Crecen las algas y el agua se pone turbia y verde"},{"id":"i6","texto":"Las tarariras enturbian el agua al desaparecer"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cascada trófica: un cambio arriba de la red baja hasta el color del agua."}},{"slug":"animales-1.s7.p3","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 2.000 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":6000,"tolerancia":120,"explicacion":"2.000 × 3 = 6.000. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p3.v2","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 5.000 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"5.000 × 3 = 15.000. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p3.v3","orden":3,"grupo":"animales-1.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si había 1.500 mojarras por hectárea y la cantidad se triplicó, ¿cuántas hay ahora por hectárea?","unidad":"mojarras por hectárea","decimales":0},"solucion":{"valor":4500,"tolerancia":90,"explicacion":"1.500 × 3 = 4.500. Sin su depredador, la población crece hasta que otro factor la limita."}},{"slug":"animales-1.s7.p4","orden":4,"grupo":"animales-1.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la medida más directa para empezar a recuperar la laguna?","opciones":[{"id":"o1","texto":"Regular la pesca de tarariras"},{"id":"o2","texto":"Echar productos químicos para matar las algas"},{"id":"o3","texto":"Pescar todas las mojarras con redes"},{"id":"o4","texto":"Traer peces exóticos para que coman mojarras"}]},"solucion":{"clave":["o1"],"explicacion":"Atacar la causa: devolverle a la red su depredador. Los químicos y los exóticos suelen traer problemas nuevos.","por_opcion":{"o3":"Ayudaría un tiempo, pero sin el depredador las mojarras vuelven a crecer."}}},{"slug":"animales-1.s7.p5","orden":5,"grupo":"animales-1.s7.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Traer un pez exótico para que coma mojarras es una buena solución.","razones":[{"id":"r1","texto":"Porque puede volverse invasor y causar nuevos daños"},{"id":"r2","texto":"Porque los peces exóticos no comen"},{"id":"r3","texto":"Porque las mojarras son exóticas"}]},"solucion":{"valor":false,"explicacion":"Un pez exótico puede volverse invasor y causar daños mayores. Mejor recuperar al depredador nativo, la tararira.","clave":["r1"]}},{"slug":"animales-1.s7.p6","orden":6,"grupo":"animales-1.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de los vecinos.","grupos":[{"id":"g1","nombre":"Ayudan a recuperar la laguna"},{"id":"g2","nombre":"No ayudan o empeoran"}],"items":[{"id":"i1","texto":"Veda de pesca de tarariras por dos temporadas"},{"id":"i2","texto":"Echar alguicidas al agua"},{"id":"i3","texto":"Talla mínima para las tarariras que se pescan"},{"id":"i4","texto":"Soltar peces de acuario"},{"id":"i5","texto":"Controlar los vuelcos de fertilizantes de los campos cercanos"},{"id":"i6","texto":"Pescar más tarariras antes de que se prohíba"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las buenas medidas atacan la causa y cuidan la red. Las malas tapan síntomas o agregan problemas."}},{"slug":"animales-1.s7.p7","orden":7,"grupo":"animales-1.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos conviene seguir midiendo para saber si la laguna se recupera? Marcá todos.","opciones":[{"id":"o1","texto":"Cantidad de tarariras"},{"id":"o2","texto":"Cantidad de mojarras"},{"id":"o3","texto":"Turbidez del agua"},{"id":"o4","texto":"Cantidad de plancton"},{"id":"o5","texto":"Cantidad de autos en la costanera"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Medir las piezas de la red permite ver si la cascada se revierte. Como en el tronco: medir antes y después."}},{"slug":"animales-1.s7.p8","orden":8,"grupo":"animales-1.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La municipalidad publica su plan. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Habrá veda de pesca de tarariras durante dos temporadas."},{"id":"s2","texto":"Como el problema son las algas, las mataremos con químicos y listo."},{"id":"s3","texto":"La universidad seguirá midiendo peces y plancton."},{"id":"s4","texto":"Soltaremos truchas para que coman mojarras."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan ataca la causa, respeta la red y mide los resultados.","por_opcion":{"s2":"Las algas son un síntoma; la causa es la falta de depredadores. Los químicos dañan toda la red.","s4":"Traer un pez exótico puede generar una invasión."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-2","rama":"animales","orden":2,"nivel":1,"titulo_es":"Vecinos silvestres","bajada_es":"Horneros, comadrejas, murciélagos y carpinchos: cómo convivir con la fauna de la ciudad, qué hacer si encontrás un animal y cómo cuidar a las mascotas sin dañar a nadie.","objetivos_es":["Reconocer especies silvestres nativas y exóticas de las ciudades argentinas","Aplicar pautas de convivencia y actuar bien ante un animal silvestre","Evaluar el impacto de perros y gatos sobre la fauna","Explicar por qué no se liberan mascotas exóticas y qué es el tráfico de fauna","Proponer medidas para ciudades más amigables con la fauna"],"repasa":["animales-1","tronco-3"],"requiere_tronco":1,"fuentes":["protocolo-fauna-cba","red-centros-rescate","crfs-ecoparque","gcba-cinco-libertades","ley-22421-fauna","cites","conicet-carpinchos","loss-2013-gatos","loss-2014-vidrios","invasoras-mayds","aves-argentinas"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-2.s1","orden":1,"tipo":"leccion","titulo_es":"Quién vive en la ciudad","bajada_es":"Aves, mamíferos, reptiles e insectos que comparten el barrio con nosotros, nativos y exóticos.","minutos":11,"pasos":[{"slug":"animales-2.s1.p1","orden":1,"grupo":"animales-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una ciudad llena de vida","cuerpo":["Las ciudades no son solo cemento: en plazas, jardines, terrenos baldíos, arroyos y hasta balcones viven muchas especies. En las ciudades argentinas son comunes aves nativas como el hornero —el ave nacional—, el benteveo, el zorzal colorado, la calandria, el chingolo, el tero y la paloma picazuró.","También hay mamíferos nativos que pasan desapercibidos, como la comadreja overa, un marsupial nocturno, y muchas especies de murciélagos. Y lagartijas, sapos, mariposas, abejas nativas y cientos de insectos."]},"solucion":{}},{"slug":"animales-2.s1.p2","orden":2,"grupo":"animales-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos animales son nativos y comunes en ciudades argentinas? Marcá todos.","opciones":[{"id":"o1","texto":"Hornero"},{"id":"o2","texto":"Benteveo"},{"id":"o3","texto":"Comadreja overa"},{"id":"o4","texto":"Zorzal colorado"},{"id":"o5","texto":"Canguro"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Mucha fauna nativa vive entre nosotros. El canguro, claro, es de Australia."}},{"slug":"animales-2.s1.p3","orden":3,"grupo":"animales-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los que llegaron con nosotros","cuerpo":["Otras especies urbanas son exóticas, traídas por personas. El gorrión llegó de Europa en el siglo XIX; la paloma doméstica, también. El estornino pinto, un ave europea, se liberó en Buenos Aires hacia fines de los años ochenta y se expandió por buena parte del país, compitiendo con aves nativas por los huecos donde anidan.","Las ratas y los ratones domésticos también son exóticos y viajaron con las personas en barcos."]},"solucion":{}},{"slug":"animales-2.s1.p4","orden":4,"grupo":"animales-2.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es nativa de Argentina o exótica?","grupos":[{"id":"g1","nombre":"Nativa"},{"id":"g2","nombre":"Exótica"}],"items":[{"id":"i1","texto":"Hornero"},{"id":"i2","texto":"Gorrión"},{"id":"i3","texto":"Paloma picazuró"},{"id":"i4","texto":"Paloma doméstica"},{"id":"i5","texto":"Tero"},{"id":"i6","texto":"Estornino pinto"},{"id":"i7","texto":"Comadreja overa"},{"id":"i8","texto":"Rata parda"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Que un animal sea común en la ciudad no dice si es nativo. Varias de las especies más vistas vinieron con las personas."}},{"slug":"animales-2.s1.p5","orden":5,"grupo":"animales-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La comadreja overa es un animal peligroso que conviene eliminar de los jardines.","razones":[{"id":"r1","texto":"Porque es un marsupial nativo que ayuda a controlar plagas"},{"id":"r2","texto":"Porque la comadreja es una rata grande"},{"id":"r3","texto":"Porque la comadreja ataca a las personas para comer"}]},"solucion":{"valor":false,"explicacion":"Es un marsupial nativo, tímido, que come insectos, caracoles, frutos y hasta ratones. Ayuda a controlar plagas. Si se siente amenazada, se hace la muerta.","clave":["r1"]}},{"slug":"animales-2.s1.p6","orden":6,"grupo":"animales-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciudades sobre humedales","cuerpo":["Muchas ciudades crecen sobre ambientes naturales, como humedales. Cuando en 2021 los carpinchos se hicieron famosos en un barrio cerrado del norte del conurbano, especialistas del CONICET recordaron que ese barrio se construyó sobre el humedal donde los carpinchos vivían desde siempre: no eran ellos los invasores.","La convivencia con fauna silvestre en la ciudad es, muchas veces, la consecuencia de haber ocupado su ambiente."]},"solucion":{}},{"slug":"animales-2.s1.p7","orden":7,"grupo":"animales-2.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué aparecieron tantos carpinchos en un barrio nuevo.","items":[{"id":"i1","texto":"Se construye un barrio sobre un humedal"},{"id":"i2","texto":"Los carpinchos pierden gran parte de su hábitat"},{"id":"i3","texto":"Quedan lagunas y céspedes con agua y pasto"},{"id":"i4","texto":"Los carpinchos siguen viviendo en lo que queda"},{"id":"i5","texto":"Aparecen conflictos con los vecinos"},{"id":"i6","texto":"Los carpinchos llegaron desde otro país"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los carpinchos no invadieron el barrio: el barrio se construyó en su casa."}},{"slug":"animales-2.s1.p8","orden":8,"grupo":"animales-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal urbano con algo que lo caracteriza.","izquierda":[{"id":"a1","texto":"Hornero"},{"id":"a2","texto":"Tero"},{"id":"a3","texto":"Murciélago"},{"id":"a4","texto":"Comadreja overa"}],"derecha":[{"id":"b1","texto":"Construye su nido de barro"},{"id":"b2","texto":"Grita fuerte cuando alguien se acerca a su nido"},{"id":"b3","texto":"Caza insectos de noche"},{"id":"b4","texto":"Lleva a sus crías en una bolsa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer a los vecinos ayuda a entenderlos y a no temerles."}},{"slug":"animales-2.s1.p9","orden":9,"grupo":"animales-2.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el estornino pinto es un problema para aves nativas?","opciones":[{"id":"o1","texto":"Porque compite con ellas por los huecos para anidar"},{"id":"o2","texto":"Porque se come todas las semillas de los árboles"},{"id":"o3","texto":"Porque ataca a las personas en las plazas"},{"id":"o4","texto":"Porque destruye los nidos de hornero con el pico"}]},"solucion":{"clave":["o1"],"explicacion":"Muchas aves nativas anidan en huecos. Un competidor exótico abundante les quita lugar.","por_opcion":{"o3":"No es peligroso para las personas: el problema es su competencia con aves nativas."}}},{"slug":"animales-2.s1.p10","orden":10,"grupo":"animales-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El hornero es el ave nacional."},{"id":"s2","texto":"Los gorriones son aves nativas de la pampa."},{"id":"s3","texto":"En la ciudad viven murciélagos."},{"id":"s4","texto":"Los carpinchos invadieron el barrio desde afuera."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber quién es quién cambia cómo miramos los conflictos con la fauna.","por_opcion":{"s2":"Son exóticos: llegaron de Europa en el siglo XIX.","s4":"El barrio se construyó sobre el humedal donde ya vivían."}}},{"slug":"animales-2.s1.p11","orden":11,"grupo":"animales-2.s1.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La cotorra, tan común en las ciudades, es una especie exótica en Argentina.","razones":[{"id":"r1","texto":"Porque es nativa de la región, aunque sea invasora en otros países"},{"id":"r2","texto":"Porque llegó de Europa con los barcos"},{"id":"r3","texto":"Porque es un ave de Australia"}]},"solucion":{"valor":false,"explicacion":"Es nativa de Argentina y la región. Se volvió muy abundante en ciudades y cultivos, y en otros países, como España, sí es una invasora.","clave":["r1"]}},{"slug":"animales-2.s1.p12","orden":12,"grupo":"animales-2.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué lugares de una ciudad puede vivir fauna silvestre? Marcá todos.","opciones":[{"id":"o1","texto":"Plazas con árboles"},{"id":"o2","texto":"Arroyos y sus orillas"},{"id":"o3","texto":"Balcones con plantas"},{"id":"o4","texto":"Terrenos baldíos con vegetación"},{"id":"o5","texto":"Solo en zoológicos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fauna urbana aprovecha cualquier rincón con agua, refugio y comida."}},{"slug":"animales-2.s1.p13","orden":13,"grupo":"animales-2.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El {{0}} es el ave nacional; el gorrión y la paloma doméstica son {{1}}; y la comadreja overa es un {{2}} nativo.","banco":[{"id":"w1","texto":"hornero"},{"id":"w2","texto":"exóticos"},{"id":"w3","texto":"marsupial"},{"id":"w4","texto":"cóndor"},{"id":"w5","texto":"nativos"},{"id":"w6","texto":"roedor"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres vecinos del barrio, bien presentados."}},{"slug":"animales-2.s1.p14","orden":14,"grupo":"animales-2.s1.p14","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos lugares de la ciudad según cuánta fauna silvestre suelen albergar, de más a menos.","items":[{"id":"i1","texto":"Reserva ecológica con humedal"},{"id":"i2","texto":"Plaza grande con árboles y arbustos nativos"},{"id":"i3","texto":"Vereda arbolada"},{"id":"i4","texto":"Estacionamiento de cemento"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Más hábitat natural, más fauna. Pero hasta una vereda con árboles hace una diferencia.","valores":{"i1":"mucha","i2":"bastante","i3":"poca","i4":"casi nada"}}}]},{"slug":"animales-2.s2","orden":2,"tipo":"leccion","titulo_es":"Convivir sin dañar","bajada_es":"No alimentar, no capturar, no molestar, y qué hacer si encontrás un pichón o un animal herido.","minutos":11,"pasos":[{"slug":"animales-2.s2.p1","orden":1,"grupo":"animales-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las reglas básicas","cuerpo":["Convivir con la fauna silvestre tiene reglas simples: no alimentarla (se vuelve dependiente, pierde el miedo y puede enfermar con comida humana), no capturarla ni tenerla como mascota, no molestarla en sus nidos o refugios y mantener a perros y gatos controlados.","La fauna silvestre está protegida por ley: la Ley 22.421 de conservación de la fauna silvestre prohíbe cazarla, capturarla o comerciarla sin autorización."]},"solucion":{}},{"slug":"animales-2.s2.p2","orden":2,"grupo":"animales-2.s2.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene hacer para convivir con la fauna silvestre? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Observarla a distancia"},{"id":"o2","texto":"No darle comida"},{"id":"o3","texto":"Mantener a perros y gatos controlados"},{"id":"o4","texto":"No tocar nidos ni crías"},{"id":"o5","texto":"Llevarse un pichón a casa para criarlo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fauna silvestre está mejor en libertad, sin depender de las personas."}},{"slug":"animales-2.s2.p3","orden":3,"grupo":"animales-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué no alimentar","cuerpo":["Darles comida a animales silvestres parece un gesto amable, pero trae problemas: pierden el miedo a las personas y pueden volverse agresivos o terminar atropellados; se concentran muchos en un lugar y se contagian enfermedades; y la comida humana, como el pan, les hace mal.","En varias ciudades, los carpinchos o los zorros alimentados por la gente terminaron en conflictos que los perjudicaron a ellos."]},"solucion":{}},{"slug":"animales-2.s2.p4","orden":4,"grupo":"animales-2.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué alimentar a un zorro puede terminar mal para él.","items":[{"id":"i1","texto":"Personas alimentan a un zorro en una ruta"},{"id":"i2","texto":"El zorro pierde el miedo y se acerca a los autos"},{"id":"i3","texto":"Espera comida al costado de la ruta"},{"id":"i4","texto":"Aumenta el riesgo de que lo atropellen"},{"id":"i5","texto":"El zorro aprende a cruzar la ruta sin peligro"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo que parece amabilidad puede convertirse en una trampa. En parques nacionales, alimentar fauna está prohibido."}},{"slug":"animales-2.s2.p5","orden":5,"grupo":"animales-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Darles pan a los patos de una laguna es bueno para ellos.","razones":[{"id":"r1","texto":"Porque el pan no es su alimento y puede enfermarlos"},{"id":"r2","texto":"Porque los patos no comen nada"},{"id":"r3","texto":"Porque el pan purifica el agua de la laguna"}]},"solucion":{"valor":false,"explicacion":"El pan no les aporta lo que necesitan y puede enfermarlos; además, el pan que sobra se pudre en el agua. Mejor observarlos sin alimentar.","clave":["r1"]}},{"slug":"animales-2.s2.p6","orden":6,"grupo":"animales-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El pichón en el suelo","cuerpo":["En primavera, es común encontrar un pichón de ave en el suelo. Muchas veces es un volantón: un pichón con plumas que está aprendiendo a volar y cuyos padres siguen cerca alimentándolo. En ese caso, lo mejor es dejarlo tranquilo, alejar a perros y gatos y observar de lejos.","Si es un pichón sin plumas o casi sin plumas, que se cayó del nido, se puede intentar devolverlo al nido si se lo ve. Si está herido o en peligro, conviene comunicarse con un centro de rescate de fauna o la autoridad ambiental. Nunca hay que darle agua ni comida por la boca: puede ahogarse."]},"solucion":{}},{"slug":"animales-2.s2.p7","orden":7,"grupo":"animales-2.s2.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué hacer si encontrás un pichón con plumas en el suelo.","items":[{"id":"i1","texto":"Observar de lejos si los padres están cerca"},{"id":"i2","texto":"Alejar a perros y gatos"},{"id":"i3","texto":"Dejarlo en el lugar si no corre peligro"},{"id":"i4","texto":"Si está herido, contactar a un centro de rescate"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La mayoría de los volantones no necesitan ayuda: sus padres los siguen cuidando."}},{"slug":"animales-2.s2.p8","orden":8,"grupo":"animales-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conviene hacer en cada caso?","grupos":[{"id":"g1","nombre":"Dejarlo donde está y observar"},{"id":"g2","nombre":"Contactar a un centro de rescate o la autoridad"}],"items":[{"id":"i1","texto":"Pichón con plumas saltando en el pasto"},{"id":"i2","texto":"Lechuza con un ala rota"},{"id":"i3","texto":"Tero defendiendo su nido en un parque"},{"id":"i4","texto":"Tortuga atropellada en la ruta"},{"id":"i5","texto":"Zorro enredado en un alambre"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Un animal sano en su ambiente no necesita rescate. Uno herido sí, pero con especialistas."}},{"slug":"animales-2.s2.p9","orden":9,"grupo":"animales-2.s2.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Encontraste un pichón sin plumas debajo de un árbol y ves el nido. ¿Qué hacés?","opciones":[{"id":"o1","texto":"Intentar devolverlo al nido con cuidado"},{"id":"o2","texto":"Llevarlo a casa y darle leche con una jeringa"},{"id":"o3","texto":"Darle agua por el pico para que se hidrate"},{"id":"o4","texto":"Dejarlo al sol para que se caliente"}]},"solucion":{"clave":["o1"],"explicacion":"Si el nido está a mano, devolverlo es lo mejor. Que lo toques no hace que los padres lo rechacen: esa es una creencia falsa.","por_opcion":{"o3":"Nunca se da agua ni comida por la boca: puede ahogarse."}}},{"slug":"animales-2.s2.p10","orden":10,"grupo":"animales-2.s2.p10","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si tocás un pichón, sus padres lo van a rechazar por el olor.","razones":[{"id":"r1","texto":"Porque la mayoría de las aves no rechaza a sus crías por el olor"},{"id":"r2","texto":"Porque las aves no tienen crías"},{"id":"r3","texto":"Porque los pichones no tienen olor"}]},"solucion":{"valor":false,"explicacion":"Es una creencia muy extendida pero falsa para la mayoría de las aves: no rechazan a sus crías por el olor humano. Se puede devolver un pichón al nido.","clave":["r1"]}},{"slug":"animales-2.s2.p11","orden":11,"grupo":"animales-2.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada situación con quién conviene contactar.","izquierda":[{"id":"a1","texto":"Animal silvestre herido"},{"id":"a2","texto":"Venta de aves silvestres en una feria"},{"id":"a3","texto":"Serpiente dentro de una casa"},{"id":"a4","texto":"Carpinchos en el barrio"}],"derecha":[{"id":"b1","texto":"Centro de rescate de fauna o autoridad ambiental"},{"id":"b2","texto":"Autoridad de fauna para denunciar"},{"id":"b3","texto":"Bomberos o la autoridad ambiental local"},{"id":"b4","texto":"Nadie: observarlos a distancia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Saber a quién llamar evita que las personas actúen solas y dañen al animal o se lastimen."}},{"slug":"animales-2.s2.p12","orden":12,"grupo":"animales-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un grupo de vecinos y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Si encontrás un volantón, alejá al gato y observá."},{"id":"s2","texto":"Si encontrás un pichón, dale leche con una jeringa."},{"id":"s3","texto":"No alimentes a los carpinchos."},{"id":"s4","texto":"Si ves una comadreja, espantala o matala porque es peligrosa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La buena voluntad necesita buena información.","por_opcion":{"s2":"Nunca se da nada por la boca, y la leche les hace mal.","s4":"Es un marsupial nativo inofensivo que ayuda a controlar plagas."}}},{"slug":"animales-2.s2.p13","orden":13,"grupo":"animales-2.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"A la fauna silvestre no hay que {{0}} ni capturarla; la Ley {{1}} la protege; y ante un animal herido hay que llamar a un centro de {{2}}.","banco":[{"id":"w1","texto":"alimentarla"},{"id":"w2","texto":"22.421"},{"id":"w3","texto":"rescate"},{"id":"w4","texto":"fotografiarla"},{"id":"w5","texto":"25.675"},{"id":"w6","texto":"compras"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas para convivir con la fauna sin dañarla."}}]},{"slug":"animales-2.s3","orden":3,"tipo":"leccion","titulo_es":"Mascotas y fauna","bajada_es":"Gatos que cazan, perros sueltos y la tenencia responsable: cómo cuidar a las mascotas sin dañar a la fauna.","minutos":11,"pasos":[{"slug":"animales-2.s3.p1","orden":1,"grupo":"animales-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las cinco libertades","cuerpo":["Tener una mascota es una responsabilidad. El bienestar animal se suele resumir en cinco libertades: que viva libre de hambre y sed; libre de incomodidad; libre de dolor, lesiones y enfermedades; libre para expresar su comportamiento normal; y libre de miedo y angustia.","La tenencia responsable también incluye la vacunación, la castración para evitar camadas no deseadas y el control para que la mascota no dañe a otras personas ni a la fauna."]},"solucion":{}},{"slug":"animales-2.s3.p2","orden":2,"grupo":"animales-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas son parte de las cinco libertades del bienestar animal? Marcá todas.","opciones":[{"id":"o1","texto":"Libre de hambre y sed"},{"id":"o2","texto":"Libre de dolor, lesiones y enfermedades"},{"id":"o3","texto":"Libre para expresar su comportamiento normal"},{"id":"o4","texto":"Libre de miedo y angustia"},{"id":"o5","texto":"Libre de tener que ir al veterinario"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Ir al veterinario es justamente parte de mantenerla libre de dolor y enfermedades."}},{"slug":"animales-2.s3.p3","orden":3,"grupo":"animales-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los gatos, cazadores","cuerpo":["Los gatos domésticos son cazadores eficientes, aunque estén bien alimentados. Un estudio publicado en Nature Communications estimó que en Estados Unidos los gatos que andan sueltos matan entre 1.300 y 4.000 millones de aves por año, además de muchísimos pequeños mamíferos. En islas, los gatos contribuyeron a la extinción de varias especies.","Tener el gato adentro, sobre todo al amanecer y al atardecer, o en un patio cerrado, reduce mucho su impacto sobre la fauna y también lo protege de accidentes y enfermedades."],"destacado":{"valor":"1.300-4.000 millones","texto":"de aves por año matarían los gatos sueltos en Estados Unidos, según un estudio de 2013."}},"solucion":{}},{"slug":"animales-2.s3.p4","orden":4,"grupo":"animales-2.s3.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un gato bien alimentado no caza.","razones":[{"id":"r1","texto":"Porque cazar es un instinto que no depende del hambre"},{"id":"r2","texto":"Porque los gatos solo comen alimento balanceado"},{"id":"r3","texto":"Porque los gatos no pueden atrapar aves"}]},"solucion":{"valor":false,"explicacion":"La caza es un instinto independiente del hambre. Un gato bien alimentado puede cazar aves y otros animales igual.","clave":["r1"]}},{"slug":"animales-2.s3.p5","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 1.000 gatos que salen a la calle y cada uno caza en promedio 10 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"1.000 × 10 = 10.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p5.v2","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 5.000 gatos que salen a la calle y cada uno caza en promedio 8 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":40000,"tolerancia":800,"explicacion":"5.000 × 8 = 40.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p5.v3","orden":5,"grupo":"animales-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio hay 200 gatos que salen a la calle y cada uno caza en promedio 15 aves por año. ¿Cuántas aves cazan en total por año?","unidad":"aves","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"200 × 15 = 3.000 aves por año. Poco por gato, mucho por barrio: la misma lógica del stand-by o de la basura."}},{"slug":"animales-2.s3.p6","orden":6,"grupo":"animales-2.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un gato suelto afecta a las aves del barrio.","items":[{"id":"i1","texto":"Un gato sale libremente al jardín y la plaza"},{"id":"i2","texto":"Caza pichones y aves adultas"},{"id":"i3","texto":"Menos aves llegan a reproducirse"},{"id":"i4","texto":"Baja la población de aves del barrio"},{"id":"i5","texto":"El gato ahuyenta a las aves hacia lugares mejores"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un efecto chico multiplicado por muchos gatos y muchos años."}},{"slug":"animales-2.s3.p7","orden":7,"grupo":"animales-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Perros sueltos","cuerpo":["Los perros sueltos o en jauría también afectan a la fauna: persiguen y matan aves que anidan en el suelo, como teros, ñandúes o pingüinos en la costa patagónica, atacan a ciervos, zorros o vizcachas, y transmiten enfermedades a animales silvestres.","En áreas naturales, reservas y playas con fauna, los perros tienen que ir con correa, y en muchos parques nacionales no están permitidos."]},"solucion":{}},{"slug":"animales-2.s3.p8","orden":8,"grupo":"animales-2.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica protege a la fauna o la pone en riesgo?","grupos":[{"id":"g1","nombre":"Protege a la fauna"},{"id":"g2","nombre":"La pone en riesgo"}],"items":[{"id":"i1","texto":"Llevar al perro con correa en la reserva"},{"id":"i2","texto":"Soltar al perro en una playa con colonia de aves"},{"id":"i3","texto":"Castrar a perros y gatos"},{"id":"i4","texto":"Abandonar camadas en un terreno baldío"},{"id":"i5","texto":"Tener al gato adentro de noche"},{"id":"i6","texto":"Dejar comida para gatos en una plaza con aves"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La tenencia responsable cuida a la mascota y a la fauna al mismo tiempo."}},{"slug":"animales-2.s3.p9","orden":9,"grupo":"animales-2.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la castración de perros y gatos ayuda a la fauna silvestre?","opciones":[{"id":"o1","texto":"Porque evita camadas que terminan sueltas"},{"id":"o2","texto":"Porque los animales castrados no pueden correr"},{"id":"o3","texto":"Porque los castrados dejan de tener instinto de caza"},{"id":"o4","texto":"Porque así se vuelven animales silvestres"}]},"solucion":{"clave":["o1"],"explicacion":"Menos camadas no deseadas, menos animales abandonados y menos presión sobre la fauna.","por_opcion":{"o3":"El instinto de caza puede seguir; lo que se evita es la sobrepoblación de animales sueltos."}}},{"slug":"animales-2.s3.p10","orden":10,"grupo":"animales-2.s3.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada práctica de tenencia responsable con su beneficio.","izquierda":[{"id":"a1","texto":"Vacunar"},{"id":"a2","texto":"Castrar"},{"id":"a3","texto":"Correa en áreas naturales"},{"id":"a4","texto":"Gato adentro de noche"}],"derecha":[{"id":"b1","texto":"Evitar enfermedades que pueden pasar a la fauna"},{"id":"b2","texto":"Evitar camadas no deseadas"},{"id":"b3","texto":"Evitar persecuciones de fauna"},{"id":"b4","texto":"Reducir la caza de aves"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada práctica protege a la mascota, a las personas y a la fauna."}},{"slug":"animales-2.s3.p11","orden":11,"grupo":"animales-2.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los gatos pueden cazar aunque estén bien alimentados."},{"id":"s2","texto":"Los perros sueltos no molestan a la fauna porque son domésticos."},{"id":"s3","texto":"Castrar evita camadas no deseadas."},{"id":"s4","texto":"Soltar al perro en una playa con aves es inofensivo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Querer a las mascotas incluye evitar que dañen a otros animales.","por_opcion":{"s2":"Los perros sueltos persiguen y matan fauna silvestre.","s4":"Puede perseguir aves que anidan y destruir nidos."}}},{"slug":"animales-2.s3.p12","orden":12,"grupo":"animales-2.s3.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los gatos cazan aunque estén bien {{0}}; en reservas, los perros van con {{1}}; y la {{2}} evita camadas no deseadas.","banco":[{"id":"w1","texto":"alimentados"},{"id":"w2","texto":"correa"},{"id":"w3","texto":"castración"},{"id":"w4","texto":"vacunados"},{"id":"w5","texto":"bozal"},{"id":"w6","texto":"vacuna"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas de tenencia responsable pensando en la fauna."}},{"slug":"animales-2.s3.p13","orden":13,"grupo":"animales-2.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas por cuánto reducen la caza de aves por parte de un gato, de más a menos.","items":[{"id":"i1","texto":"Tenerlo siempre adentro o en patio cerrado"},{"id":"i2","texto":"Tenerlo adentro al amanecer, al atardecer y de noche"},{"id":"i3","texto":"Ponerle un collar con cascabel"},{"id":"i4","texto":"Dejarlo salir cuando quiera"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las horas de luz baja son las de mayor actividad de las aves y de caza del gato.","valores":{"i1":"casi la elimina","i2":"la reduce mucho","i3":"la reduce algo","i4":"no la reduce"}}}]},{"slug":"animales-2.s4","orden":4,"tipo":"leccion","titulo_es":"Nunca liberar, nunca comprar","bajada_es":"Tortugas de orejas rojas, peces de acuario y cardenales en jaulas: mascotas exóticas liberadas y tráfico de fauna.","minutos":11,"pasos":[{"slug":"animales-2.s4.p1","orden":1,"grupo":"animales-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Liberar una mascota exótica","cuerpo":["Cuando alguien se cansa de una mascota exótica —una tortuga, un pez, un reptil— y la suelta en una laguna o un parque, puede crear una invasión. La tortuga de orejas rojas, originaria de América del Norte y muy vendida como mascota, fue liberada en lagunas y arroyos de Argentina y figura en la lista oficial de especies exóticas invasoras: compite con las tortugas nativas y puede transmitirles enfermedades.","Lo mismo pasa con peces de acuario, plantas acuáticas y otros animales. Una mascota exótica nunca se libera: se busca otro hogar o se consulta con la autoridad ambiental."]},"solucion":{}},{"slug":"animales-2.s4.p2","orden":2,"grupo":"animales-2.s4.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Soltar una tortuga de acuario en una laguna es una forma de devolverla a la naturaleza.","razones":[{"id":"r1","texto":"Porque no es su ambiente y puede volverse invasora"},{"id":"r2","texto":"Porque las tortugas no pueden nadar"},{"id":"r3","texto":"Porque las lagunas no tienen agua suficiente"}]},"solucion":{"valor":false,"explicacion":"No es su naturaleza: es de otro continente. Puede morir o volverse invasora y dañar a las especies nativas. Nunca se liberan mascotas exóticas.","clave":["r1"]}},{"slug":"animales-2.s4.p3","orden":3,"grupo":"animales-2.s4.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una mascota liberada puede volverse invasora.","items":[{"id":"i1","texto":"Una familia suelta sus tortugas de orejas rojas en una laguna"},{"id":"i2","texto":"Las tortugas sobreviven y se reproducen"},{"id":"i3","texto":"Compiten con las tortugas nativas por comida y lugares para asolearse"},{"id":"i4","texto":"Las tortugas nativas disminuyen"},{"id":"i5","texto":"Las tortugas nativas se convierten en tortugas de orejas rojas"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un acto que parece bondadoso termina dañando a especies que no tienen nada que ver."}},{"slug":"animales-2.s4.p4","orden":4,"grupo":"animales-2.s4.p4","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Ya no podés cuidar a tu tortuga de acuario. ¿Qué es lo correcto?","opciones":[{"id":"o1","texto":"Buscarle otro hogar o consultar a la autoridad ambiental"},{"id":"o2","texto":"Soltarla en la laguna del parque más cercano"},{"id":"o3","texto":"Dejarla en la plaza para que alguien la encuentre"},{"id":"o4","texto":"Tirarla por el inodoro"}]},"solucion":{"clave":["o1"],"explicacion":"Una mascota exótica es responsabilidad de por vida. Si no se puede cuidar, se busca un hogar, nunca un río.","por_opcion":{"o3":"También es liberarla: puede morir o volverse invasora."}}},{"slug":"animales-2.s4.p5","orden":5,"grupo":"animales-2.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El tráfico de fauna silvestre","cuerpo":["El tráfico de fauna es la captura, el transporte y la venta ilegal de animales silvestres, vivos o de sus partes. En Argentina, muchas aves —como el cardenal amarillo, el loro hablador o distintos jilgueros— se capturan en el campo para venderlas como mascotas en jaulas.","El cardenal amarillo está en peligro de extinción, y la captura para el comercio de aves de jaula es una de sus principales amenazas. Por cada ave que llega viva a una casa, muchas mueren en la captura y el transporte."]},"solucion":{}},{"slug":"animales-2.s4.p6","orden":6,"grupo":"animales-2.s4.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas causa el tráfico de fauna? Marcá todos.","opciones":[{"id":"o1","texto":"Lleva especies al borde de la extinción"},{"id":"o2","texto":"Muchos animales mueren en la captura y el transporte"},{"id":"o3","texto":"Puede transmitir enfermedades"},{"id":"o4","texto":"Alimenta redes delictivas"},{"id":"o5","texto":"Ayuda a conservar las especies en las casas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las especies no se conservan en jaulas: se conservan en su ambiente."}},{"slug":"animales-2.s4.p7","orden":7,"grupo":"animales-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ley y los acuerdos","cuerpo":["En Argentina, la Ley 22.421 protege a la fauna silvestre y prohíbe su caza, captura y comercio sin autorización. A nivel internacional, la convención CITES regula el comercio entre países de especies amenazadas.","La forma más efectiva de frenar el tráfico es no comprar animales silvestres y denunciar su venta ante la autoridad de fauna."]},"solucion":{}},{"slug":"animales-2.s4.p8","orden":8,"grupo":"animales-2.s4.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que hace.","izquierda":[{"id":"a1","texto":"Ley 22.421"},{"id":"a2","texto":"CITES"},{"id":"a3","texto":"Denuncia ciudadana"},{"id":"a4","texto":"No comprar"}],"derecha":[{"id":"b1","texto":"Protege a la fauna silvestre en Argentina"},{"id":"b2","texto":"Regula el comercio internacional de especies amenazadas"},{"id":"b3","texto":"Avisa a la autoridad sobre ventas ilegales"},{"id":"b4","texto":"Quita la demanda que sostiene el tráfico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Leyes, acuerdos y decisiones individuales. El tráfico existe porque alguien compra."}},{"slug":"animales-2.s4.p9","orden":9,"grupo":"animales-2.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué comprar un cardenal en una feria alimenta su extinción.","items":[{"id":"i1","texto":"Alguien compra un cardenal amarillo en una feria"},{"id":"i2","texto":"El vendedor gana dinero con esa venta"},{"id":"i3","texto":"Vuelve a capturar más cardenales en el campo"},{"id":"i4","texto":"La población silvestre sigue bajando"},{"id":"i5","texto":"Comprarlo lo salva de estar en el campo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La demanda es el motor del tráfico. Sin compradores, no hay negocio."}},{"slug":"animales-2.s4.p10","orden":10,"grupo":"animales-2.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es legal o es tráfico de fauna?","grupos":[{"id":"g1","nombre":"Legal"},{"id":"g2","nombre":"Tráfico o ilegal"}],"items":[{"id":"i1","texto":"Observar aves con binoculares"},{"id":"i2","texto":"Comprar un loro sacado del monte"},{"id":"i3","texto":"Adoptar un perro de un refugio"},{"id":"i4","texto":"Vender cardenales en una feria"},{"id":"i5","texto":"Fotografiar un zorro en un parque nacional"},{"id":"i6","texto":"Tener un tatú capturado como mascota"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La fauna silvestre no es mascota. Observarla y fotografiarla, en cambio, es libre y no le hace daño."}},{"slug":"animales-2.s4.p11","orden":11,"grupo":"animales-2.s4.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este aviso en redes y marcá lo problemático.","segmentos":[{"id":"s1","texto":"Vendo cardenal amarillo, cantor, sacado del campo."},{"id":"s2","texto":"Doy en adopción gatito castrado y vacunado."},{"id":"s3","texto":"Regalo tortuga de orejas rojas; si nadie la quiere, la suelto en el lago."},{"id":"s4","texto":"Busco hogar para perro adulto."}]},"solucion":{"clave":["s1","s3"],"explicacion":"Algunos avisos parecen inofensivos y no lo son.","por_opcion":{"s1":"Es tráfico de una especie en peligro de extinción: se debe denunciar.","s3":"Liberarla puede crear una invasión: nunca se liberan mascotas exóticas."}}},{"slug":"animales-2.s4.p12","orden":12,"grupo":"animales-2.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una mascota exótica nunca se {{0}}; el comercio internacional de especies amenazadas lo regula {{1}}; y el tráfico existe porque alguien {{2}}.","banco":[{"id":"w1","texto":"libera"},{"id":"w2","texto":"CITES"},{"id":"w3","texto":"compra"},{"id":"w4","texto":"vacuna"},{"id":"w5","texto":"FIFA"},{"id":"w6","texto":"observa"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para no ser parte del problema."}},{"slug":"animales-2.s4.p13","orden":13,"grupo":"animales-2.s4.p13","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año aproximado se liberó el estornino pinto en Buenos Aires.","min":1900,"max":2020,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":1987,"banda":"lineal","explicacion":"A fines de los años ochenta. En pocas décadas se expandió por buena parte del país: así de rápido puede avanzar una especie liberada."}}]},{"slug":"animales-2.s5","orden":5,"tipo":"leccion","titulo_es":"Una ciudad amiga de la fauna","bajada_es":"Vidrios, luces, agua y refugios: cambios chicos en casas y edificios que salvan muchos animales.","minutos":11,"pasos":[{"slug":"animales-2.s5.p1","orden":1,"grupo":"animales-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Vidrios que matan","cuerpo":["Las aves no ven los vidrios: ven el reflejo del cielo o de los árboles, o ven a través, y chocan. Un estudio publicado en la revista The Condor estimó que en Estados Unidos mueren entre 365 y 988 millones de aves por año por choques contra vidrios, la mayoría en casas y edificios bajos.","Se puede evitar con marcas visibles en el vidrio (puntos o líneas separados unos 5 a 10 centímetros), cortinas o mosquiteros exteriores, o vidrios especiales en edificios nuevos."],"destacado":{"valor":"365-988 millones","texto":"de aves mueren por año en Estados Unidos por chocar contra vidrios, según un estudio de 2014."}},"solucion":{}},{"slug":"animales-2.s5.p2","orden":2,"grupo":"animales-2.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las aves chocan contra los vidrios?","opciones":[{"id":"o1","texto":"Porque ven el reflejo del cielo o ven a través"},{"id":"o2","texto":"Porque les gusta golpear las ventanas"},{"id":"o3","texto":"Porque son aves enfermas que no ven bien"},{"id":"o4","texto":"Porque buscan comida adentro de las casas"}]},"solucion":{"clave":["o1"],"explicacion":"Para un ave, un vidrio reflectante es un pedazo de cielo o de árbol.","por_opcion":{"o3":"Aves sanas chocan igual: el vidrio es invisible para ellas."}}},{"slug":"animales-2.s5.p3","orden":3,"grupo":"animales-2.s5.p3","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas reducen los choques de aves contra vidrios? Marcá todas.","opciones":[{"id":"o1","texto":"Marcas visibles separadas pocos centímetros"},{"id":"o2","texto":"Mosquiteros exteriores"},{"id":"o3","texto":"Cortinas o persianas"},{"id":"o4","texto":"Vidrios especiales en edificios nuevos"},{"id":"o5","texto":"Una sola calcomanía chica en el medio del ventanal"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una silueta aislada no alcanza: el ave pasa por el costado. Hacen falta marcas repartidas en todo el vidrio."}},{"slug":"animales-2.s5.p4","orden":4,"grupo":"animales-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La noche iluminada","cuerpo":["La luz artificial de noche desorienta a muchos animales: aves migratorias que vuelan de noche, insectos que giran alrededor de las lámparas hasta morir, tortugas marinas recién nacidas que van hacia las luces en vez de hacia el mar. También afecta a murciélagos y ranas.","Apagar luces que no se usan, apuntar las luces hacia abajo y usar luces más cálidas (menos azules) reduce ese impacto, y además ahorra energía."]},"solucion":{}},{"slug":"animales-2.s5.p5","orden":5,"grupo":"animales-2.s5.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una luz exterior toda la noche afecta a los insectos.","items":[{"id":"i1","texto":"Se deja una luz blanca encendida toda la noche"},{"id":"i2","texto":"Miles de insectos nocturnos son atraídos"},{"id":"i3","texto":"Giran alrededor hasta agotarse o ser comidos"},{"id":"i4","texto":"Hay menos insectos para polinizar y alimentar a otros animales"},{"id":"i5","texto":"Los insectos aprenden a usar la luz para ver mejor"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La contaminación lumínica es una amenaza silenciosa para los insectos, que ya vienen en declive."}},{"slug":"animales-2.s5.p6","orden":6,"grupo":"animales-2.s5.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta iluminación es amigable con la fauna o no?","grupos":[{"id":"g1","nombre":"Más amigable"},{"id":"g2","nombre":"Menos amigable"}],"items":[{"id":"i1","texto":"Luz que apunta hacia abajo"},{"id":"i2","texto":"Reflector blanco apuntando al cielo"},{"id":"i3","texto":"Luz cálida con sensor de movimiento"},{"id":"i4","texto":"Luces de jardín encendidas toda la noche"},{"id":"i5","texto":"Apagar las luces del jardín a la noche"},{"id":"i6","texto":"Carteles luminosos en zonas naturales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos luz, hacia abajo, cálida y solo cuando hace falta: la regla para la fauna y para la factura."}},{"slug":"animales-2.s5.p7","orden":7,"grupo":"animales-2.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua, refugios y comida natural","cuerpo":["En la ciudad, la fauna necesita agua, lugares para refugiarse y alimento natural. Un recipiente bajo con agua limpia (que se cambia seguido para que no críe mosquitos), arbustos densos, troncos, piedras, plantas nativas con flores y frutos y cajas nido para aves o murciélagos crean hábitat.","También ayuda dejar un rincón del jardín menos \"prolijo\", con hojas secas y pasto más alto, donde se refugian insectos, sapos y lagartijas."]},"solucion":{}},{"slug":"animales-2.s5.p8","orden":8,"grupo":"animales-2.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué elementos crean hábitat para la fauna en un jardín? Marcá todos.","opciones":[{"id":"o1","texto":"Plantas nativas con flores y frutos"},{"id":"o2","texto":"Un plato bajo con agua limpia que se cambia seguido"},{"id":"o3","texto":"Arbustos densos"},{"id":"o4","texto":"Un rincón con hojas secas"},{"id":"o5","texto":"Césped corto con herbicidas en todo el terreno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Agua, refugio y comida: las tres cosas que busca cualquier animal."}},{"slug":"animales-2.s5.p9","orden":9,"grupo":"animales-2.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento con el animal al que más ayuda.","izquierda":[{"id":"a1","texto":"Caja nido"},{"id":"a2","texto":"Rincón con hojas secas"},{"id":"a3","texto":"Flores nativas"},{"id":"a4","texto":"Refugio para murciélagos"}],"derecha":[{"id":"b1","texto":"Aves que anidan en huecos"},{"id":"b2","texto":"Sapos, lagartijas e insectos"},{"id":"b3","texto":"Mariposas y abejas"},{"id":"b4","texto":"Murciélagos insectívoros"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada elemento suma un tipo de hábitat distinto."}},{"slug":"animales-2.s5.p10","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 10 metros de ancho. Si se ponen marcas verticales cada 5 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"10 m = 1000 cm; 1000 ÷ 5 = 200 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p10.v2","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 20 metros de ancho. Si se ponen marcas verticales cada 10 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"20 m = 2000 cm; 2000 ÷ 10 = 200 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p10.v3","orden":10,"grupo":"animales-2.s5.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un ventanal mide 6 metros de ancho. Si se ponen marcas verticales cada 5 centímetros, ¿cuántas franjas hacen falta aproximadamente? (Dividí el ancho en cm por la separación)","unidad":"marcas","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"6 m = 600 cm; 600 ÷ 5 = 120 marcas. Con marcas tan juntas, las aves perciben el vidrio como un obstáculo."}},{"slug":"animales-2.s5.p11","orden":11,"grupo":"animales-2.s5.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un herbicida para dejar el césped perfecto no afecta a la fauna del jardín.","razones":[{"id":"r1","texto":"Porque elimina alimento y puede dañar a sapos, insectos y aves"},{"id":"r2","texto":"Porque los herbicidas atraen mariposas"},{"id":"r3","texto":"Porque la fauna no vive en jardines"}]},"solucion":{"valor":false,"explicacion":"Elimina plantas que alimentan insectos y puede afectar a sapos, insectos y aves. Un jardín con algo de diversidad es mucho mejor hábitat.","clave":["r1"]}},{"slug":"animales-2.s5.p12","orden":12,"grupo":"animales-2.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un edificio y marcá lo que no ayuda a la fauna.","segmentos":[{"id":"s1","texto":"Pondremos marcas en los ventanales del hall."},{"id":"s2","texto":"Dejaremos los reflectores del frente encendidos toda la noche apuntando al cielo."},{"id":"s3","texto":"Plantaremos nativas en el cantero de la entrada."},{"id":"s4","texto":"Pondremos una sola calcomanía de halcón en el ventanal."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los detalles importan: cantidad de marcas, dirección de la luz.","por_opcion":{"s2":"La luz hacia el cielo desorienta aves e insectos y gasta energía.","s4":"Una silueta aislada casi no sirve: hacen falta marcas repartidas."}}},{"slug":"animales-2.s5.p13","orden":13,"grupo":"animales-2.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las aves no ven los {{0}}; la luz de noche conviene que apunte hacia {{1}}; y un jardín amigo de la fauna ofrece agua, refugio y {{2}}.","banco":[{"id":"w1","texto":"vidrios"},{"id":"w2","texto":"abajo"},{"id":"w3","texto":"comida"},{"id":"w4","texto":"techos"},{"id":"w5","texto":"arriba"},{"id":"w6","texto":"ruido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres cambios chicos para una ciudad más amable."}}]},{"slug":"animales-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: vecinos silvestres","bajada_es":"Fauna urbana, convivencia, mascotas, tráfico y ciudad amigable, mezclados.","minutos":8,"pasos":[{"slug":"animales-2.s6.p1","orden":1,"grupo":"animales-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Vecinos silvestres». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el barrio junto al humedal","bajada_es":"Un barrio nuevo junto a un humedal tiene conflictos con la fauna. Ordená los problemas y armá un plan de convivencia.","minutos":10,"pasos":[{"slug":"animales-2.s7.p1","orden":1,"grupo":"animales-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El barrio","cuerpo":["Un barrio de 300 casas se construyó al lado de un humedal. Los vecinos se quejan de que los carpinchos comen los jardines y cruzan las calles, y algunos proponen echarlos. Hay 180 perros y 150 gatos, muchos sueltos. En la entrada hay un edificio vidriado donde aparecen aves muertas cada semana, y las luces del perímetro quedan encendidas toda la noche.","En el humedal viven carpinchos, garzas, teros, coipos y muchas otras especies. La asociación vecinal pidió un plan de convivencia."]},"solucion":{}},{"slug":"animales-2.s7.p2","orden":2,"grupo":"animales-2.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el enfoque correcto para el conflicto con los carpinchos?","opciones":[{"id":"o1","texto":"Convivir con reglas claras"},{"id":"o2","texto":"Capturarlos y llevarlos a otro lugar"},{"id":"o3","texto":"Cazarlos para reducir la población"},{"id":"o4","texto":"Cerrar el humedal y rellenarlo"}]},"solucion":{"clave":["o1"],"explicacion":"El barrio se instaló en su ambiente. La salida es la convivencia, no la expulsión.","por_opcion":{"o3":"Es ilegal y no resuelve nada: el humedal es su hábitat."}}},{"slug":"animales-2.s7.p3","orden":3,"grupo":"animales-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si cada gato suelto caza en promedio 10 aves por año, ¿cuántas aves por año cazarían los 150 gatos del barrio si todos salieran?","unidad":"aves","decimales":0,"contexto":"150 gatos; 10 aves por gato por año."},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"150 × 10 = 1.500 aves por año, en el borde de un humedal lleno de aves."}},{"slug":"animales-2.s7.p4","orden":4,"grupo":"animales-2.s7.p4","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas del plan por su prioridad, de la primera a la última.","items":[{"id":"i1","texto":"Correa obligatoria y gatos adentro de noche en el borde del humedal"},{"id":"i2","texto":"Marcas en los vidrios del edificio de la entrada"},{"id":"i3","texto":"Luces del perímetro hacia abajo y con sensor"},{"id":"i4","texto":"Carteles y charlas sobre convivencia con carpinchos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que evita muertes ya; después lo que mejora el hábitat y los hábitos.","valores":{"i1":"protege a la fauna ya","i2":"evita muertes cada semana","i3":"reduce la desorientación","i4":"cambia hábitos a largo plazo"}}},{"slug":"animales-2.s7.p5","orden":5,"grupo":"animales-2.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de los vecinos.","grupos":[{"id":"g1","nombre":"Suma a la convivencia"},{"id":"g2","nombre":"Empeora la situación"}],"items":[{"id":"i1","texto":"Reductores de velocidad en la calle junto al humedal"},{"id":"i2","texto":"Darles pan a los carpinchos para que no coman los jardines"},{"id":"i3","texto":"Cercos bajos para proteger huertas"},{"id":"i4","texto":"Soltar perros de noche para ahuyentarlos"},{"id":"i5","texto":"Castración gratuita de perros y gatos"},{"id":"i6","texto":"Rellenar una parte del humedal"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las buenas medidas protegen a vecinos y fauna; las malas aumentan el conflicto o destruyen hábitat."}},{"slug":"animales-2.s7.p6","orden":6,"grupo":"animales-2.s7.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Alimentar a los carpinchos en un lugar fijo reduciría el problema de los jardines.","razones":[{"id":"r1","texto":"Porque los acostumbra a las personas y los concentra"},{"id":"r2","texto":"Porque los carpinchos no comen pasto"},{"id":"r3","texto":"Porque la comida los vuelve silvestres otra vez"}]},"solucion":{"valor":false,"explicacion":"Los acostumbraría a las personas, los concentraría y aumentaría los conflictos y las enfermedades. No hay que alimentarlos.","clave":["r1"]}},{"slug":"animales-2.s7.p7","orden":7,"grupo":"animales-2.s7.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan sobre las mascotas? Marcá todo.","opciones":[{"id":"o1","texto":"Perros con correa en las calles junto al humedal"},{"id":"o2","texto":"Gatos adentro de noche"},{"id":"o3","texto":"Campaña de castración"},{"id":"o4","texto":"Prohibir abandonar animales"},{"id":"o5","texto":"Dejar que los perros persigan carpinchos para que se vayan"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las mascotas bien cuidadas conviven mejor con el humedal, y también están más seguras."}},{"slug":"animales-2.s7.p8","orden":8,"grupo":"animales-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La asociación publica su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pondremos marcas en los vidrios del edificio de la entrada."},{"id":"s2","texto":"Pediremos que trasladen a los carpinchos a otra provincia."},{"id":"s3","texto":"Las luces del perímetro apuntarán hacia abajo y tendrán sensores."},{"id":"s4","texto":"Cada vecino podrá dar de comer a los carpinchos en su jardín."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan de convivencia protege a la fauna en su hábitat y cambia los hábitos de las personas.","por_opcion":{"s2":"El humedal es su hábitat; trasladarlos no resuelve el conflicto y puede dañarlos.","s4":"Alimentarlos aumenta los conflictos y las enfermedades."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-3","rama":"animales","orden":3,"nivel":2,"titulo_es":"Especies en peligro","bajada_es":"Del yaguareté al macá tobiano: cómo se mide el riesgo de extinción, qué hace a una especie vulnerable y cómo se recupera una población.","objetivos_es":["Interpretar las categorías de la Lista Roja de la UICN","Reconocer especies amenazadas de Argentina y sus causas","Explicar qué características hacen más vulnerable a una especie","Distinguir extinción local, en estado silvestre y global","Describir estrategias para recuperar especies amenazadas"],"repasa":["animales-1","animales-2","tronco-1"],"requiere_tronco":2,"fuentes":["iucn-red-list","iucn-categorias","sarem-2019","aves-argentinas-amenazadas","ipbes-global","rewilding-argentina","parques-nacionales"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-3.s1","orden":1,"tipo":"leccion","titulo_es":"La Lista Roja","bajada_es":"Cómo la UICN clasifica el riesgo de extinción de las especies y qué dicen sus números.","minutos":11,"pasos":[{"slug":"animales-3.s1.p1","orden":1,"grupo":"animales-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un termómetro del riesgo","cuerpo":["La Unión Internacional para la Conservación de la Naturaleza (UICN) evalúa el riesgo de extinción de las especies y lo publica en la Lista Roja. Usa categorías: Extinta (EX), Extinta en estado silvestre (EW), En peligro crítico (CR), En peligro (EN), Vulnerable (VU), Casi amenazada (NT) y Preocupación menor (LC). Cuando no hay datos suficientes, la especie queda como Datos insuficientes (DD).","Las especies en las categorías CR, EN y VU se consideran amenazadas."],"lista":["EX · Extinta","EW · Extinta en estado silvestre","CR · En peligro crítico","EN · En peligro","VU · Vulnerable","NT · Casi amenazada","LC · Preocupación menor"]},"solucion":{}},{"slug":"animales-3.s1.p2","orden":2,"grupo":"animales-3.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas categorías de la Lista Roja de menor a mayor riesgo.","items":[{"id":"i1","texto":"Preocupación menor (LC)"},{"id":"i2","texto":"Casi amenazada (NT)"},{"id":"i3","texto":"Vulnerable (VU)"},{"id":"i4","texto":"En peligro (EN)"},{"id":"i5","texto":"En peligro crítico (CR)"}],"extremos":["Menor riesgo","Mayor riesgo"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada escalón indica un riesgo de extinción mayor."}},{"slug":"animales-3.s1.p3","orden":3,"grupo":"animales-3.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta categoría cuenta como \"amenazada\" o no?","grupos":[{"id":"g1","nombre":"Amenazada"},{"id":"g2","nombre":"No amenazada (todavía)"}],"items":[{"id":"i1","texto":"En peligro crítico (CR)"},{"id":"i2","texto":"Casi amenazada (NT)"},{"id":"i3","texto":"En peligro (EN)"},{"id":"i4","texto":"Preocupación menor (LC)"},{"id":"i5","texto":"Vulnerable (VU)"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Solo CR, EN y VU son \"amenazadas\". NT es una alerta: podría pasar a amenazada pronto."}},{"slug":"animales-3.s1.p4","orden":4,"grupo":"animales-3.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los criterios","cuerpo":["Para asignar una categoría, la UICN usa criterios medibles: qué tan rápido disminuye la población, qué tan chica es su distribución, cuántos individuos adultos quedan y si esa población está fragmentada o en declive. Por ejemplo, una especie con menos de 50 individuos maduros califica como En peligro crítico, aunque no se conozcan otros datos.","Así, la categoría no es una opinión: surge de datos y umbrales definidos."]},"solucion":{}},{"slug":"animales-3.s1.p5","orden":5,"grupo":"animales-3.s1.p5","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos usa la UICN para evaluar el riesgo de una especie? Marcá todos.","opciones":[{"id":"o1","texto":"Qué tan rápido disminuye su población"},{"id":"o2","texto":"El tamaño de su área de distribución"},{"id":"o3","texto":"Cuántos individuos adultos quedan"},{"id":"o4","texto":"Si la población está fragmentada"},{"id":"o5","texto":"Qué tan linda es la especie"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Criterios medibles, no la popularidad de la especie."}},{"slug":"animales-3.s1.p6","orden":6,"grupo":"animales-3.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números","cuerpo":["La Lista Roja ya evaluó más de 160.000 especies, y más de 45.000 están amenazadas: alrededor de una de cada cuatro. Algunos grupos están especialmente en riesgo: alrededor del 40 % de los anfibios y más de un tercio de los tiburones y rayas y de los corales de arrecife.","Hay que recordar que solo se evaluó una parte chica de todas las especies del planeta."],"datos":{"tipo":"barras","titulo":"Especies amenazadas en algunos grupos evaluados (aproximado)","unidad":"% amenazado","filas":[{"etiqueta":"Corales de arrecife","valor":44},{"etiqueta":"Anfibios","valor":41},{"etiqueta":"Tiburones y rayas","valor":37},{"etiqueta":"Mamíferos","valor":26},{"etiqueta":"Aves","valor":12}],"nota":"Lista Roja de la UICN, valores aproximados de evaluaciones recientes."}},"solucion":{}},{"slug":"animales-3.s1.p7","orden":7,"grupo":"animales-3.s1.p7","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según la Lista Roja, ordená estos grupos por el porcentaje de especies amenazadas, de mayor a menor.","items":[{"id":"i1","texto":"Corales de arrecife"},{"id":"i2","texto":"Anfibios"},{"id":"i3","texto":"Mamíferos"},{"id":"i4","texto":"Aves"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los anfibios y los corales están entre los grupos más amenazados del planeta.","valores":{"i1":"≈ 44 %","i2":"≈ 41 %","i3":"≈ 26 %","i4":"≈ 12 %"}}},{"slug":"animales-3.s1.p8","orden":8,"grupo":"animales-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se evaluaron 160.000 especies y 45.000 están amenazadas, ¿qué porcentaje está amenazado? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":28,"tolerancia":1,"explicacion":"45.000 ÷ 160.000 × 100 ≈ 28 %: alrededor de una de cada cuatro especies evaluadas."}},{"slug":"animales-3.s1.p8.v2","orden":8,"grupo":"animales-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se evaluaron 150.000 especies y 42.000 están amenazadas, ¿qué porcentaje está amenazado? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":28,"tolerancia":1,"explicacion":"42.000 ÷ 150.000 × 100 ≈ 28 %: alrededor de una de cada cuatro especies evaluadas."}},{"slug":"animales-3.s1.p8.v3","orden":8,"grupo":"animales-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se evaluaron 166.000 especies y 46.000 están amenazadas, ¿qué porcentaje está amenazado? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":28,"tolerancia":1,"explicacion":"46.000 ÷ 166.000 × 100 ≈ 28 %: alrededor de una de cada cuatro especies evaluadas."}},{"slug":"animales-3.s1.p9","orden":9,"grupo":"animales-3.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una especie no aparece como amenazada en la Lista Roja, seguro está bien.","razones":[{"id":"r1","texto":"Porque muchas especies no fueron evaluadas o faltan datos"},{"id":"r2","texto":"Porque la Lista Roja incluye todas las especies del planeta"},{"id":"r3","texto":"Porque las especies no evaluadas son siempre abundantes"}]},"solucion":{"valor":false,"explicacion":"Puede que no haya sido evaluada, o que esté como Datos insuficientes. Solo una parte chica de las especies del planeta fue evaluada.","clave":["r1"]}},{"slug":"animales-3.s1.p10","orden":10,"grupo":"animales-3.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada categoría con su significado.","izquierda":[{"id":"a1","texto":"EW"},{"id":"a2","texto":"CR"},{"id":"a3","texto":"NT"},{"id":"a4","texto":"DD"}],"derecha":[{"id":"b1","texto":"Solo sobrevive en cautiverio"},{"id":"b2","texto":"Riesgo extremadamente alto de extinción"},{"id":"b3","texto":"Cerca de ser amenazada"},{"id":"b4","texto":"No hay datos suficientes para evaluarla"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer las siglas permite leer cualquier ficha de especie."}},{"slug":"animales-3.s1.p11","orden":11,"grupo":"animales-3.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Lista Roja la publica la UICN."},{"id":"s2","texto":"Las especies \"Casi amenazadas\" cuentan como amenazadas."},{"id":"s3","texto":"Alrededor de un cuarto de las especies evaluadas está amenazado."},{"id":"s4","texto":"La categoría se decide según qué tan conocida es la especie."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La Lista Roja es una herramienta científica, no un ranking de popularidad.","por_opcion":{"s2":"Solo CR, EN y VU cuentan como amenazadas; NT es una alerta.","s4":"Se decide con criterios medibles de población y distribución."}}},{"slug":"animales-3.s1.p12","orden":12,"grupo":"animales-3.s1.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una rana fue vista pocas veces y nadie sabe cuántas quedan. ¿Qué categoría le corresponde hasta tener más datos?","opciones":[{"id":"o1","texto":"Datos insuficientes (DD)"},{"id":"o2","texto":"Preocupación menor (LC), por ahora"},{"id":"o3","texto":"Extinta (EX), por las dudas"},{"id":"o4","texto":"En peligro crítico (CR), automáticamente"}]},"solucion":{"clave":["o1"],"explicacion":"Sin datos no se puede asignar un nivel de riesgo. DD no significa \"a salvo\": muchas especies DD podrían estar amenazadas.","por_opcion":{"o3":"Para declarar extinta a una especie hay que buscarla a fondo sin encontrarla."}}},{"slug":"animales-3.s1.p13","orden":13,"grupo":"animales-3.s1.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie que solo sobrevive en zoológicos y criaderos se considera Extinta en estado silvestre, no Extinta.","razones":[{"id":"r1","texto":"Porque todavía quedan individuos vivos en cautiverio"},{"id":"r2","texto":"Porque los zoológicos cuentan como naturaleza"},{"id":"r3","texto":"Porque EW y EX significan exactamente lo mismo"}]},"solucion":{"valor":true,"explicacion":"Mientras queden individuos en cautiverio es EW; todavía existe la posibilidad de reintroducirla en la naturaleza.","clave":["r1"]}},{"slug":"animales-3.s1.p14","orden":14,"grupo":"animales-3.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Lista {{0}} la publica la UICN; las categorías amenazadas son CR, EN y {{1}}; y alrededor de una de cada {{2}} especies evaluadas está amenazada.","banco":[{"id":"w1","texto":"Roja"},{"id":"w2","texto":"VU"},{"id":"w3","texto":"cuatro"},{"id":"w4","texto":"Verde"},{"id":"w5","texto":"LC"},{"id":"w6","texto":"diez"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para leer la Lista Roja y cualquier ficha de especie."}}]},{"slug":"animales-3.s2","orden":2,"tipo":"leccion","titulo_es":"Especies argentinas en peligro","bajada_es":"Yaguareté, huemul, macá tobiano, cardenal amarillo y cauquén colorado: quiénes son y qué los amenaza.","minutos":10,"pasos":[{"slug":"animales-3.s2.p1","orden":1,"grupo":"animales-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Evaluaciones nacionales","cuerpo":["Además de la Lista Roja mundial, cada país evalúa sus especies. En Argentina, por ejemplo, la Sociedad Argentina para el Estudio de los Mamíferos (SAREM) y Aves Argentinas publicaron categorizaciones nacionales. Una especie puede estar menos amenazada a nivel mundial que en un país, si en ese país quedan pocos individuos.","El yaguareté es un ejemplo: a nivel mundial está Casi amenazado, pero en Argentina está En peligro crítico, porque quedan pocos cientos de ejemplares y perdió la mayor parte de su distribución histórica."]},"solucion":{}},{"slug":"animales-3.s2.p2","orden":2,"grupo":"animales-3.s2.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie puede estar en distinta categoría de riesgo a nivel mundial y a nivel nacional.","razones":[{"id":"r1","texto":"Porque su situación puede ser distinta en cada país"},{"id":"r2","texto":"Porque las categorías son siempre idénticas"},{"id":"r3","texto":"Porque solo existen evaluaciones mundiales"}]},"solucion":{"valor":true,"explicacion":"Sí: el yaguareté está Casi amenazado en el mundo, pero En peligro crítico en Argentina, donde quedan pocos cientos.","clave":["r1"]}},{"slug":"animales-3.s2.p3","orden":3,"grupo":"animales-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Algunos casos","cuerpo":["El huemul, un ciervo de los bosques andino-patagónicos, está En peligro: quedan poblaciones chicas y aisladas, afectadas por la pérdida de hábitat, la caza, perros y enfermedades del ganado. El macá tobiano, un ave que solo vive en lagunas de la meseta de Santa Cruz, está En peligro crítico: lo afectan el visón americano, una especie invasora, las truchas introducidas que compiten por alimento y los cambios en las lagunas.","El cardenal amarillo está En peligro por la captura para el comercio de aves de jaula y la pérdida de hábitat. Y el cauquén colorado, un ganso que migra entre la Patagonia y el sur bonaerense, está En peligro crítico en Argentina, con muy pocos ejemplares."]},"solucion":{}},{"slug":"animales-3.s2.p4","orden":4,"grupo":"animales-3.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada especie con su principal amenaza.","izquierda":[{"id":"a1","texto":"Yaguareté"},{"id":"a2","texto":"Macá tobiano"},{"id":"a3","texto":"Cardenal amarillo"},{"id":"a4","texto":"Huemul"}],"derecha":[{"id":"b1","texto":"Pérdida de selva y caza"},{"id":"b2","texto":"Visón americano invasor y truchas introducidas"},{"id":"b3","texto":"Captura para aves de jaula"},{"id":"b4","texto":"Poblaciones chicas y aisladas, perros y enfermedades del ganado"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada especie amenazada tiene su historia. Conocerla dice qué hacer."}},{"slug":"animales-3.s2.p5","orden":5,"grupo":"animales-3.s2.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Dónde vive cada especie amenazada?","grupos":[{"id":"g1","nombre":"Selva y bosques del norte"},{"id":"g2","nombre":"Patagonia"},{"id":"g3","nombre":"Pastizales y espinal del centro"}],"items":[{"id":"i1","texto":"Yaguareté"},{"id":"i2","texto":"Macá tobiano"},{"id":"i3","texto":"Cardenal amarillo"},{"id":"i4","texto":"Tatú carreta"},{"id":"i5","texto":"Huemul"},{"id":"i6","texto":"Venado de las pampas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Especies amenazadas en casi todas las regiones del país."}},{"slug":"animales-3.s2.p6","orden":6,"grupo":"animales-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una especie ocupaba 100 unidades de territorio en Argentina y hoy ocupa 5, ¿qué porcentaje de su distribución histórica conserva? Redondeá a un decimal.","unidad":"%","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"5 ÷ 100 × 100 ≈ 5 %. El yaguareté, por ejemplo, perdió la gran mayoría de su distribución histórica en el país."}},{"slug":"animales-3.s2.p6.v2","orden":6,"grupo":"animales-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una especie ocupaba 80 unidades de territorio en Argentina y hoy ocupa 4, ¿qué porcentaje de su distribución histórica conserva? Redondeá a un decimal.","unidad":"%","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"4 ÷ 80 × 100 ≈ 5 %. El yaguareté, por ejemplo, perdió la gran mayoría de su distribución histórica en el país."}},{"slug":"animales-3.s2.p6.v3","orden":6,"grupo":"animales-3.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una especie ocupaba 95 unidades de territorio en Argentina y hoy ocupa 3, ¿qué porcentaje de su distribución histórica conserva? Redondeá a un decimal.","unidad":"%","decimales":1},"solucion":{"valor":3.2,"tolerancia":0.1,"explicacion":"3 ÷ 95 × 100 ≈ 3,2 %. El yaguareté, por ejemplo, perdió la gran mayoría de su distribución histórica en el país."}},{"slug":"animales-3.s2.p7","orden":7,"grupo":"animales-3.s2.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el macá tobiano es tan vulnerable?","opciones":[{"id":"o1","texto":"Vive solo en algunas lagunas de Santa Cruz"},{"id":"o2","texto":"Porque está en todas las lagunas del país"},{"id":"o3","texto":"Porque migra a Europa cada invierno"},{"id":"o4","texto":"Porque es una especie exótica"}]},"solucion":{"clave":["o1"],"explicacion":"Una especie que vive en pocos lugares puede perderlo todo con pocos cambios. Es endémica de la meseta santacruceña.","por_opcion":{"o3":"Migra dentro de la región patagónica y la costa; su problema es su distribución muy reducida."}}},{"slug":"animales-3.s2.p8","orden":8,"grupo":"animales-3.s2.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el visón americano amenaza al macá tobiano.","items":[{"id":"i1","texto":"Se trajeron visones americanos para criaderos de pieles"},{"id":"i2","texto":"Algunos escaparon y se establecieron en la Patagonia"},{"id":"i3","texto":"Llegaron a las lagunas donde anida el macá tobiano"},{"id":"i4","texto":"Depredan huevos, pichones y adultos"},{"id":"i5","texto":"La población de macá tobiano cae"},{"id":"i6","texto":"Los macás aprendieron a comer visones"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una especie exótica liberada puede poner en riesgo a una especie que solo vive allí."}},{"slug":"animales-3.s2.p9","orden":9,"grupo":"animales-3.s2.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué especies argentinas están amenazadas a nivel nacional? Marcá todas.","opciones":[{"id":"o1","texto":"Yaguareté"},{"id":"o2","texto":"Huemul"},{"id":"o3","texto":"Macá tobiano"},{"id":"o4","texto":"Cardenal amarillo"},{"id":"o5","texto":"Paloma doméstica"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La paloma doméstica es exótica y muy abundante: no está amenazada."}},{"slug":"animales-3.s2.p10","orden":10,"grupo":"animales-3.s2.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este texto escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El huemul vive en los bosques andino-patagónicos."},{"id":"s2","texto":"El yaguareté está fuera de peligro en Argentina."},{"id":"s3","texto":"El cardenal amarillo sufre la captura para aves de jaula."},{"id":"s4","texto":"El macá tobiano vive en todas las lagunas del país."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer las especies de tu país es el primer paso para protegerlas.","por_opcion":{"s2":"En Argentina está En peligro crítico; quedan pocos cientos.","s4":"Solo vive en algunas lagunas de la meseta de Santa Cruz."}}},{"slug":"animales-3.s2.p11","orden":11,"grupo":"animales-3.s2.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En Argentina, el yaguareté está en peligro {{0}}; el macá tobiano vive en lagunas de {{1}}; y el cardenal amarillo sufre la captura para aves de {{2}}.","banco":[{"id":"w1","texto":"crítico"},{"id":"w2","texto":"Santa Cruz"},{"id":"w3","texto":"jaula"},{"id":"w4","texto":"leve"},{"id":"w5","texto":"Misiones"},{"id":"w6","texto":"corral"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos sobre especies argentinas amenazadas."}},{"slug":"animales-3.s2.p12","orden":12,"grupo":"animales-3.s2.p12","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el viaje anual del cauquén colorado, empezando en primavera.","items":[{"id":"i1","texto":"Llega a la Patagonia austral a reproducirse"},{"id":"i2","texto":"Cría a sus pichones durante el verano"},{"id":"i3","texto":"En otoño vuela hacia el norte"},{"id":"i4","texto":"Pasa el invierno en el sur de Buenos Aires"}],"extremos":["Primavera","Invierno"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Al migrar, una especie depende de varios lugares a la vez: si cualquiera se degrada, la población sufre."}},{"slug":"animales-3.s2.p13","orden":13,"grupo":"animales-3.s2.p13","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos yaguaretés quedan en estado silvestre en Argentina.","min":10,"max":100000,"paso":1,"unidad":"individuos","escala":"log"},"solucion":{"valor":250,"banda":"log","explicacion":"Del orden de pocos cientos, según las estimaciones de los últimos años. Por eso está En peligro crítico en el país."}}]},{"slug":"animales-3.s3","orden":3,"tipo":"leccion","titulo_es":"Por qué algunas especies son más vulnerables","bajada_es":"Tamaño, reproducción lenta, distribución reducida y dieta especializada: rasgos que aumentan el riesgo.","minutos":11,"pasos":[{"slug":"animales-3.s3.p1","orden":1,"grupo":"animales-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Rasgos de riesgo","cuerpo":["No todas las especies responden igual a las amenazas. Suelen ser más vulnerables las especies grandes, que necesitan mucho territorio; las que se reproducen lento, con pocas crías y mucho tiempo entre una y otra; las que viven en un área muy chica o en un solo tipo de ambiente (endémicas o de distribución restringida); y las especialistas, que dependen de un alimento o un hábitat muy particular.","Las especies generalistas, que comen de todo y viven en muchos ambientes, suelen adaptarse mejor a los cambios."]},"solucion":{}},{"slug":"animales-3.s3.p2","orden":2,"grupo":"animales-3.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este rasgo aumenta o reduce la vulnerabilidad de una especie?","grupos":[{"id":"g1","nombre":"Aumenta la vulnerabilidad"},{"id":"g2","nombre":"Reduce la vulnerabilidad"}],"items":[{"id":"i1","texto":"Tener una cría cada dos o tres años"},{"id":"i2","texto":"Tener muchas crías por año"},{"id":"i3","texto":"Vivir en una sola laguna"},{"id":"i4","texto":"Vivir en muchos ambientes"},{"id":"i5","texto":"Comer un solo tipo de alimento"},{"id":"i6","texto":"Comer de todo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La biología de cada especie define cuánto resiste los cambios."}},{"slug":"animales-3.s3.p3","orden":3,"grupo":"animales-3.s3.p3","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada especie con el rasgo que la hace más vulnerable.","izquierda":[{"id":"a1","texto":"Yaguareté"},{"id":"a2","texto":"Macá tobiano"},{"id":"a3","texto":"Oso hormiguero"},{"id":"a4","texto":"Cóndor andino"}],"derecha":[{"id":"b1","texto":"Necesita territorios enormes"},{"id":"b2","texto":"Distribución muy reducida"},{"id":"b3","texto":"Dieta muy especializada en hormigas y termitas"},{"id":"b4","texto":"Se reproduce muy lento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada rasgo es una debilidad frente a las amenazas humanas."}},{"slug":"animales-3.s3.p4","orden":4,"grupo":"animales-3.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La reproducción lenta","cuerpo":["El cóndor andino pone, en general, un solo huevo cada dos o tres años, y tarda varios años en llegar a la edad adulta. Si mueren adultos por envenenamiento, la población tarda muchísimo en recuperarse. Una especie de ratón, en cambio, puede tener varias camadas por año."]},"solucion":{}},{"slug":"animales-3.s3.p5","orden":5,"grupo":"animales-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una pareja de cóndores cría un pichón cada 2 años, ¿cuántos pichones puede criar en 20 años de vida reproductiva, como máximo?","unidad":"pichones","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"20 ÷ 2 = 10 pichones como máximo. Por eso perder un solo adulto por envenenamiento es un golpe enorme para la población."}},{"slug":"animales-3.s3.p5.v2","orden":5,"grupo":"animales-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una pareja de cóndores cría un pichón cada 3 años, ¿cuántos pichones puede criar en 30 años de vida reproductiva, como máximo?","unidad":"pichones","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"30 ÷ 3 = 10 pichones como máximo. Por eso perder un solo adulto por envenenamiento es un golpe enorme para la población."}},{"slug":"animales-3.s3.p5.v3","orden":5,"grupo":"animales-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una pareja de cóndores cría un pichón cada 2 años, ¿cuántos pichones puede criar en 10 años de vida reproductiva, como máximo?","unidad":"pichones","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"10 ÷ 2 = 5 pichones como máximo. Por eso perder un solo adulto por envenenamiento es un golpe enorme para la población."}},{"slug":"animales-3.s3.p6","orden":6,"grupo":"animales-3.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué perder adultos es tan grave para el cóndor.","items":[{"id":"i1","texto":"Un cebo envenenado mata a varios cóndores adultos"},{"id":"i2","texto":"Esos adultos ya no se reproducen"},{"id":"i3","texto":"Cada pareja cría un pichón cada dos o tres años"},{"id":"i4","texto":"Los pichones tardan años en ser adultos"},{"id":"i5","texto":"La población tarda décadas en recuperarse"},{"id":"i6","texto":"Los cóndores ponen muchos huevos para compensar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Especies de vida lenta necesitan que los adultos sobrevivan."}},{"slug":"animales-3.s3.p7","orden":7,"grupo":"animales-3.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie que come de todo y vive en muchos ambientes suele adaptarse mejor a los cambios que una especialista.","razones":[{"id":"r1","texto":"Porque tiene más opciones cuando el ambiente cambia"},{"id":"r2","texto":"Porque las generalistas no necesitan comer"},{"id":"r3","texto":"Porque las especialistas se adaptan más rápido"}]},"solucion":{"valor":true,"explicacion":"Las generalistas tienen más opciones cuando su ambiente cambia; las especialistas dependen de recursos muy particulares.","clave":["r1"]}},{"slug":"animales-3.s3.p8","orden":8,"grupo":"animales-3.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Endémicas","cuerpo":["Una especie endémica vive solo en un lugar del mundo. Argentina tiene muchas especies endémicas, como el macá tobiano, la ranita de Valcheta, que vive solo en unos arroyos termales de la meseta de Somuncurá, y muchas plantas de la Puna y de las sierras. Si su único lugar se degrada, no tienen a dónde ir."]},"solucion":{}},{"slug":"animales-3.s3.p9","orden":9,"grupo":"animales-3.s3.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que una especie sea endémica de Argentina?","opciones":[{"id":"o1","texto":"Que vive naturalmente solo en Argentina"},{"id":"o2","texto":"Que está enferma"},{"id":"o3","texto":"Que es muy abundante en todo el mundo"},{"id":"o4","texto":"Que fue traída de otro país"}]},"solucion":{"clave":["o1"],"explicacion":"Proteger las especies endémicas es una responsabilidad única: si desaparecen de acá, desaparecen del mundo.","por_opcion":{"o3":"Endémica es lo contrario: vive en un solo lugar."}}},{"slug":"animales-3.s3.p10","orden":10,"grupo":"animales-3.s3.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas especies de más a menos vulnerable, según sus rasgos.","items":[{"id":"i1","texto":"Especie grande, endémica de una laguna, con una cría por año"},{"id":"i2","texto":"Especie grande de amplia distribución, con pocas crías"},{"id":"i3","texto":"Especie chica de amplia distribución, con varias crías"},{"id":"i4","texto":"Especie generalista que vive en ciudades y campos"}],"extremos":["Más vulnerable","Menos vulnerable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Tamaño, distribución y reproducción se combinan en el riesgo.","valores":{"i1":"muy vulnerable","i2":"vulnerable","i3":"poco vulnerable","i4":"muy poco vulnerable"}}},{"slug":"animales-3.s3.p11","orden":11,"grupo":"animales-3.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué rasgos tiene una especie muy vulnerable? Marcá todos.","opciones":[{"id":"o1","texto":"Distribución muy reducida"},{"id":"o2","texto":"Reproducción lenta"},{"id":"o3","texto":"Dieta especializada"},{"id":"o4","texto":"Necesidad de grandes territorios"},{"id":"o5","texto":"Muchas crías por año"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Estos rasgos no condenan a una especie, pero la hacen más frágil frente a las amenazas."}},{"slug":"animales-3.s3.p12","orden":12,"grupo":"animales-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El cóndor andino se reproduce lento."},{"id":"s2","texto":"Las especies endémicas pueden mudarse a cualquier otro país si su hábitat se degrada."},{"id":"s3","texto":"El oso hormiguero tiene una dieta especializada."},{"id":"s4","texto":"Las especies grandes nunca están en riesgo porque son fuertes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La biología de una especie ayuda a entender su riesgo.","por_opcion":{"s2":"Suelen depender de condiciones que solo existen en su lugar.","s4":"Suelen ser más vulnerables: necesitan mucho territorio y se reproducen lento."}}},{"slug":"animales-3.s3.p13","orden":13,"grupo":"animales-3.s3.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un zorro gris y un macá tobiano pierden parte de su ambiente. ¿Cuál corre más riesgo?","opciones":[{"id":"o1","texto":"El macá, que depende de pocas lagunas"},{"id":"o2","texto":"El zorro, porque es más grande"},{"id":"o3","texto":"Los dos igual, porque son animales"},{"id":"o4","texto":"Ninguno, porque se adaptan enseguida"}]},"solucion":{"clave":["o1"],"explicacion":"El zorro gris es generalista y de amplia distribución; el macá tobiano es endémico y especialista.","por_opcion":{"o3":"Sus rasgos son muy distintos: el zorro vive en muchos ambientes y come de todo."}}},{"slug":"animales-3.s3.p14","orden":14,"grupo":"animales-3.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una especie que vive en un solo lugar del mundo es {{0}}; las que comen de todo son {{1}}; y las de reproducción {{2}} se recuperan más despacio.","banco":[{"id":"w1","texto":"endémica"},{"id":"w2","texto":"generalistas"},{"id":"w3","texto":"lenta"},{"id":"w4","texto":"exótica"},{"id":"w5","texto":"especialistas"},{"id":"w6","texto":"rápida"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres rasgos que explican la vulnerabilidad."}}]},{"slug":"animales-3.s4","orden":4,"tipo":"leccion","titulo_es":"La extinción","bajada_es":"Local, en estado silvestre o global: qué significa que una especie se extinga y qué dice la tasa actual.","minutos":11,"pasos":[{"slug":"animales-3.s4.p1","orden":1,"grupo":"animales-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Grados de extinción","cuerpo":["Una extinción local ocurre cuando una especie desaparece de una zona pero sobrevive en otras: el yaguareté, por ejemplo, desapareció de gran parte de la región pampeana, donde vivía en el siglo XIX. Una especie está extinta en estado silvestre cuando solo sobrevive en cautiverio. Y está extinta cuando no queda ningún individuo en el mundo.","La extinción global es irreversible: no hay forma de traer de vuelta a una especie desaparecida."]},"solucion":{}},{"slug":"animales-3.s4.p2","orden":2,"grupo":"animales-3.s4.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de extinción es cada caso?","grupos":[{"id":"g1","nombre":"Local"},{"id":"g2","nombre":"Global"}],"items":[{"id":"i1","texto":"El yaguareté desaparecido de la región pampeana"},{"id":"i2","texto":"El lobo de las Malvinas, extinto en el siglo XIX"},{"id":"i3","texto":"El oso hormiguero desaparecido de Corrientes antes de su reintroducción"},{"id":"i4","texto":"El dodo de la isla Mauricio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Lo local puede revertirse con reintroducciones; lo global es para siempre."}},{"slug":"animales-3.s4.p3","orden":3,"grupo":"animales-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Extinciones en la historia","cuerpo":["Siempre hubo extinciones: la mayoría de las especies que existieron ya no existen. Pero según la IPBES, la plataforma científica sobre biodiversidad, la tasa actual de extinción es al menos decenas o cientos de veces mayor que el promedio de los últimos diez millones de años, y alrededor de un millón de especies de animales y plantas están amenazadas de extinción, muchas en las próximas décadas.","La diferencia con las grandes extinciones del pasado es que esta vez la causa principal son las actividades humanas."],"destacado":{"valor":"≈ 1 millón","texto":"de especies de animales y plantas estarían amenazadas de extinción, según la IPBES."}},"solucion":{}},{"slug":"animales-3.s4.p4","orden":4,"grupo":"animales-3.s4.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas especies de animales y plantas estarían amenazadas de extinción en el mundo, según la IPBES.","min":1000,"max":100000000,"paso":1,"unidad":"especies","escala":"log"},"solucion":{"valor":1000000,"banda":"log","explicacion":"Alrededor de un millón, según el informe global de la IPBES de 2019."}},{"slug":"animales-3.s4.p5","orden":5,"grupo":"animales-3.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las extinciones actuales ocurren al mismo ritmo que en los últimos millones de años.","razones":[{"id":"r1","texto":"Porque la tasa actual es decenas o cientos de veces mayor"},{"id":"r2","texto":"Porque ya no se extingue ninguna especie"},{"id":"r3","texto":"Porque las extinciones son siempre naturales"}]},"solucion":{"valor":false,"explicacion":"Según la IPBES, la tasa actual es al menos decenas o cientos de veces mayor que el promedio de los últimos diez millones de años.","clave":["r1"]}},{"slug":"animales-3.s4.p6","orden":6,"grupo":"animales-3.s4.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una especie llega a extinguirse.","items":[{"id":"i1","texto":"Se pierde y fragmenta su hábitat"},{"id":"i2","texto":"Las poblaciones se achican y quedan aisladas"},{"id":"i3","texto":"Pierden diversidad genética"},{"id":"i4","texto":"Son más vulnerables a enfermedades y eventos extremos"},{"id":"i5","texto":"Las últimas poblaciones desaparecen"},{"id":"i6","texto":"La especie se extingue de golpe sin ninguna señal previa"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La extinción suele ser un proceso: hay señales y tiempo para actuar."}},{"slug":"animales-3.s4.p7","orden":7,"grupo":"animales-3.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El vórtice de extinción","cuerpo":["Cuando una población se vuelve muy chica, entra en un círculo vicioso: pierde diversidad genética, hay más cruzas entre parientes, nacen menos crías sanas, la población se achica más, y así sucesivamente. Se lo llama vórtice de extinción. Por eso actuar a tiempo, cuando todavía hay poblaciones razonables, es mucho más efectivo que intentar salvar a los últimos individuos."]},"solucion":{}},{"slug":"animales-3.s4.p8","orden":8,"grupo":"animales-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de 1.000 individuos baja un 10 % por año. ¿Cuántos quedan después de dos años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":810,"tolerancia":1,"explicacion":"1.000 × 0,9 × 0,9 ≈ 810. Una caída del mismo porcentaje cada año se acumula: en pocos años la población pierde una parte grande."}},{"slug":"animales-3.s4.p8.v2","orden":8,"grupo":"animales-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de 500 individuos baja un 20 % por año. ¿Cuántos quedan después de dos años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":320,"tolerancia":1,"explicacion":"500 × 0,8 × 0,8 ≈ 320. Una caída del mismo porcentaje cada año se acumula: en pocos años la población pierde una parte grande."}},{"slug":"animales-3.s4.p8.v3","orden":8,"grupo":"animales-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de 2.000 individuos baja un 15 % por año. ¿Cuántos quedan después de dos años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":1445,"tolerancia":1,"explicacion":"2.000 × 0,85 × 0,85 ≈ 1.445. Una caída del mismo porcentaje cada año se acumula: en pocos años la población pierde una parte grande."}},{"slug":"animales-3.s4.p9","orden":9,"grupo":"animales-3.s4.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Extinción local"},{"id":"a2","texto":"Extinta en estado silvestre"},{"id":"a3","texto":"Extinción global"},{"id":"a4","texto":"Vórtice de extinción"}],"derecha":[{"id":"b1","texto":"Desaparece de una zona pero sobrevive en otras"},{"id":"b2","texto":"Solo sobrevive en cautiverio"},{"id":"b3","texto":"No queda ningún individuo en el mundo"},{"id":"b4","texto":"Círculo vicioso de poblaciones muy chicas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para entender el camino hacia la extinción."}},{"slug":"animales-3.s4.p10","orden":10,"grupo":"animales-3.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene proteger una especie cuando todavía tiene poblaciones razonables?","opciones":[{"id":"o1","texto":"Porque es más fácil y barato que salvar a los últimos"},{"id":"o2","texto":"Porque las especies abundantes nunca se extinguen"},{"id":"o3","texto":"Porque así se evita estudiarla"},{"id":"o4","texto":"Porque las especies raras no importan"}]},"solucion":{"clave":["o1"],"explicacion":"Prevenir es más barato y más efectivo, como en casi todo lo ambiental.","por_opcion":{"o3":"Al contrario: estudiarla es parte de protegerla a tiempo."}}},{"slug":"animales-3.s4.p11","orden":11,"grupo":"animales-3.s4.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La extinción global es irreversible."},{"id":"s2","texto":"Una especie extinta en el mundo se puede traer de vuelta fácilmente."},{"id":"s3","texto":"El yaguareté desapareció de gran parte de la región pampeana."},{"id":"s4","texto":"Las poblaciones muy chicas se recuperan solas sin ayuda."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender la extinción ayuda a actuar antes.","por_opcion":{"s2":"Una extinción global es para siempre.","s4":"Pueden caer en un vórtice de extinción si no se actúa."}}},{"slug":"animales-3.s4.p12","orden":12,"grupo":"animales-3.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pasa en una población atrapada en un vórtice de extinción? Marcá todo.","opciones":[{"id":"o1","texto":"Pierde diversidad genética"},{"id":"o2","texto":"Aumentan las cruzas entre parientes"},{"id":"o3","texto":"Nacen menos crías sanas"},{"id":"o4","texto":"Se recupera sola sin ayuda"},{"id":"o5","texto":"Gana diversidad genética nueva"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Cada efecto empeora al siguiente. Por eso se actúa antes de que la población sea muy chica."}},{"slug":"animales-3.s4.p13","orden":13,"grupo":"animales-3.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Si una especie desaparece de una zona pero vive en otras, es una extinción {{0}}; la extinción global es {{1}}; y según la IPBES, alrededor de un {{2}} de especies están amenazadas.","banco":[{"id":"w1","texto":"local"},{"id":"w2","texto":"irreversible"},{"id":"w3","texto":"millón"},{"id":"w4","texto":"total"},{"id":"w5","texto":"temporal"},{"id":"w6","texto":"mil"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las ideas clave para entender qué es una extinción y su ritmo actual."}},{"slug":"animales-3.s4.p14","orden":14,"grupo":"animales-3.s4.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas situaciones de menor a mayor gravedad.","items":[{"id":"i1","texto":"Una especie baja en una provincia pero abunda en el resto del país"},{"id":"i2","texto":"Desaparece de una región entera"},{"id":"i3","texto":"Solo quedan ejemplares en zoológicos"},{"id":"i4","texto":"No queda ningún ejemplar en el mundo"}],"extremos":["Menos grave","Más grave"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada paso es más difícil de revertir. El último, imposible.","valores":{"i1":"menor","i2":"extinción local","i3":"extinta en estado silvestre","i4":"extinción global"}}}]},{"slug":"animales-3.s5","orden":5,"tipo":"leccion","titulo_es":"Recuperar especies","bajada_es":"Proteger el hábitat, reducir amenazas, criar y liberar: cómo se ha logrado que especies en peligro vuelvan.","minutos":11,"pasos":[{"slug":"animales-3.s5.p1","orden":1,"grupo":"animales-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las herramientas","cuerpo":["Recuperar una especie amenazada requiere combinar herramientas: proteger y restaurar su hábitat, reducir las amenazas directas (caza, venenos, invasoras), y a veces criar en cautiverio y liberar individuos, o trasladarlos para reintroducirlos donde desaparecieron. También hace falta investigación, monitoreo y trabajo con las comunidades locales."]},"solucion":{}},{"slug":"animales-3.s5.p2","orden":2,"grupo":"animales-3.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas se usan para recuperar especies amenazadas? Marcá todas.","opciones":[{"id":"o1","texto":"Proteger y restaurar su hábitat"},{"id":"o2","texto":"Reducir amenazas como venenos e invasoras"},{"id":"o3","texto":"Cría en cautiverio y liberación"},{"id":"o4","texto":"Trabajo con comunidades locales"},{"id":"o5","texto":"Esperar sin hacer nada a que se recupere"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La recuperación combina muchas herramientas a la vez."}},{"slug":"animales-3.s5.p3","orden":3,"grupo":"animales-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Casos que funcionaron","cuerpo":["La ballena franca austral, cazada casi hasta la extinción, se recuperó en buena medida desde que se prohibió su caza, y hoy se la ve cada año en Península Valdés. En los Esteros del Iberá, especies que habían desaparecido —como el oso hormiguero, el pecarí de collar, el guacamayo rojo y el yaguareté— volvieron gracias a proyectos de reintroducción. El Programa de Conservación del Cóndor Andino cría y libera cóndores y trabaja contra el envenenamiento."]},"solucion":{}},{"slug":"animales-3.s5.p4","orden":4,"grupo":"animales-3.s5.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada caso con la herramienta principal que lo hizo posible.","izquierda":[{"id":"a1","texto":"Ballena franca austral"},{"id":"a2","texto":"Oso hormiguero en Iberá"},{"id":"a3","texto":"Cóndor andino"},{"id":"a4","texto":"Macá tobiano"}],"derecha":[{"id":"b1","texto":"Prohibición de la caza"},{"id":"b2","texto":"Reintroducción"},{"id":"b3","texto":"Cría, liberación y lucha contra venenos"},{"id":"b4","texto":"Control del visón y protección de lagunas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada especie necesitó una estrategia distinta según su amenaza."}},{"slug":"animales-3.s5.p5","orden":5,"grupo":"animales-3.s5.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se reintroduce una especie.","items":[{"id":"i1","texto":"Se verifica que la causa de su desaparición ya no existe"},{"id":"i2","texto":"Se preparan individuos, a veces criados en cautiverio"},{"id":"i3","texto":"Se liberan en el lugar con seguimiento"},{"id":"i4","texto":"Se monitorea si sobreviven y se reproducen"},{"id":"i5","texto":"Se forma una población silvestre estable"},{"id":"i6","texto":"Se liberan animales sin verificar si la amenaza sigue"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin resolver la causa, cualquier liberación fracasa."}},{"slug":"animales-3.s5.p6","orden":6,"grupo":"animales-3.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para reintroducir una especie alcanza con liberar individuos en el lugar donde vivía.","razones":[{"id":"r1","texto":"Porque primero hay que resolver la causa y hacer seguimiento"},{"id":"r2","texto":"Porque las especies liberadas nunca sobreviven"},{"id":"r3","texto":"Porque no hace falta estudiar el lugar"}]},"solucion":{"valor":false,"explicacion":"Primero hay que resolver la causa de su desaparición (caza, falta de hábitat, invasoras), y después liberar con seguimiento. Si no, la historia se repite.","clave":["r1"]}},{"slug":"animales-3.s5.p7","orden":7,"grupo":"animales-3.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El papel de las personas","cuerpo":["Muchas amenazas dependen de decisiones humanas locales: cebos envenenados, caza, perros sueltos, compra de fauna silvestre, desmontes. Por eso los programas exitosos trabajan con productores, comunidades y escuelas, y ofrecen alternativas: por ejemplo, formas de proteger el ganado sin veneno, o ingresos por turismo de naturaleza que hacen más valiosa la especie viva."]},"solucion":{}},{"slug":"animales-3.s5.p8","orden":8,"grupo":"animales-3.s5.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción ayuda o perjudica a una especie amenazada?","grupos":[{"id":"g1","nombre":"Ayuda"},{"id":"g2","nombre":"Perjudica"}],"items":[{"id":"i1","texto":"Proteger el ganado con perros guardianes en lugar de veneno"},{"id":"i2","texto":"Poner cebos envenenados"},{"id":"i3","texto":"Turismo responsable de observación"},{"id":"i4","texto":"Soltar perros en zonas de fauna"},{"id":"i5","texto":"Denunciar la venta de aves silvestres"},{"id":"i6","texto":"Comprar un cardenal amarillo en una feria"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las decisiones cotidianas de las personas pueden salvar o condenar a una especie."}},{"slug":"animales-3.s5.p9","orden":9,"grupo":"animales-3.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población reintroducida de 50 individuos crece un 10 % por año. ¿Cuántos individuos hay después de 3 años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":67,"tolerancia":1,"explicacion":"50 × 1,1³ ≈ 67. Con las amenazas controladas, una población puede crecer de forma sostenida."}},{"slug":"animales-3.s5.p9.v2","orden":9,"grupo":"animales-3.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población reintroducida de 30 individuos crece un 15 % por año. ¿Cuántos individuos hay después de 3 años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":46,"tolerancia":1,"explicacion":"30 × 1,15³ ≈ 46. Con las amenazas controladas, una población puede crecer de forma sostenida."}},{"slug":"animales-3.s5.p9.v3","orden":9,"grupo":"animales-3.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población reintroducida de 100 individuos crece un 8 % por año. ¿Cuántos individuos hay después de 3 años? Redondeá al entero.","unidad":"individuos","decimales":0},"solucion":{"valor":126,"tolerancia":1,"explicacion":"100 × 1,08³ ≈ 126. Con las amenazas controladas, una población puede crecer de forma sostenida."}},{"slug":"animales-3.s5.p10","orden":10,"grupo":"animales-3.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una zona ganadera se envenenan cóndores con cebos puestos para zorros. ¿Qué medida atiende la causa?","opciones":[{"id":"o1","texto":"Trabajar con productores en alternativas al veneno"},{"id":"o2","texto":"Liberar más cóndores sin cambiar nada"},{"id":"o3","texto":"Prohibir que los cóndores vuelen sobre los campos"},{"id":"o4","texto":"Esperar que los cóndores aprendan a evitar los cebos"}]},"solucion":{"clave":["o1"],"explicacion":"Sin atacar la causa, liberar más cóndores solo agrega más víctimas.","por_opcion":{"o3":"Imposible y absurdo: la causa es el veneno, no el vuelo."}}},{"slug":"animales-3.s5.p11","orden":11,"grupo":"animales-3.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones de recuperación de la más de fondo a la más de emergencia.","items":[{"id":"i1","texto":"Proteger y restaurar el hábitat"},{"id":"i2","texto":"Controlar las amenazas directas"},{"id":"i3","texto":"Reintroducir en zonas recuperadas"},{"id":"i4","texto":"Criar en cautiverio a los últimos individuos"}],"extremos":["Más de fondo","Más de emergencia"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo de fondo sostiene todo; la cría en cautiverio es un salvavidas para los casos extremos.","valores":{"i1":"de fondo","i2":"clave","i3":"cuando la causa se resolvió","i4":"emergencia"}}},{"slug":"animales-3.s5.p12","orden":12,"grupo":"animales-3.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La ballena franca austral se recuperó tras prohibirse su caza."},{"id":"s2","texto":"Las reintroducciones funcionan aunque la amenaza siga igual."},{"id":"s3","texto":"En Iberá se reintrodujeron especies desaparecidas."},{"id":"s4","texto":"Las comunidades locales no tienen ningún papel en la conservación."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Recuperar especies es posible, y hay casos argentinos que lo muestran.","por_opcion":{"s2":"Sin resolver la causa, la especie vuelve a desaparecer.","s4":"Son clave: muchas amenazas dependen de decisiones locales."}}},{"slug":"animales-3.s5.p13","orden":13,"grupo":"animales-3.s5.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos años pasaron entre la protección internacional de la ballena franca austral (1935) y 2025.","min":10,"max":200,"paso":5,"unidad":"años","escala":"lineal"},"solucion":{"valor":90,"banda":"lineal","explicacion":"Unos 90 años. La recuperación de especies longevas lleva décadas: la ballena franca todavía no volvió a sus números originales."}},{"slug":"animales-3.s5.p14","orden":14,"grupo":"animales-3.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de reintroducir una especie hay que resolver la {{0}} de su desaparición; la ballena franca se recuperó al prohibirse su {{1}}; y en {{2}} volvieron especies desaparecidas.","banco":[{"id":"w1","texto":"causa"},{"id":"w2","texto":"caza"},{"id":"w3","texto":"Iberá"},{"id":"w4","texto":"foto"},{"id":"w5","texto":"observación"},{"id":"w6","texto":"Ushuaia"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las claves de la recuperación de especies."}}]},{"slug":"animales-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: especies en peligro","bajada_es":"Lista Roja, especies argentinas, vulnerabilidad, extinción y recuperación, mezclados.","minutos":8,"pasos":[{"slug":"animales-3.s6.p1","orden":1,"grupo":"animales-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Especies en peligro». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el plan para el macá tobiano","bajada_es":"El macá tobiano vive solo en lagunas de la meseta de Santa Cruz. Con los datos, priorizá las acciones para salvarlo.","minutos":10,"pasos":[{"slug":"animales-3.s7.p1","orden":1,"grupo":"animales-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Quedan pocos cientos de macás tobianos, en unas pocas lagunas de la meseta santacruceña. Sus amenazas principales son el visón americano, que depreda huevos y pichones; las truchas introducidas en algunas lagunas, que compiten por el alimento; gaviotas que aumentaron cerca de basurales; y cambios en las lagunas por el clima y el viento.","Un equipo de conservación puede instalar guardianes en las colonias durante la temporada de cría, controlar visones, evitar nuevas siembras de truchas y monitorear las lagunas."]},"solucion":{}},{"slug":"animales-3.s7.p2","orden":2,"grupo":"animales-3.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una colonia había 80 nidos y con guardianes y control de visones el éxito de cría sube del 30 % al 60 %, ¿cuántos nidos más tienen éxito?","unidad":"nidos","decimales":0,"contexto":"80 nidos; éxito de cría del 30 % al 60 %."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"Antes: 80 × 30 % = 24. Después: 80 × 60 % = 48. Diferencia: 24 nidos más con éxito en una sola temporada."}},{"slug":"animales-3.s7.p3","orden":3,"grupo":"animales-3.s7.p3","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las acciones por urgencia, de la más urgente a la menos.","items":[{"id":"i1","texto":"Guardianes y control de visones en las colonias"},{"id":"i2","texto":"No sembrar truchas en lagunas con macá"},{"id":"i3","texto":"Controlar basurales que atraen gaviotas"},{"id":"i4","texto":"Investigar cómo cambia el clima en la meseta"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero se frena la mortalidad directa; después se reducen las otras amenazas y se estudia lo de fondo.","valores":{"i1":"frena la mortalidad ya","i2":"evita una amenaza nueva","i3":"reduce otra amenaza","i4":"clave a largo plazo"}}},{"slug":"animales-3.s7.p4","orden":4,"grupo":"animales-3.s7.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las amenazas del macá tobiano.","grupos":[{"id":"g1","nombre":"Especies introducidas"},{"id":"g2","nombre":"Efectos humanos indirectos"}],"items":[{"id":"i1","texto":"Visón americano"},{"id":"i2","texto":"Gaviotas que aumentaron por basurales"},{"id":"i3","texto":"Truchas sembradas"},{"id":"i4","texto":"Cambios en las lagunas por el clima"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Varias amenazas a la vez: por eso hace falta un plan con varias acciones."}},{"slug":"animales-3.s7.p5","orden":5,"grupo":"animales-3.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué no alcanza con proteger una sola laguna?","opciones":[{"id":"o1","texto":"Porque la especie depende de varias lagunas"},{"id":"o2","texto":"Porque el macá tobiano vive en todo el país"},{"id":"o3","texto":"Porque una laguna protegida atrae más visones"},{"id":"o4","texto":"Porque las lagunas no se pueden proteger"}]},"solucion":{"clave":["o1"],"explicacion":"Las especies con poblaciones chicas y fragmentadas necesitan que se protejan todos sus sitios clave.","por_opcion":{"o3":"No es el motivo: la especie usa varias lagunas a lo largo de los años."}}},{"slug":"animales-3.s7.p6","orden":6,"grupo":"animales-3.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan? Marcá todo.","opciones":[{"id":"o1","texto":"Guardianes en las colonias durante la cría"},{"id":"o2","texto":"Control del visón americano"},{"id":"o3","texto":"Evitar nuevas siembras de truchas en lagunas con macá"},{"id":"o4","texto":"Monitoreo anual de la población"},{"id":"o5","texto":"Capturar todos los macás y llevarlos a un zoológico lejos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Proteger en su lugar, controlar amenazas y medir resultados."}},{"slug":"animales-3.s7.p7","orden":7,"grupo":"animales-3.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el macá tobiano está En peligro crítico, ya no hay nada que hacer.","razones":[{"id":"r1","texto":"Porque especies en situación crítica se han recuperado con acción"},{"id":"r2","texto":"Porque las especies CR se extinguen siempre"},{"id":"r3","texto":"Porque la categoría no se puede cambiar nunca"}]},"solucion":{"valor":false,"explicacion":"Hay casos de especies que se recuperaron desde situaciones críticas. Con acciones bien dirigidas, la población puede estabilizarse y crecer.","clave":["r1"]}},{"slug":"animales-3.s7.p8","orden":8,"grupo":"animales-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El equipo escribe el plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pondremos guardianes en las colonias durante la cría."},{"id":"s2","texto":"Sembraremos truchas para que los pescadores apoyen el proyecto."},{"id":"s3","texto":"Controlaremos visones en las lagunas clave."},{"id":"s4","texto":"No mediremos la población para no molestar a las aves."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan ataca las causas, se sostiene en el tiempo y se mide.","por_opcion":{"s2":"Las truchas compiten por el alimento del macá.","s4":"Sin monitoreo no se sabe si el plan funciona; se puede medir sin molestar."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-4","rama":"animales","orden":4,"nivel":2,"titulo_es":"Qué amenaza a la biodiversidad","bajada_es":"Desmontes, castores, tráfico de fauna, venenos y un clima que cambia: los cinco grandes motores de pérdida de biodiversidad y cómo frenarlos.","objetivos_es":["Nombrar y ordenar los cinco motores directos de pérdida de biodiversidad","Explicar la pérdida y fragmentación del hábitat con el caso del Gran Chaco","Analizar el impacto de las especies exóticas invasoras en Argentina","Reconocer el tráfico de fauna y cómo lo regulan las leyes y CITES","Relacionar contaminación y cambio climático con la pérdida de especies"],"repasa":["animales-3","animales-1","plantas-2","oceanos-2"],"requiere_tronco":2,"fuentes":["ipbes-global","ley-bosques-26331","global-forest-watch","invasoras-mayds","cites","ley-22421-fauna","red-centros-rescate","ipcc-ar6","ipbes-polinizadores"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-4.s1","orden":1,"tipo":"leccion","titulo_es":"Los cinco motores","bajada_es":"Qué dice la ciencia sobre las causas directas de la pérdida de biodiversidad.","minutos":11,"pasos":[{"slug":"animales-4.s1.p1","orden":1,"grupo":"animales-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un diagnóstico mundial","cuerpo":["En 2019, la IPBES —la plataforma intergubernamental que reúne a cientos de especialistas en biodiversidad— publicó la evaluación global más completa hasta ese momento. Identificó cinco motores directos de pérdida de biodiversidad, ordenados por su impacto a nivel mundial: el cambio en el uso de la tierra y el mar, la explotación directa de organismos, el cambio climático, la contaminación y las especies exóticas invasoras.","Detrás de estos motores hay causas indirectas: cuánto y cómo producimos y consumimos, el crecimiento de las ciudades, el comercio y las políticas públicas."],"lista":["1 · Cambio en el uso de la tierra y el mar","2 · Explotación directa (caza, pesca, tala, captura)","3 · Cambio climático","4 · Contaminación","5 · Especies exóticas invasoras"]},"solucion":{}},{"slug":"animales-4.s1.p2","orden":2,"grupo":"animales-4.s1.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los motores de pérdida de biodiversidad según su impacto a nivel mundial, de mayor a menor, como los ordenó la IPBES.","items":[{"id":"i1","texto":"Cambio en el uso de la tierra y el mar"},{"id":"i2","texto":"Explotación directa de organismos"},{"id":"i3","texto":"Cambio climático"},{"id":"i4","texto":"Contaminación"},{"id":"i5","texto":"Especies exóticas invasoras"}],"extremos":["Mayor impacto","Menor impacto"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Que un motor esté último en el promedio mundial no significa que sea menor en todos lados: en islas, las invasoras suelen ser la primera causa."}},{"slug":"animales-4.s1.p3","orden":3,"grupo":"animales-4.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué motor corresponde cada caso?","grupos":[{"id":"g1","nombre":"Cambio en el uso de la tierra"},{"id":"g2","nombre":"Explotación directa"},{"id":"g3","nombre":"Especies invasoras"}],"items":[{"id":"i1","texto":"Desmontar un bosque para sembrar soja"},{"id":"i2","texto":"Capturar cardenales para venderlos"},{"id":"i3","texto":"Castores que inundan bosques fueguinos"},{"id":"i4","texto":"Rellenar un humedal para construir barrios"},{"id":"i5","texto":"Pescar más merluza de la que se repone"},{"id":"i6","texto":"Mejillón dorado que tapa cañerías"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Clasificar las amenazas ayuda a elegir la herramienta correcta para cada una."}},{"slug":"animales-4.s1.p4","orden":4,"grupo":"animales-4.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La magnitud","cuerpo":["Según la IPBES, alrededor del 75 % de la superficie terrestre fue alterada de forma significativa por las actividades humanas, y cerca del 66 % de los océanos recibe impactos acumulados. Más del 85 % de los humedales que existían en 1700 se habían perdido para el año 2000."],"destacado":{"valor":"75 %","texto":"de la superficie terrestre fue alterada de forma significativa por actividades humanas, según la IPBES."}},"solucion":{}},{"slug":"animales-4.s1.p5","orden":5,"grupo":"animales-4.s1.p5","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la superficie terrestre fue alterada de forma significativa por las actividades humanas, según la IPBES.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Alrededor del 75 %. Quedan pocas zonas terrestres sin una huella humana fuerte, y por eso son tan valiosas."}},{"slug":"animales-4.s1.p6","orden":6,"grupo":"animales-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 1700 había 200 humedales en una región y se perdió el 85 %, ¿cuántos quedan?","unidad":"humedales","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Queda el 15 %: 200 × 0,15 = 30. Los humedales están entre los ecosistemas que más se perdieron en el mundo."}},{"slug":"animales-4.s1.p6.v2","orden":6,"grupo":"animales-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 1700 había 120 humedales en una región y se perdió el 85 %, ¿cuántos quedan?","unidad":"humedales","decimales":0},"solucion":{"valor":18,"tolerancia":0.5,"explicacion":"Queda el 15 %: 120 × 0,15 = 18. Los humedales están entre los ecosistemas que más se perdieron en el mundo."}},{"slug":"animales-4.s1.p6.v3","orden":6,"grupo":"animales-4.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en 1700 había 80 humedales en una región y se perdió el 85 %, ¿cuántos quedan?","unidad":"humedales","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"Queda el 15 %: 80 × 0,15 = 12. Los humedales están entre los ecosistemas que más se perdieron en el mundo."}},{"slug":"animales-4.s1.p7","orden":7,"grupo":"animales-4.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En el mar, otro orden","cuerpo":["El orden cambia según el ambiente. En tierra firme y en el agua dulce, el primer motor es el cambio en el uso del suelo: desmontes, agricultura, ciudades, represas. En el mar, en cambio, el primer motor es la explotación directa, sobre todo la pesca."]},"solucion":{}},{"slug":"animales-4.s1.p8","orden":8,"grupo":"animales-4.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Según la IPBES, ¿cuál es el principal motor de pérdida de biodiversidad en los océanos?","opciones":[{"id":"o1","texto":"La explotación directa, sobre todo la pesca"},{"id":"o2","texto":"Las especies invasoras que llegan en barcos"},{"id":"o3","texto":"El cambio en el uso de la tierra"},{"id":"o4","texto":"La luz artificial de las ciudades costeras"}]},"solucion":{"clave":["o1"],"explicacion":"En el mar, la pesca es el motor número uno. Lo viste en la unidad de pesca: muchas poblaciones se pescan por encima de lo que se reponen.","por_opcion":{"o3":"Es el primero en tierra firme; en el mar pesa más la pesca."}}},{"slug":"animales-4.s1.p9","orden":9,"grupo":"animales-4.s1.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las especies exóticas invasoras son una amenaza menor en todo el mundo, porque figuran últimas en el ranking de la IPBES.","razones":[{"id":"r1","texto":"Porque el ranking es un promedio y varía según el lugar"},{"id":"r2","texto":"Porque las invasoras no causan ningún daño"},{"id":"r3","texto":"Porque el ranking es igual en todos los lugares"}]},"solucion":{"valor":false,"explicacion":"El ranking es un promedio mundial. En islas y en algunos ecosistemas, como Tierra del Fuego, las invasoras son la amenaza principal.","clave":["r1"]}},{"slug":"animales-4.s1.p10","orden":10,"grupo":"animales-4.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada motor con un ejemplo argentino.","izquierda":[{"id":"a1","texto":"Cambio en el uso de la tierra"},{"id":"a2","texto":"Explotación directa"},{"id":"a3","texto":"Contaminación"},{"id":"a4","texto":"Cambio climático"}],"derecha":[{"id":"b1","texto":"Desmonte en el Gran Chaco"},{"id":"b2","texto":"Tráfico de tortugas terrestres"},{"id":"b3","texto":"Cóndores intoxicados con plomo"},{"id":"b4","texto":"Retroceso de los glaciares andinos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los cinco motores tienen casos concretos en Argentina."}},{"slug":"animales-4.s1.p11","orden":11,"grupo":"animales-4.s1.p11","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una causa indirecta a la pérdida de especies.","items":[{"id":"i1","texto":"Crece la demanda mundial de granos y carne"},{"id":"i2","texto":"Sube el precio de la tierra agrícola"},{"id":"i3","texto":"Se desmontan bosques para ampliar cultivos"},{"id":"i4","texto":"Las especies del bosque pierden su hábitat"},{"id":"i5","texto":"Los bosques crecen más rápido con la demanda"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las causas indirectas, como el consumo y el comercio, empujan a los motores directos."}},{"slug":"animales-4.s1.p12","orden":12,"grupo":"animales-4.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La IPBES identificó cinco motores directos de pérdida de biodiversidad."},{"id":"s2","texto":"El cambio climático es el motor número uno en tierra firme."},{"id":"s3","texto":"En el mar, el primer motor es la pesca."},{"id":"s4","texto":"Más de la mitad de los humedales del mundo sigue intacta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer el diagnóstico evita perder tiempo en causas menores.","por_opcion":{"s2":"En tierra el primero es el cambio en el uso del suelo; el clima es el tercero en el ranking global.","s4":"Se perdió más del 85 % de los humedales que había en 1700."}}},{"slug":"animales-4.s1.p13","orden":13,"grupo":"animales-4.s1.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles son causas indirectas, que empujan a los motores directos? Marcá todas.","opciones":[{"id":"o1","texto":"Los patrones de producción y consumo"},{"id":"o2","texto":"El comercio internacional"},{"id":"o3","texto":"Las políticas públicas"},{"id":"o4","texto":"La fotosíntesis de las plantas"},{"id":"o5","texto":"La migración natural de las aves"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La fotosíntesis y las migraciones son procesos naturales, no causas de pérdida."}},{"slug":"animales-4.s1.p14","orden":14,"grupo":"animales-4.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El primer motor de pérdida de biodiversidad en tierra es el cambio en el {{0}} del suelo; en el mar, la {{1}}; y según la IPBES se perdió más del 85 % de los {{2}}.","banco":[{"id":"w1","texto":"uso"},{"id":"w2","texto":"pesca"},{"id":"w3","texto":"humedales"},{"id":"w4","texto":"color"},{"id":"w5","texto":"lluvia"},{"id":"w6","texto":"desiertos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave del diagnóstico mundial sobre biodiversidad."}}]},{"slug":"animales-4.s2","orden":2,"tipo":"leccion","titulo_es":"Sin casa: desmonte y fragmentación","bajada_es":"El Gran Chaco, la Ley de Bosques y por qué un bosque partido en pedazos no es lo mismo que un bosque entero.","minutos":14,"pasos":[{"slug":"animales-4.s2.p1","orden":1,"grupo":"animales-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Gran Chaco","cuerpo":["El Gran Chaco es el segundo bosque más grande de Sudamérica, después de la Amazonia, y se extiende por Argentina, Paraguay y Bolivia. Es uno de los lugares del mundo donde más rápido se perdieron bosques en las últimas décadas, sobre todo para sembrar soja y criar ganado. En Argentina, la mayor parte del desmonte de bosque nativo ocurrió en las provincias chaqueñas: Santiago del Estero, Salta, Chaco y Formosa.","Allí viven el yaguareté, el tatú carreta, el oso hormiguero y el chancho quimilero, que se creyó extinto hasta que fue redescubierto en 1975."]},"solucion":{}},{"slug":"animales-4.s2.p2","orden":2,"grupo":"animales-4.s2.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué se desmontó tanto bosque en el Gran Chaco?","opciones":[{"id":"o1","texto":"Para ampliar la agricultura y la ganadería"},{"id":"o2","texto":"Porque los bosques se secaron solos"},{"id":"o3","texto":"Para construir grandes ciudades"},{"id":"o4","texto":"Por una plaga que atacó a los árboles"}]},"solucion":{"clave":["o1"],"explicacion":"La expansión agropecuaria es la principal causa de desmonte en el Chaco argentino.","por_opcion":{"o3":"Las ciudades ocupan poco; la mayor parte se transformó en campos de cultivo y pasturas."}}},{"slug":"animales-4.s2.p3","orden":3,"grupo":"animales-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Ley de Bosques","cuerpo":["En 2007 se sancionó la Ley 26.331, de Presupuestos Mínimos de Protección de los Bosques Nativos. Obliga a cada provincia a hacer un ordenamiento territorial de sus bosques con tres categorías de colores. Rojo: muy alto valor de conservación, no se puede desmontar. Amarillo: valor medio, se permite un uso sostenible, pero no el desmonte. Verde: bajo valor de conservación, se puede transformar con evaluación de impacto ambiental."]},"solucion":{}},{"slug":"animales-4.s2.p4","orden":4,"grupo":"animales-4.s2.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Según la Ley de Bosques, ¿qué se permite en cada zona?","grupos":[{"id":"g1","nombre":"Rojo (muy alto valor)"},{"id":"g2","nombre":"Amarillo (valor medio)"},{"id":"g3","nombre":"Verde (bajo valor)"}],"items":[{"id":"i1","texto":"Conservar sin transformar"},{"id":"i2","texto":"Aprovechamiento sostenible de madera"},{"id":"i3","texto":"Desmonte con evaluación de impacto"},{"id":"i4","texto":"Investigación científica"},{"id":"i5","texto":"Turismo de naturaleza"},{"id":"i6","texto":"Transformación a cultivos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La ley no prohíbe todo: ordena qué se puede hacer en cada lugar según su valor."}},{"slug":"animales-4.s2.p5","orden":5,"grupo":"animales-4.s2.p5","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos millones de hectáreas de bosque nativo perdió Argentina entre 1998 y 2020, aproximadamente.","min":0.5,"max":30,"paso":0.5,"unidad":"millones de ha","escala":"lineal"},"solucion":{"valor":6.5,"banda":"lineal","explicacion":"Alrededor de 6 a 7 millones de hectáreas, según los monitoreos oficiales, la mayor parte en la región chaqueña. Es más que toda la superficie de la provincia de Jujuy."}},{"slug":"animales-4.s2.p6","orden":6,"grupo":"animales-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Fragmentación","cuerpo":["Cuando un bosque no desaparece del todo sino que queda partido en parches, se habla de fragmentación. Los parches chicos no alcanzan para las especies que necesitan grandes territorios, como el yaguareté. Además, en los bordes del parche entra más luz, viento, ganado, perros y cazadores: es el efecto borde. Y los animales que no cruzan campos abiertos quedan aislados en cada parche."]},"solucion":{}},{"slug":"animales-4.s2.p7","orden":7,"grupo":"animales-4.s2.p7","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Un bosque, dos formas de partirlo","planteo":"Un campo de 100 ha de bosque se desmonta a la mitad. En la opción A queda un bloque de 50 ha. En la opción B quedan 10 parches de 5 ha cada uno.","pasos":["Las dos opciones conservan la misma superficie: 50 ha.","Pero en la opción B hay muchos más bordes: cada parche chico tiene mucho borde para poco interior.","El interior del bosque, lejos de los bordes, es donde viven las especies más sensibles."],"resultado":"Con la misma superficie, el bloque grande conserva mucho más hábitat de interior que diez parches chicos."},"solucion":{}},{"slug":"animales-4.s2.p8","orden":8,"grupo":"animales-4.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Con la misma superficie de bosque, ¿qué conserva más hábitat para especies sensibles?","opciones":[{"id":"o1","texto":"Un bloque grande y continuo"},{"id":"o2","texto":"Muchos parches chicos separados"},{"id":"o3","texto":"Da exactamente igual si la superficie es la misma"},{"id":"o4","texto":"Un parche largo y muy angosto"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso, en la planificación, importa tanto cómo queda el bosque como cuánto queda.","por_opcion":{"o3":"No da igual: los parches chicos tienen más borde y menos interior."}}},{"slug":"animales-4.s2.p9","orden":9,"grupo":"animales-4.s2.p9","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parche cuadrado de bosque mide 1.000 m de lado. Si el efecto borde entra 100 m desde cada lado, ¿qué porcentaje del parche es interior? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Parche cuadrado de 1000 m de lado; efecto borde de 100 m."},"solucion":{"valor":64,"tolerancia":1,"explicacion":"El interior es un cuadrado de 800 m de lado: 800² ÷ 1.000² ≈ 64 %. Cuanto más chico el parche, mayor la proporción de borde."}},{"slug":"animales-4.s2.p9.v2","orden":9,"grupo":"animales-4.s2.p9","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parche cuadrado de bosque mide 2.000 m de lado. Si el efecto borde entra 100 m desde cada lado, ¿qué porcentaje del parche es interior? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Parche cuadrado de 2000 m de lado; efecto borde de 100 m."},"solucion":{"valor":81,"tolerancia":1,"explicacion":"El interior es un cuadrado de 1800 m de lado: 1.800² ÷ 2.000² ≈ 81 %. Cuanto más chico el parche, mayor la proporción de borde."}},{"slug":"animales-4.s2.p9.v3","orden":9,"grupo":"animales-4.s2.p9","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parche cuadrado de bosque mide 500 m de lado. Si el efecto borde entra 100 m desde cada lado, ¿qué porcentaje del parche es interior? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Parche cuadrado de 500 m de lado; efecto borde de 100 m."},"solucion":{"valor":36,"tolerancia":1,"explicacion":"El interior es un cuadrado de 300 m de lado: 300² ÷ 500² ≈ 36 %. Cuanto más chico el parche, mayor la proporción de borde."}},{"slug":"animales-4.s2.p10","orden":10,"grupo":"animales-4.s2.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corredores","cuerpo":["Una forma de reducir la fragmentación es conectar los parches con corredores biológicos: franjas de bosque a lo largo de ríos, cortinas de árboles nativos entre campos, o pasos de fauna bajo o sobre las rutas. Así los animales pueden moverse, encontrar pareja y recolonizar parches."]},"solucion":{}},{"slug":"animales-4.s2.p11","orden":11,"grupo":"animales-4.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un corredor ayuda a una especie aislada.","items":[{"id":"i1","texto":"Un corredor une dos parches de bosque"},{"id":"i2","texto":"Los animales pueden pasar de un parche al otro"},{"id":"i3","texto":"Se cruzan individuos de poblaciones distintas"},{"id":"i4","texto":"Aumenta la diversidad genética"},{"id":"i5","texto":"La población es más resistente"},{"id":"i6","texto":"Los animales dejan de necesitar bosque"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Conectar parches evita que cada uno quede como una isla. Es lo contrario del vórtice de extinción."}},{"slug":"animales-4.s2.p12","orden":12,"grupo":"animales-4.s2.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pasa en los bordes de un parche de bosque? Marcá todo.","opciones":[{"id":"o1","texto":"Entra más luz y viento"},{"id":"o2","texto":"Llegan más fácilmente ganado y perros"},{"id":"o3","texto":"Hay más acceso para cazadores"},{"id":"o4","texto":"Aumenta la humedad del interior"},{"id":"o5","texto":"Desaparecen todas las especies exóticas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El borde cambia las condiciones del bosque varios metros hacia adentro."}},{"slug":"animales-4.s2.p13","orden":13,"grupo":"animales-4.s2.p13","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si en una provincia queda la mitad del bosque original, se conserva la mitad de las especies de bosque, sin importar cómo queden los parches.","razones":[{"id":"r1","texto":"Porque la forma y la conexión de los parches también importan"},{"id":"r2","texto":"Porque se conservan siempre todas las especies"},{"id":"r3","texto":"Porque las especies no dependen del bosque"}]},"solucion":{"valor":false,"explicacion":"Depende mucho de la forma: parches chicos y aislados pierden especies aunque la superficie total sea la misma.","clave":["r1"]}},{"slug":"animales-4.s2.p14","orden":14,"grupo":"animales-4.s2.p14","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Desmonte"},{"id":"a2","texto":"Fragmentación"},{"id":"a3","texto":"Efecto borde"},{"id":"a4","texto":"Corredor biológico"}],"derecha":[{"id":"b1","texto":"Eliminar el bosque para otro uso"},{"id":"b2","texto":"Bosque partido en parches separados"},{"id":"b3","texto":"Cambios en los márgenes de un parche"},{"id":"b4","texto":"Franja que conecta parches de hábitat"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para leer cualquier mapa de bosques."}},{"slug":"animales-4.s2.p15","orden":15,"grupo":"animales-4.s2.p15","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El Gran Chaco es el segundo bosque más grande de Sudamérica."},{"id":"s2","texto":"La Ley de Bosques prohíbe cualquier uso de todos los bosques."},{"id":"s3","texto":"El efecto borde hace que los parches chicos pierdan calidad."},{"id":"s4","texto":"El chancho quimilero se extinguió en 1975."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los detalles importan cuando se discute qué bosque conservar.","por_opcion":{"s2":"Ordena usos según categorías: solo en rojo no se transforma.","s4":"Al revés: en 1975 fue redescubierto, cuando se lo creía extinto."}}},{"slug":"animales-4.s2.p16","orden":16,"grupo":"animales-4.s2.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley de Bosques usa tres colores: rojo, amarillo y {{0}}; un bosque partido en parches está {{1}}; y una franja que une parches es un {{2}}.","banco":[{"id":"w1","texto":"verde"},{"id":"w2","texto":"fragmentado"},{"id":"w3","texto":"corredor"},{"id":"w4","texto":"azul"},{"id":"w5","texto":"reforestado"},{"id":"w6","texto":"desmonte"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave para entender el desmonte."}}]},{"slug":"animales-4.s3","orden":3,"tipo":"leccion","titulo_es":"Invasores: el caso del castor","bajada_es":"Especies traídas de otros continentes que se expanden sin control y transforman los ecosistemas.","minutos":12,"pasos":[{"slug":"animales-4.s3.p1","orden":1,"grupo":"animales-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Exótica no es lo mismo que invasora","cuerpo":["Una especie exótica es la que llegó a un lugar llevada por las personas, a propósito o por accidente. La mayoría no logra establecerse. Una especie es invasora cuando, además, se reproduce sin ayuda, se expande y causa daños al ambiente, a la economía o a la salud. Lo viste con las plantas; con los animales pasa lo mismo."]},"solucion":{}},{"slug":"animales-4.s3.p2","orden":2,"grupo":"animales-4.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El castor en Tierra del Fuego","cuerpo":["En 1946 se liberaron en Tierra del Fuego unas pocas decenas de castores traídos de Canadá, con la idea de crear una industria peletera. La industria no prosperó, pero los castores sí: sin predadores naturales, hoy se estiman en decenas de miles en el archipiélago. Construyen diques que inundan y matan bosques de lenga y ñire, árboles que, a diferencia de los de Canadá, no rebrotan tras ser cortados.","Argentina y Chile acordaron en 2008 un plan binacional para restaurar los ambientes afectados y erradicar al castor del archipiélago."]},"solucion":{}},{"slug":"animales-4.s3.p3","orden":3,"grupo":"animales-4.s3.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el castor transforma el bosque fueguino.","items":[{"id":"i1","texto":"Se liberan castores sin predadores naturales"},{"id":"i2","texto":"La población crece y se expande por los ríos"},{"id":"i3","texto":"Construyen diques que inundan el bosque"},{"id":"i4","texto":"Los árboles inundados mueren y no rebrotan"},{"id":"i5","texto":"Cambian los ríos, el suelo y las especies del lugar"},{"id":"i6","texto":"Los pumas fueguinos controlan a los castores"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"En Tierra del Fuego no hay pumas ni osos que coman castores: por eso se expandieron sin freno."}},{"slug":"animales-4.s3.p4","orden":4,"grupo":"animales-4.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el castor se volvió invasor en Tierra del Fuego y no en Canadá, su lugar de origen?","opciones":[{"id":"o1","texto":"Porque en Tierra del Fuego no tiene predadores"},{"id":"o2","texto":"Porque en Canadá hace más frío para los castores"},{"id":"o3","texto":"Porque en Tierra del Fuego hay más ríos"},{"id":"o4","texto":"Porque los castores fueguinos son otra especie"}]},"solucion":{"clave":["o1"],"explicacion":"En su lugar de origen, los predadores y la competencia mantienen a raya a la población. Afuera, esos controles faltan.","por_opcion":{"o3":"El problema no es la cantidad de ríos, sino la falta de controles naturales."}}},{"slug":"animales-4.s3.p5","orden":5,"grupo":"animales-4.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Otros invasores en Argentina","cuerpo":["El mejillón dorado llegó desde Asia en el agua de lastre de barcos, a comienzos de los 90, al Río de la Plata; hoy tapiza cañerías de tomas de agua y centrales. El jabalí europeo, traído para caza, rompe suelos y cultivos. La rana toro, traída para criaderos, come ranas nativas y dispersa enfermedades. El estornino pinto, escapado de jaulas, compite por huecos para anidar con aves nativas."]},"solucion":{}},{"slug":"animales-4.s3.p6","orden":6,"grupo":"animales-4.s3.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada especie invasora con cómo llegó.","izquierda":[{"id":"a1","texto":"Castor"},{"id":"a2","texto":"Mejillón dorado"},{"id":"a3","texto":"Jabalí europeo"},{"id":"a4","texto":"Estornino pinto"}],"derecha":[{"id":"b1","texto":"Liberado para la industria peletera"},{"id":"b2","texto":"En el agua de lastre de barcos"},{"id":"b3","texto":"Traído para la caza deportiva"},{"id":"b4","texto":"Escapado del comercio de aves de jaula"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Muchas invasiones empezaron con una decisión humana que parecía inofensiva."}},{"slug":"animales-4.s3.p7","orden":7,"grupo":"animales-4.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Llegó a propósito o por accidente?","grupos":[{"id":"g1","nombre":"A propósito"},{"id":"g2","nombre":"Por accidente"}],"items":[{"id":"i1","texto":"Castor para peletería"},{"id":"i2","texto":"Mejillón dorado en el lastre de barcos"},{"id":"i3","texto":"Jabalí para caza"},{"id":"i4","texto":"Ratas en barcos"},{"id":"i5","texto":"Rana toro para criaderos"},{"id":"i6","texto":"Semillas pegadas a la ropa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las introducciones intencionales pueden prevenirse con reglas; las accidentales, con controles en puertos y fronteras."}},{"slug":"animales-4.s3.p8","orden":8,"grupo":"animales-4.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir, detectar, controlar","cuerpo":["Con las invasoras, prevenir es mucho más barato que controlar. La estrategia tiene tres pasos: prevenir que lleguen (controles en puertos, reglas para importar especies), detectar temprano y erradicar si aparecen, y controlar o manejar las que ya se establecieron. Argentina tiene una Estrategia Nacional sobre Especies Exóticas Invasoras."]},"solucion":{}},{"slug":"animales-4.s3.p9","orden":9,"grupo":"animales-4.s3.p9","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las acciones contra una invasora de la más barata a la más cara.","items":[{"id":"i1","texto":"Evitar que la especie llegue"},{"id":"i2","texto":"Detectarla y erradicarla apenas aparece"},{"id":"i3","texto":"Controlarla cuando ya está en una región"},{"id":"i4","texto":"Restaurar el ecosistema después de décadas de daño"}],"extremos":["Más barata","Más cara"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más tarde se actúa, más caro y difícil es. Con el castor, se actuó tarde.","valores":{"i1":"prevención","i2":"respuesta temprana","i3":"control","i4":"restauración"}}},{"slug":"animales-4.s3.p10","orden":10,"grupo":"animales-4.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población invasora de 50 individuos se duplica cada 5 años. ¿Cuántos habrá en 15 años?","unidad":"individuos","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"15 años son 3 duplicaciones: 50 × 8 = 400. Por eso la detección temprana es clave: el crecimiento se acelera."}},{"slug":"animales-4.s3.p10.v2","orden":10,"grupo":"animales-4.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población invasora de 40 individuos se duplica cada 5 años. ¿Cuántos habrá en 20 años?","unidad":"individuos","decimales":0},"solucion":{"valor":640,"tolerancia":12.8,"explicacion":"20 años son 4 duplicaciones: 40 × 16 = 640. Por eso la detección temprana es clave: el crecimiento se acelera."}},{"slug":"animales-4.s3.p10.v3","orden":10,"grupo":"animales-4.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población invasora de 60 individuos se duplica cada 5 años. ¿Cuántos habrá en 10 años?","unidad":"individuos","decimales":0},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"10 años son 2 duplicaciones: 60 × 4 = 240. Por eso la detección temprana es clave: el crecimiento se acelera."}},{"slug":"animales-4.s3.p11","orden":11,"grupo":"animales-4.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Soltar en la naturaleza una mascota exótica que ya no se quiere es una forma de liberarla sin daño.","razones":[{"id":"r1","texto":"Porque puede volverse invasora o transmitir enfermedades"},{"id":"r2","texto":"Porque las mascotas no sobreviven nunca afuera"},{"id":"r3","texto":"Porque la ley obliga a liberarlas"}]},"solucion":{"valor":false,"explicacion":"Puede convertirse en invasora, transmitir enfermedades o morir. Es una de las vías por las que llegaron especies como la tortuga de orejas rojas.","clave":["r1"]}},{"slug":"animales-4.s3.p12","orden":12,"grupo":"animales-4.s3.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones previenen nuevas invasiones? Marcá todas.","opciones":[{"id":"o1","texto":"Controlar el agua de lastre de los barcos"},{"id":"o2","texto":"No liberar mascotas exóticas"},{"id":"o3","texto":"Limpiar el calzado al pasar entre áreas protegidas"},{"id":"o4","texto":"Traer especies nuevas para \"enriquecer\" un lugar"},{"id":"o5","texto":"Soltar peces exóticos en lagunas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La prevención depende de controles oficiales y también de decisiones de cada persona."}},{"slug":"animales-4.s3.p13","orden":13,"grupo":"animales-4.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los castores llegaron a Tierra del Fuego en 1946."},{"id":"s2","texto":"La lenga rebrota enseguida después de que el castor la corta."},{"id":"s3","texto":"El mejillón dorado llegó en el agua de lastre de barcos."},{"id":"s4","texto":"Toda especie exótica es invasora."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las invasoras son una amenaza seria, pero hay que distinguirlas bien.","por_opcion":{"s2":"A diferencia de los árboles de Canadá, la lenga y el ñire no rebrotan.","s4":"La mayoría no se establece; solo algunas se vuelven invasoras."}}},{"slug":"animales-4.s3.p14","orden":14,"grupo":"animales-4.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una exótica que se expande y causa daño es {{0}}; el castor fue liberado para la industria {{1}}; y con las invasoras, lo más barato es {{2}}.","banco":[{"id":"w1","texto":"invasora"},{"id":"w2","texto":"peletera"},{"id":"w3","texto":"prevenir"},{"id":"w4","texto":"nativa"},{"id":"w5","texto":"lechera"},{"id":"w6","texto":"restaurar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las claves para entender y enfrentar a las especies invasoras."}}]},{"slug":"animales-4.s4","orden":4,"tipo":"leccion","titulo_es":"Capturados: caza y tráfico de fauna","bajada_es":"Por qué el comercio de animales silvestres amenaza especies y qué dicen las leyes y la CITES.","minutos":12,"pasos":[{"slug":"animales-4.s4.p1","orden":1,"grupo":"animales-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El tráfico de fauna","cuerpo":["El tráfico de fauna silvestre es el comercio ilegal de animales vivos, sus partes o sus productos. En Argentina, algunas de las especies más traficadas son aves canoras como el cardenal amarillo y el cardenal común, loros como el loro hablador, y la tortuga terrestre argentina, vendida como mascota. Muchos animales mueren en la captura, el encierro y el transporte, antes de llegar a la venta."]},"solucion":{}},{"slug":"animales-4.s4.p2","orden":2,"grupo":"animales-4.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del tráfico de un cardenal amarillo.","items":[{"id":"i1","texto":"Un trampero captura aves en el monte"},{"id":"i2","texto":"Las encierra en cajas y las transporta ocultas"},{"id":"i3","texto":"Muchas mueren por estrés, calor o falta de agua"},{"id":"i4","texto":"Las sobrevivientes se venden en ferias o por internet"},{"id":"i5","texto":"Cada venta financia nuevas capturas"},{"id":"i6","texto":"El comprador ayuda a que el ave vuelva a su hábitat"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Comprar un animal silvestre no lo rescata: pone en marcha la próxima captura."}},{"slug":"animales-4.s4.p3","orden":3,"grupo":"animales-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La tortuga terrestre","cuerpo":["La tortuga terrestre argentina vive en zonas secas del centro y norte del país. Está categorizada como Vulnerable. Crece muy despacio, vive décadas y pone pocos huevos, por lo que cada ejemplar que se saca de la naturaleza es difícil de reponer. En los hogares suele vivir mal: necesita sol, temperaturas adecuadas y una dieta especial, y muchas mueren en los primeros años."]},"solucion":{}},{"slug":"animales-4.s4.p4","orden":4,"grupo":"animales-4.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la extracción de tortugas terrestres afecta tanto a la especie?","opciones":[{"id":"o1","texto":"Porque crece lento y pone pocos huevos"},{"id":"o2","texto":"Porque se reproduce varias veces por año"},{"id":"o3","texto":"Porque en las casas vive más años"},{"id":"o4","texto":"Porque es una especie exótica invasora"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste en la unidad anterior: las especies de vida lenta son las más vulnerables a perder individuos.","por_opcion":{"o3":"En general vive peor: le faltan sol, temperatura y dieta adecuadas."}}},{"slug":"animales-4.s4.p5","orden":5,"grupo":"animales-4.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las leyes","cuerpo":["En Argentina, la Ley 22.421 de Conservación de la Fauna Silvestre regula la caza y el comercio de animales silvestres, y el comercio de especies protegidas es un delito. A nivel internacional, la CITES es un tratado que regula el comercio entre países de especies amenazadas. Tiene tres apéndices: en el Apéndice I están las especies más amenazadas, cuyo comercio internacional está prohibido salvo excepciones; en el II, especies cuyo comercio se permite con controles y permisos; y en el III, especies que un país protege y pide ayuda a los demás para controlar."]},"solucion":{}},{"slug":"animales-4.s4.p6","orden":6,"grupo":"animales-4.s4.p6","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada apéndice de la CITES con lo que significa.","izquierda":[{"id":"a1","texto":"Apéndice I"},{"id":"a2","texto":"Apéndice II"},{"id":"a3","texto":"Apéndice III"}],"derecha":[{"id":"b1","texto":"Comercio internacional prohibido salvo excepciones"},{"id":"b2","texto":"Comercio permitido con permisos y controles"},{"id":"b3","texto":"Especie protegida por un país que pide colaboración"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"La CITES no prohíbe todo el comercio de fauna: lo regula según el nivel de riesgo."}},{"slug":"animales-4.s4.p7","orden":7,"grupo":"animales-4.s4.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un loro se vende en una feria, seguro es legal.","razones":[{"id":"r1","texto":"Porque muchas ventas de fauna silvestre son ilegales"},{"id":"r2","texto":"Porque en las ferias solo hay animales de criadero"},{"id":"r3","texto":"Porque los loros no están protegidos"}]},"solucion":{"valor":false,"explicacion":"Muchas aves silvestres se venden ilegalmente en ferias y por internet. Un animal legal tiene documentación que acredita su origen.","clave":["r1"]}},{"slug":"animales-4.s4.p8","orden":8,"grupo":"animales-4.s4.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué hacer y qué no hacer ante la fauna silvestre?","grupos":[{"id":"g1","nombre":"Conviene"},{"id":"g2","nombre":"No conviene"}],"items":[{"id":"i1","texto":"Denunciar la venta de fauna a las autoridades"},{"id":"i2","texto":"Comprar un cardenal \"para liberarlo\""},{"id":"i3","texto":"Llamar a un centro de rescate si encontrás un animal herido"},{"id":"i4","texto":"Llevarse una tortuga del campo"},{"id":"i5","texto":"Elegir mascotas domésticas, como perros o gatos adoptados"},{"id":"i6","texto":"Compartir en redes fotos con fauna silvestre como mascota"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Comprar para liberar también financia el tráfico. La fauna silvestre no es mascota."}},{"slug":"animales-4.s4.p9","orden":9,"grupo":"animales-4.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se capturan 100 aves y el 60 % muere antes de la venta, ¿cuántas llegan vivas a venderse?","unidad":"aves","decimales":0,"contexto":"Captura de 100 aves; muere el 60 % antes de la venta."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"100 × 40 % = 40. Por cada ave en una jaula, muchas otras murieron en el camino."}},{"slug":"animales-4.s4.p9.v2","orden":9,"grupo":"animales-4.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se capturan 200 aves y el 70 % muere antes de la venta, ¿cuántas llegan vivas a venderse?","unidad":"aves","decimales":0,"contexto":"Captura de 200 aves; muere el 70 % antes de la venta."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"200 × 30 % = 60. Por cada ave en una jaula, muchas otras murieron en el camino."}},{"slug":"animales-4.s4.p9.v3","orden":9,"grupo":"animales-4.s4.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se capturan 150 aves y el 50 % muere antes de la venta, ¿cuántas llegan vivas a venderse?","unidad":"aves","decimales":0,"contexto":"Captura de 150 aves; muere el 50 % antes de la venta."},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"150 × 50 % = 75. Por cada ave en una jaula, muchas otras murieron en el camino."}},{"slug":"animales-4.s4.p10","orden":10,"grupo":"animales-4.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La caza y el plomo","cuerpo":["La caza también afecta a especies que no son su objetivo. Los cóndores y otras aves carroñeras se intoxican al comer restos de animales cazados con munición de plomo. Además, la caza furtiva de especies protegidas sigue ocurriendo. Las alternativas incluyen munición sin plomo, controles y trabajo con los cazadores."]},"solucion":{}},{"slug":"animales-4.s4.p11","orden":11,"grupo":"animales-4.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo se intoxica un cóndor con plomo si nadie le dispara?","opciones":[{"id":"o1","texto":"Come restos de animales cazados con munición de plomo"},{"id":"o2","texto":"Respira el humo de las fábricas de ciudades cercanas"},{"id":"o3","texto":"Toma agua de ríos con mucha sal durante la sequía"},{"id":"o4","texto":"Anida en paredes de roca con minerales de plomo"}]},"solucion":{"clave":["o1"],"explicacion":"Los fragmentos de munición quedan en la carroña. Pasar a munición sin plomo evita el problema.","por_opcion":{"o3":"La sal no aporta plomo; la fuente es la munición en la carroña."}}},{"slug":"animales-4.s4.p12","orden":12,"grupo":"animales-4.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El comercio de especies protegidas es ilegal en Argentina."},{"id":"s2","texto":"Comprar un ave silvestre para liberarla ayuda a la especie."},{"id":"s3","texto":"La CITES regula el comercio internacional de especies amenazadas."},{"id":"s4","texto":"La tortuga terrestre se reproduce rápido y abunda."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Mucha información falsa sobre fauna circula en redes. Conviene chequear.","por_opcion":{"s2":"Financia la próxima captura; lo correcto es denunciar.","s4":"Crece lento, pone pocos huevos y está categorizada como Vulnerable."}}},{"slug":"animales-4.s4.p13","orden":13,"grupo":"animales-4.s4.p13","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué especies argentinas sufren el tráfico de fauna? Marcá todas.","opciones":[{"id":"o1","texto":"Cardenal amarillo"},{"id":"o2","texto":"Tortuga terrestre argentina"},{"id":"o3","texto":"Loro hablador"},{"id":"o4","texto":"Paloma doméstica"},{"id":"o5","texto":"Gorrión"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La paloma doméstica y el gorrión son especies exóticas abundantes que no son objeto del tráfico."}},{"slug":"animales-4.s4.p14","orden":14,"grupo":"animales-4.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En Argentina, la fauna silvestre está protegida por la Ley {{0}}; el tratado internacional que regula su comercio es la {{1}}; y si ves venta de fauna, lo mejor es {{2}}.","banco":[{"id":"w1","texto":"22.421"},{"id":"w2","texto":"CITES"},{"id":"w3","texto":"denunciar"},{"id":"w4","texto":"26.331"},{"id":"w5","texto":"OMS"},{"id":"w6","texto":"comprar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las herramientas legales contra el tráfico de fauna silvestre."}}]},{"slug":"animales-4.s5","orden":5,"tipo":"leccion","titulo_es":"Venenos y un clima que cambia","bajada_es":"Plaguicidas, plásticos, luz artificial y calentamiento: amenazas menos visibles que se suman a las demás.","minutos":11,"pasos":[{"slug":"animales-4.s5.p1","orden":1,"grupo":"animales-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La contaminación","cuerpo":["La contaminación afecta a la fauna de muchas formas. Algunos insecticidas dañan a abejas y otros polinizadores. Los fertilizantes en exceso alimentan algas que agotan el oxígeno del agua. Los plásticos se enredan en animales o son ingeridos: tortugas marinas y aves comen bolsas y fragmentos que confunden con alimento. La luz artificial desorienta a aves migratorias e insectos, y el ruido interfiere con la comunicación de muchos animales."]},"solucion":{}},{"slug":"animales-4.s5.p2","orden":2,"grupo":"animales-4.s5.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada contaminante con su efecto en la fauna.","izquierda":[{"id":"a1","texto":"Insecticidas"},{"id":"a2","texto":"Exceso de fertilizantes"},{"id":"a3","texto":"Bolsas plásticas en el mar"},{"id":"a4","texto":"Luz artificial de noche"}],"derecha":[{"id":"b1","texto":"Dañan a abejas y otros polinizadores"},{"id":"b2","texto":"Algas que agotan el oxígeno del agua"},{"id":"b3","texto":"Tortugas que las confunden con alimento"},{"id":"b4","texto":"Aves e insectos desorientados"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada contaminante actúa distinto, y muchos se combinan en el mismo lugar."}},{"slug":"animales-4.s5.p3","orden":3,"grupo":"animales-4.s5.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La luz artificial de noche es un tipo de contaminación que afecta a la fauna.","razones":[{"id":"r1","texto":"Porque desorienta aves e insectos y altera comportamientos"},{"id":"r2","texto":"Porque los animales nocturnos necesitan más luz"},{"id":"r3","texto":"Porque solo afecta a las personas"}]},"solucion":{"valor":true,"explicacion":"Sí: desorienta a aves migratorias que vuelan de noche, atrae y mata insectos, y altera el comportamiento de muchos animales.","clave":["r1"]}},{"slug":"animales-4.s5.p4","orden":4,"grupo":"animales-4.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El clima","cuerpo":["El cambio climático ya mueve a las especies. Según el IPCC, alrededor de la mitad de las especies estudiadas desplazó su distribución hacia los polos o, en tierra, hacia zonas más altas, buscando temperaturas más frescas. Las que viven en cumbres o en lugares muy fríos se quedan sin lugar a donde ir. También se producen desacoples: por ejemplo, plantas que florecen antes, cuando sus polinizadores todavía no llegaron."],"destacado":{"valor":"≈ 50 %","texto":"de las especies estudiadas ya desplazó su distribución hacia los polos o hacia zonas más altas, según el IPCC."}},"solucion":{}},{"slug":"animales-4.s5.p5","orden":5,"grupo":"animales-4.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una especie de rana vive en la cima de una sierra. Si el clima se calienta, ¿qué problema tiene?","opciones":[{"id":"o1","texto":"No puede subir más porque ya está en la cima"},{"id":"o2","texto":"Tiene que bajar al valle, donde hace más frío"},{"id":"o3","texto":"Ninguno, porque las ranas no sienten la temperatura"},{"id":"o4","texto":"Se vuelve una especie invasora en la cima"}]},"solucion":{"clave":["o1"],"explicacion":"Las especies de montaña se desplazan hacia arriba; en la cumbre se acaba el espacio.","por_opcion":{"o3":"Los anfibios son muy sensibles a la temperatura y la humedad."}}},{"slug":"animales-4.s5.p6","orden":6,"grupo":"animales-4.s5.p6","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un desacople entre una flor y su polinizador.","items":[{"id":"i1","texto":"Las temperaturas de primavera suben antes"},{"id":"i2","texto":"La planta florece más temprano"},{"id":"i3","texto":"El polinizador sigue llegando en la fecha de siempre"},{"id":"i4","texto":"Cuando llega, quedan pocas flores"},{"id":"i5","texto":"La planta produce menos semillas y el polinizador come menos"},{"id":"i6","texto":"El polinizador adelanta su viaje leyendo el calendario"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las especies que dependen entre sí pueden desincronizarse si responden a señales distintas."}},{"slug":"animales-4.s5.p7","orden":7,"grupo":"animales-4.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las amenazas se suman","cuerpo":["Las amenazas rara vez actúan solas. Un bosque fragmentado es más vulnerable a incendios, que son más frecuentes con sequías más intensas; los animales aislados en parches no pueden desplazarse cuando el clima cambia; y las invasoras aprovechan los ambientes alterados. Por eso las estrategias que reducen varias amenazas a la vez, como conservar y conectar hábitats, son las más efectivas."]},"solucion":{}},{"slug":"animales-4.s5.p8","orden":8,"grupo":"animales-4.s5.p8","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cómo se potencian las amenazas entre sí? Marcá todos los ejemplos correctos.","opciones":[{"id":"o1","texto":"Un parche aislado impide que las especies se muden cuando el clima cambia"},{"id":"o2","texto":"Las sequías aumentan los incendios en bosques ya fragmentados"},{"id":"o3","texto":"Las invasoras aprovechan los ambientes degradados"},{"id":"o4","texto":"La contaminación reduce el efecto del cambio climático"},{"id":"o5","texto":"Los incendios eliminan a todas las especies invasoras"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las amenazas combinadas pueden causar más daño que la suma de cada una por separado."}},{"slug":"animales-4.s5.p9","orden":9,"grupo":"animales-4.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por el calentamiento, una especie de montaña tiene que subir 300 m. Si la cima está 500 m por encima de donde vive hoy, ¿cuántos metros de margen le quedan hasta la cima?","unidad":"m","decimales":0,"contexto":"Desplazamiento necesario de 300 m; cima 500 m más arriba."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"500 − 300 = 200 m. Todavía tiene lugar, pero cada vez menos superficie, porque las montañas se angostan hacia arriba. Si el calentamiento sigue, se queda sin montaña."}},{"slug":"animales-4.s5.p9.v2","orden":9,"grupo":"animales-4.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por el calentamiento, una especie de montaña tiene que subir 450 m. Si la cima está 500 m por encima de donde vive hoy, ¿cuántos metros de margen le quedan hasta la cima?","unidad":"m","decimales":0,"contexto":"Desplazamiento necesario de 450 m; cima 500 m más arriba."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"500 − 450 = 50 m. Todavía tiene lugar, pero cada vez menos superficie, porque las montañas se angostan hacia arriba. Si el calentamiento sigue, se queda sin montaña."}},{"slug":"animales-4.s5.p9.v3","orden":9,"grupo":"animales-4.s5.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Por el calentamiento, una especie de montaña tiene que subir 200 m. Si la cima está 500 m por encima de donde vive hoy, ¿cuántos metros de margen le quedan hasta la cima?","unidad":"m","decimales":0,"contexto":"Desplazamiento necesario de 200 m; cima 500 m más arriba."},"solucion":{"valor":300,"tolerancia":6,"explicacion":"500 − 200 = 300 m. Todavía tiene lugar, pero cada vez menos superficie, porque las montañas se angostan hacia arriba. Si el calentamiento sigue, se queda sin montaña."}},{"slug":"animales-4.s5.p10","orden":10,"grupo":"animales-4.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué motor es cada caso?","grupos":[{"id":"g1","nombre":"Contaminación"},{"id":"g2","nombre":"Cambio climático"}],"items":[{"id":"i1","texto":"Insecticidas que dañan a las abejas"},{"id":"i2","texto":"Especies que suben por las montañas"},{"id":"i3","texto":"Plomo en la carroña"},{"id":"i4","texto":"Flores que se adelantan a sus polinizadores"},{"id":"i5","texto":"Plásticos en el estómago de tortugas"},{"id":"i6","texto":"Corales que se blanquean con el agua caliente"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Contaminación y clima son motores distintos, aunque suelan actuar juntos."}},{"slug":"animales-4.s5.p11","orden":11,"grupo":"animales-4.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas estrategias de la que reduce más amenazas a la vez a la que reduce menos.","items":[{"id":"i1","texto":"Conservar y conectar grandes áreas de hábitat"},{"id":"i2","texto":"Reducir el uso de insecticidas cerca de áreas naturales"},{"id":"i3","texto":"Apagar luces innecesarias en migración"},{"id":"i4","texto":"Rescatar un animal empetrolado"}],"extremos":["Más amenazas","Menos amenazas"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Todas ayudan, pero proteger el hábitat es la que más amenazas atiende al mismo tiempo.","valores":{"i1":"muchas amenazas","i2":"varias","i3":"una amenaza puntual","i4":"un individuo"}}},{"slug":"animales-4.s5.p12","orden":12,"grupo":"animales-4.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Muchas especies se están desplazando hacia los polos o hacia zonas más altas."},{"id":"s2","texto":"Las especies de cumbre pueden subir sin límite."},{"id":"s3","texto":"Algunos insecticidas afectan a los polinizadores."},{"id":"s4","texto":"Las amenazas siempre actúan de a una."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Contaminación y clima son amenazas menos visibles, pero están en todas partes.","por_opcion":{"s2":"En la cumbre se acaba la montaña: no tienen a dónde ir.","s4":"Suelen combinarse y potenciarse entre sí."}}},{"slug":"animales-4.s5.p13","orden":13,"grupo":"animales-4.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Con el calentamiento, muchas especies se mueven hacia los {{0}} o hacia zonas más {{1}}; y cuando las amenazas se combinan, suelen {{2}}.","banco":[{"id":"w1","texto":"polos"},{"id":"w2","texto":"altas"},{"id":"w3","texto":"potenciarse"},{"id":"w4","texto":"trópicos"},{"id":"w5","texto":"bajas"},{"id":"w6","texto":"anularse"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Cómo responden las especies a un clima que cambia."}}]},{"slug":"animales-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: las amenazas","bajada_es":"Motores, desmonte, invasoras, tráfico, contaminación y clima, mezclados.","minutos":8,"pasos":[{"slug":"animales-4.s6.p1","orden":1,"grupo":"animales-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Qué amenaza a la biodiversidad». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el diagnóstico de la reserva","bajada_es":"Una reserva del Chaco registró qué amenazas afectan a sus especies. Con los datos, decidí dónde poner el esfuerzo.","minutos":10,"pasos":[{"slug":"animales-4.s7.p1","orden":1,"grupo":"animales-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["El equipo de guardaparques revisó 40 especies de vertebrados de la reserva y anotó qué amenazas afectan a cada una. Una especie puede tener más de una amenaza."],"datos":{"tipo":"tabla","titulo":"Especies afectadas por cada amenaza (de 40 revisadas)","columnas":["Amenaza","Especies afectadas"],"filas":[["Desmonte en los campos vecinos","28"],["Caza furtiva","14"],["Perros sueltos","9"],["Incendios","12"],["Tráfico de fauna","6"]],"nota":"Datos ficticios para el ejercicio."}},"solucion":{}},{"slug":"animales-4.s7.p2","orden":2,"grupo":"animales-4.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de las especies revisadas está afectado por el desmonte en los campos vecinos?","unidad":"%","decimales":0,"contexto":"28 de 40 especies afectadas por el desmonte."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"28 ÷ 40 × 100 = 70 %. El desmonte, un cambio en el uso de la tierra, es la amenaza principal, igual que en el diagnóstico mundial."}},{"slug":"animales-4.s7.p3","orden":3,"grupo":"animales-4.s7.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las amenazas por cantidad de especies afectadas, de mayor a menor.","items":[{"id":"i1","texto":"Desmonte en los campos vecinos"},{"id":"i2","texto":"Caza furtiva"},{"id":"i3","texto":"Incendios"},{"id":"i4","texto":"Perros sueltos"},{"id":"i5","texto":"Tráfico de fauna"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ordenar los datos es el primer paso para priorizar.","valores":{"i1":"28","i2":"14","i3":"12","i4":"9","i5":"6"}}},{"slug":"animales-4.s7.p4","orden":4,"grupo":"animales-4.s7.p4","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como las especies pueden tener varias amenazas, la suma de la tabla (69) no es la cantidad de especies amenazadas.","razones":[{"id":"r1","texto":"Porque una especie puede aparecer en varias filas"},{"id":"r2","texto":"Porque la tabla tiene un error de suma"},{"id":"r3","texto":"Porque hay 69 especies en la reserva"}]},"solucion":{"valor":true,"explicacion":"Una misma especie aparece en varias filas. Solo se revisaron 40 especies, así que la suma de filas cuenta amenazas, no especies.","clave":["r1"]}},{"slug":"animales-4.s7.p5","orden":5,"grupo":"animales-4.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"El desmonte ocurre fuera de la reserva. ¿Qué acción lo atiende mejor?","opciones":[{"id":"o1","texto":"Acordar corredores y zonas de amortiguación con los vecinos"},{"id":"o2","texto":"Cerrar la reserva al público para que nadie entre"},{"id":"o3","texto":"Contratar más guardaparques solo dentro de la reserva"},{"id":"o4","texto":"Soltar más animales dentro de la reserva"}]},"solucion":{"clave":["o1"],"explicacion":"Una reserva no es una isla: lo que pasa alrededor define si sus especies sobreviven.","por_opcion":{"o3":"Ayuda con la caza, pero el desmonte ocurre afuera."}}},{"slug":"animales-4.s7.p6","orden":6,"grupo":"animales-4.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones ayudan con varias amenazas a la vez? Marcá todas.","opciones":[{"id":"o1","texto":"Conectar la reserva con corredores de bosque"},{"id":"o2","texto":"Patrullajes que controlen caza, perros y fuegos"},{"id":"o3","texto":"Trabajar con las comunidades vecinas"},{"id":"o4","texto":"Sembrar especies exóticas de crecimiento rápido"},{"id":"o5","texto":"Quemar los pastizales para \"limpiar\" la reserva"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las mejores acciones atienden varias amenazas y suman aliados."}},{"slug":"animales-4.s7.p7","orden":7,"grupo":"animales-4.s7.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada amenaza de la reserva con la acción más directa.","izquierda":[{"id":"a1","texto":"Desmonte en los campos vecinos"},{"id":"a2","texto":"Caza furtiva"},{"id":"a3","texto":"Perros sueltos"},{"id":"a4","texto":"Incendios"},{"id":"a5","texto":"Tráfico de fauna"}],"derecha":[{"id":"b1","texto":"Acuerdos con vecinos y corredores"},{"id":"b2","texto":"Patrullajes y controles"},{"id":"b3","texto":"Campañas de tenencia responsable"},{"id":"b4","texto":"Brigadas y cortafuegos"},{"id":"b5","texto":"Controles en rutas y denuncias"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada amenaza pide una herramienta distinta; un plan completo combina varias."}},{"slug":"animales-4.s7.p8","orden":8,"grupo":"animales-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El equipo redacta su informe. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"La principal amenaza es el desmonte en los campos vecinos."},{"id":"s2","texto":"Como el desmonte es afuera, no es asunto de la reserva."},{"id":"s3","texto":"Controlaremos perros sueltos y caza con patrullajes."},{"id":"s4","texto":"Hay 69 especies amenazadas en la reserva."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen diagnóstico lee bien los datos y actúa sobre lo que más pesa.","por_opcion":{"s2":"Afecta al 70 % de las especies: trabajar con los vecinos es prioritario.","s4":"Se revisaron 40 especies; 69 es la suma de amenazas, no de especies."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-5","rama":"animales","orden":5,"nivel":3,"titulo_es":"Convivir con la fauna en el paisaje","bajada_es":"Corredores, rutas que matan, pumas y ovejas, guanacos y vicuñas: cómo se diseñan paisajes donde la producción y la fauna puedan convivir.","objetivos_es":["Diseñar corredores de fauna a escala de paisaje","Analizar los atropellamientos de fauna y sus soluciones viales","Comparar métodos letales y no letales para reducir la depredación de ganado","Evaluar el uso sostenible de fauna silvestre, como el chaku de vicuñas","Proponer acuerdos de coexistencia entre productores y conservación"],"repasa":["animales-4","animales-3","animales-2","comunidad-4"],"requiere_tronco":3,"fuentes":["apn-atropellamiento-iguazu","apn-pasafaunas-iguazu","inta-perros-protectores","conicet-vicunas","cites","ley-22421-fauna","rewilding-argentina","parques-nacionales"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-5.s1","orden":1,"tipo":"leccion","titulo_es":"Paisajes conectados","bajada_es":"Áreas protegidas, corredores y \"pasaderas\": cómo se diseña un paisaje donde la fauna pueda moverse.","minutos":11,"pasos":[{"slug":"animales-5.s1.p1","orden":1,"grupo":"animales-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Islas que no alcanzan","cuerpo":["Las áreas protegidas son esenciales, pero muchas son demasiado chicas o están aisladas para sostener poblaciones sanas de especies que se mueven mucho, como el yaguareté, el puma o el tapir. Lo viste con la fragmentación: poblaciones aisladas pierden diversidad genética y pueden desaparecer. Por eso la conservación moderna piensa a escala de paisaje: áreas protegidas unidas por corredores y rodeadas de campos y bosques manejados de forma compatible con la fauna."]},"solucion":{}},{"slug":"animales-5.s1.p2","orden":2,"grupo":"animales-5.s1.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un área protegida aislada puede perder especies.","items":[{"id":"i1","texto":"El área queda rodeada de campos sin bosque"},{"id":"i2","texto":"Los animales no pueden entrar ni salir"},{"id":"i3","texto":"La población queda chica y aislada"},{"id":"i4","texto":"Aumentan las cruzas entre parientes"},{"id":"i5","texto":"La población se debilita y puede desaparecer"},{"id":"i6","texto":"El aislamiento aumenta la diversidad genética"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Proteger una isla no alcanza si está rodeada de un mar hostil."}},{"slug":"animales-5.s1.p3","orden":3,"grupo":"animales-5.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corredores y pasaderas","cuerpo":["Un corredor es una franja continua de hábitat que une dos áreas. Cuando no es posible un corredor continuo, se usan \"pasaderas\": parches de hábitat separados pero lo bastante cerca como para que los animales los usen como escalas. Los bordes de ríos y arroyos son corredores naturales: por eso conservar los bosques ribereños conecta paisajes enteros. En el Gran Chaco se proponen corredores para unir los últimos bosques donde vive el yaguareté."]},"solucion":{}},{"slug":"animales-5.s1.p4","orden":4,"grupo":"animales-5.s1.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento del paisaje con su función para la fauna.","izquierda":[{"id":"a1","texto":"Área protegida núcleo"},{"id":"a2","texto":"Corredor continuo"},{"id":"a3","texto":"Pasadera"},{"id":"a4","texto":"Campo con manejo compatible"}],"derecha":[{"id":"b1","texto":"Refugio con poblaciones estables"},{"id":"b2","texto":"Paso seguro entre áreas"},{"id":"b3","texto":"Parche que sirve de escala"},{"id":"b4","texto":"Zona que la fauna puede atravesar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un paisaje conectado combina protección estricta con usos compatibles."}},{"slug":"animales-5.s1.p5","orden":5,"grupo":"animales-5.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Qué tan ancho?","cuerpo":["No todos los corredores sirven a todas las especies. Un corredor angosto puede servir a aves o pequeños mamíferos, pero no a un yaguareté, que necesita cobertura amplia, poca presencia humana y presas. Además, un corredor muy angosto tiene mucho efecto borde: más luz, más perros, más cazadores. En general, cuanto más ancho y mejor conservado, más especies lo usan."]},"solucion":{}},{"slug":"animales-5.s1.p6","orden":6,"grupo":"animales-5.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un corredor de bosque mide 10 km de largo y 500 m de ancho. ¿Cuántas hectáreas ocupa? (1 ha = 10.000 m²)","unidad":"hectáreas","decimales":0,"contexto":"10 km de largo; 500 m de ancho."},"solucion":{"valor":500,"tolerancia":10,"explicacion":"10000 m × 500 m = 5.000.000 m² = 500 ha. Una superficie chica comparada con lo que conecta."}},{"slug":"animales-5.s1.p6.v2","orden":6,"grupo":"animales-5.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un corredor de bosque mide 5 km de largo y 1000 m de ancho. ¿Cuántas hectáreas ocupa? (1 ha = 10.000 m²)","unidad":"hectáreas","decimales":0,"contexto":"5 km de largo; 1000 m de ancho."},"solucion":{"valor":500,"tolerancia":10,"explicacion":"5000 m × 1000 m = 5.000.000 m² = 500 ha. Una superficie chica comparada con lo que conecta."}},{"slug":"animales-5.s1.p6.v3","orden":6,"grupo":"animales-5.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un corredor de bosque mide 20 km de largo y 200 m de ancho. ¿Cuántas hectáreas ocupa? (1 ha = 10.000 m²)","unidad":"hectáreas","decimales":0,"contexto":"20 km de largo; 200 m de ancho."},"solucion":{"valor":400,"tolerancia":8,"explicacion":"20000 m × 200 m = 4.000.000 m² = 400 ha. Una superficie chica comparada con lo que conecta."}},{"slug":"animales-5.s1.p7","orden":7,"grupo":"animales-5.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un corredor muy angosto puede no servir para un yaguareté?","opciones":[{"id":"o1","texto":"Tiene mucho borde, poca cobertura y más riesgos"},{"id":"o2","texto":"Porque los yaguaretés no caminan distancias largas"},{"id":"o3","texto":"Porque los yaguaretés solo cruzan por rutas"},{"id":"o4","texto":"Porque los corredores solo sirven para aves"}]},"solucion":{"clave":["o1"],"explicacion":"Cada especie necesita un corredor a su medida: los grandes carnívoros, los más amplios.","por_opcion":{"o3":"Evitan rutas y zonas con gente; necesitan cobertura."}}},{"slug":"animales-5.s1.p8","orden":8,"grupo":"animales-5.s1.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este elemento ayuda a conectar el paisaje o lo corta?","grupos":[{"id":"g1","nombre":"Ayuda a conectar"},{"id":"g2","nombre":"Corta la conexión"}],"items":[{"id":"i1","texto":"Bosque ribereño conservado"},{"id":"i2","texto":"Ruta sin pasos de fauna y con alta velocidad"},{"id":"i3","texto":"Cortinas de árboles nativos entre lotes"},{"id":"i4","texto":"Desmonte total entre dos bosques"},{"id":"i5","texto":"Pasafauna bajo una ruta"},{"id":"i6","texto":"Alambrado que atrapa animales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas decisiones productivas y viales pueden conectar o aislar."}},{"slug":"animales-5.s1.p9","orden":9,"grupo":"animales-5.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un área protegida es grande, no importa lo que pase alrededor.","razones":[{"id":"r1","texto":"Porque aun las grandes pierden especies si quedan aisladas"},{"id":"r2","texto":"Porque los animales nunca salen de las áreas protegidas"},{"id":"r3","texto":"Porque las áreas protegidas no tienen fauna"}]},"solucion":{"valor":false,"explicacion":"Aun las áreas grandes pierden especies si quedan aisladas. Los animales salen, entran y necesitan conectarse con otras poblaciones.","clave":["r1"]}},{"slug":"animales-5.s1.p10","orden":10,"grupo":"animales-5.s1.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos corredores según cuántas especies de mamíferos grandes podrían usarlo, de más a menos.","items":[{"id":"i1","texto":"Bosque de 2 km de ancho, sin rutas ni perros"},{"id":"i2","texto":"Bosque ribereño de 300 m, con poco tránsito"},{"id":"i3","texto":"Cortina de árboles de 20 m entre cultivos"},{"id":"i4","texto":"Fila de postes con alambrado"}],"extremos":["Más especies","Menos especies"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Ancho, calidad y tranquilidad definen quién puede usar un corredor.","valores":{"i1":"muchas","i2":"bastantes","i3":"pocas","i4":"ninguna"}}},{"slug":"animales-5.s1.p11","orden":11,"grupo":"animales-5.s1.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más útil a un corredor? Marcá todo.","opciones":[{"id":"o1","texto":"Ser ancho"},{"id":"o2","texto":"Tener vegetación nativa bien conservada"},{"id":"o3","texto":"Tener poca presencia de perros y cazadores"},{"id":"o4","texto":"Conectar áreas con poblaciones de fauna"},{"id":"o5","texto":"Cruzar rutas sin pasos de fauna"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un corredor es útil si la fauna realmente puede y quiere usarlo."}},{"slug":"animales-5.s1.p12","orden":12,"grupo":"animales-5.s1.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los bosques junto a ríos y arroyos funcionan como corredores naturales?","opciones":[{"id":"o1","texto":"Forman franjas continuas que cruzan paisajes enteros"},{"id":"o2","texto":"Porque la fauna solo toma agua de los ríos grandes"},{"id":"o3","texto":"Porque en los ríos no vive ningún tipo de fauna"},{"id":"o4","texto":"Porque las leyes prohíben cruzar campos abiertos"}]},"solucion":{"clave":["o1"],"explicacion":"Los ríos recorren largas distancias: conservar sus orillas conecta áreas lejanas a un costo bajo.","por_opcion":{"o3":"Son de los ambientes con más fauna; justamente por eso conectan."}}},{"slug":"animales-5.s1.p13","orden":13,"grupo":"animales-5.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de ordenamiento rural y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Conservaremos los bosques junto a los arroyos como corredores."},{"id":"s2","texto":"El corredor tendrá 10 metros de ancho para no ocupar campo."},{"id":"s3","texto":"Dejaremos parches de bosque cerca entre sí como pasaderas."},{"id":"s4","texto":"Las áreas protegidas se manejarán como islas, sin mirar el entorno."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Planificar a escala de paisaje es la clave de la conectividad.","por_opcion":{"s2":"Es demasiado angosto para la mayoría de la fauna grande.","s4":"Hay que pensar a escala de paisaje."}}},{"slug":"animales-5.s1.p14","orden":14,"grupo":"animales-5.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una franja continua que une áreas es un {{0}}; los parches separados que sirven de escala son {{1}}; y los bosques junto a ríos y arroyos son corredores {{2}}.","banco":[{"id":"w1","texto":"corredor"},{"id":"w2","texto":"pasaderas"},{"id":"w3","texto":"naturales"},{"id":"w4","texto":"alambrado"},{"id":"w5","texto":"murallas"},{"id":"w6","texto":"artificiales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para diseñar paisajes conectados."}}]},{"slug":"animales-5.s2","orden":2,"tipo":"leccion","titulo_es":"Rutas y fauna","bajada_es":"Animales atropellados, velocidad, pasafaunas y ecoductos: cómo hacer rutas que no maten.","minutos":11,"pasos":[{"slug":"animales-5.s2.p1","orden":1,"grupo":"animales-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un problema que crece","cuerpo":["Las rutas cortan hábitats y matan fauna. Según la Administración de Parques Nacionales, en las rutas del norte de Misiones mueren unos tres mil animales por año atropellados, cuando en la década de 1990 se estimaban unos quinientos. La causa principal es la velocidad: muchos conductores no respetan los límites de 60 km/h ni las señales en los tramos que atraviesan la selva. Entre las víctimas hay especies amenazadas, como el yaguareté, el puma, el tapir y el oso hormiguero."],"destacado":{"valor":"≈ 3.000","texto":"animales mueren atropellados por año en las rutas del norte de Misiones, según Parques Nacionales. En los años 90 eran unos 500."}},"solucion":{}},{"slug":"animales-5.s2.p2","orden":2,"grupo":"animales-5.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los atropellamientos pasaron de unos 500 por año a unos 3.000, ¿cuántas veces aumentaron?","unidad":"veces","decimales":0,"contexto":"De unos 500 a unos 3.000 atropellamientos por año."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"3.000 ÷ 500 = 6 veces más. Más tránsito, más velocidad y más rutas explican el aumento."}},{"slug":"animales-5.s2.p3","orden":3,"grupo":"animales-5.s2.p3","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la velocidad aumenta los atropellamientos.","items":[{"id":"i1","texto":"Un auto va a alta velocidad por un tramo de selva"},{"id":"i2","texto":"Un animal cruza la ruta"},{"id":"i3","texto":"El conductor lo ve tarde"},{"id":"i4","texto":"No alcanza a frenar"},{"id":"i5","texto":"El animal muere, y a veces también hay heridos en el auto"},{"id":"i6","texto":"A más velocidad, más tiempo para frenar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Bajar la velocidad da tiempo a ver y frenar: salva animales y personas."}},{"slug":"animales-5.s2.p4","orden":4,"grupo":"animales-5.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La distancia que recorre un auto mientras frena crece con el cuadrado de la velocidad. Si a 50 km/h necesita 14 m para frenar, ¿cuántos metros necesita a 100 km/h?","unidad":"m","decimales":0,"contexto":"14 m de frenado a 50 km/h; ahora a 100 km/h."},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"100 ÷ 50 = 2; al cuadrado da 4; 14 × 4 = 56 m, sin contar el tiempo de reacción. Por eso unos pocos km/h de más cambian tanto."}},{"slug":"animales-5.s2.p4.v2","orden":4,"grupo":"animales-5.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La distancia que recorre un auto mientras frena crece con el cuadrado de la velocidad. Si a 60 km/h necesita 20 m para frenar, ¿cuántos metros necesita a 90 km/h?","unidad":"m","decimales":0,"contexto":"20 m de frenado a 60 km/h; ahora a 90 km/h."},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"90 ÷ 60 = 1,5; al cuadrado da 2,25; 20 × 2,25 = 45 m, sin contar el tiempo de reacción. Por eso unos pocos km/h de más cambian tanto."}},{"slug":"animales-5.s2.p4.v3","orden":4,"grupo":"animales-5.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La distancia que recorre un auto mientras frena crece con el cuadrado de la velocidad. Si a 40 km/h necesita 9 m para frenar, ¿cuántos metros necesita a 80 km/h?","unidad":"m","decimales":0,"contexto":"9 m de frenado a 40 km/h; ahora a 80 km/h."},"solucion":{"valor":36,"tolerancia":0.72,"explicacion":"80 ÷ 40 = 2; al cuadrado da 4; 9 × 4 = 36 m, sin contar el tiempo de reacción. Por eso unos pocos km/h de más cambian tanto."}},{"slug":"animales-5.s2.p5","orden":5,"grupo":"animales-5.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las soluciones","cuerpo":["Hay soluciones probadas. Controlar la velocidad con cartelería, reductores y controles, como los tótems que se instalaron en las rutas que atraviesan el Parque Nacional Iguazú. Construir pasafaunas: por debajo de la ruta (alcantarillas y túneles) o por encima (ecoductos con tierra y vegetación). Instalar pasos aéreos para animales que viven en los árboles: en el Parque Nacional Iguazú, simples sogas gruesas sobre los caminos son usadas a diario por monos caí. Y guiar a los animales hacia los pasos con alambrados o vegetación."]},"solucion":{}},{"slug":"animales-5.s2.p6","orden":6,"grupo":"animales-5.s2.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada solución con el animal que más beneficia.","izquierda":[{"id":"a1","texto":"Soga aérea sobre el camino"},{"id":"a2","texto":"Túnel bajo la ruta"},{"id":"a3","texto":"Ecoducto con vegetación"},{"id":"a4","texto":"Reductores de velocidad"}],"derecha":[{"id":"b1","texto":"Monos caí"},{"id":"b2","texto":"Mamíferos medianos que caminan por el suelo"},{"id":"b3","texto":"Grandes mamíferos que evitan espacios abiertos"},{"id":"b4","texto":"Todos los que cruzan la ruta"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada grupo de fauna necesita un tipo de paso distinto."}},{"slug":"animales-5.s2.p7","orden":7,"grupo":"animales-5.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas reducen los atropellamientos de fauna? Marcá todas.","opciones":[{"id":"o1","texto":"Controlar y reducir la velocidad en tramos de selva"},{"id":"o2","texto":"Construir pasafaunas por debajo o por encima de la ruta"},{"id":"o3","texto":"Guiar a los animales hacia los pasos"},{"id":"o4","texto":"Señalizar los sitios de cruce frecuente"},{"id":"o5","texto":"Ensanchar la ruta sin ningún paso de fauna"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La combinación de velocidad controlada y pasos seguros es la más efectiva."}},{"slug":"animales-5.s2.p8","orden":8,"grupo":"animales-5.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero, los datos","cuerpo":["Para saber dónde poner los pasos, primero se registran los atropellamientos: especie, lugar exacto y fecha. Con esos datos se identifican los puntos calientes, donde se concentran las muertes. En Misiones, estudios así identificaron trece sitios sensibles y cinco prioritarios en las rutas nacionales 12 y 101. Cualquier persona puede aportar registros, como viste con la ciencia ciudadana."]},"solucion":{}},{"slug":"animales-5.s2.p9","orden":9,"grupo":"animales-5.s2.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para reducir los atropellamientos en una ruta.","items":[{"id":"i1","texto":"Registrar cada atropellamiento con especie, lugar y fecha"},{"id":"i2","texto":"Identificar los puntos calientes"},{"id":"i3","texto":"Diseñar las soluciones para esos puntos"},{"id":"i4","texto":"Construir pasos y controlar la velocidad"},{"id":"i5","texto":"Seguir registrando para medir si funcionó"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los datos dicen dónde actuar y, después, si la solución funcionó."}},{"slug":"animales-5.s2.p10","orden":10,"grupo":"animales-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tramo se registraban 120 atropellamientos por año. Después de instalar reductores y pasafaunas, se registran 30. ¿En qué porcentaje bajaron?","unidad":"%","decimales":0,"contexto":"De 120 a 30 atropellamientos por año."},"solucion":{"valor":75,"tolerancia":1,"explicacion":"(120 − 30) ÷ 120 × 100 = 75 %. Datos de ejemplo: medir antes y después es la única forma de saber si una medida sirve."}},{"slug":"animales-5.s2.p10.v2","orden":10,"grupo":"animales-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tramo se registraban 80 atropellamientos por año. Después de instalar reductores y pasafaunas, se registran 36. ¿En qué porcentaje bajaron?","unidad":"%","decimales":0,"contexto":"De 80 a 36 atropellamientos por año."},"solucion":{"valor":55,"tolerancia":1,"explicacion":"(80 − 36) ÷ 80 × 100 = 55 %. Datos de ejemplo: medir antes y después es la única forma de saber si una medida sirve."}},{"slug":"animales-5.s2.p10.v3","orden":10,"grupo":"animales-5.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tramo se registraban 200 atropellamientos por año. Después de instalar reductores y pasafaunas, se registran 60. ¿En qué porcentaje bajaron?","unidad":"%","decimales":0,"contexto":"De 200 a 60 atropellamientos por año."},"solucion":{"valor":70,"tolerancia":1,"explicacion":"(200 − 60) ÷ 200 × 100 = 70 %. Datos de ejemplo: medir antes y después es la única forma de saber si una medida sirve."}},{"slug":"animales-5.s2.p11","orden":11,"grupo":"animales-5.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un cartel de \"cruce de fauna\" alcanza por sí solo para evitar los atropellamientos.","razones":[{"id":"r1","texto":"Porque sin control de velocidad y pasos, el cartel ayuda poco"},{"id":"r2","texto":"Porque los carteles aumentan los atropellamientos"},{"id":"r3","texto":"Porque los animales leen los carteles"}]},"solucion":{"valor":false,"explicacion":"Los carteles ayudan poco si nadie controla la velocidad y no hay pasos. Las medidas más efectivas combinan control de velocidad, pasafaunas y guías.","clave":["r1"]}},{"slug":"animales-5.s2.p12","orden":12,"grupo":"animales-5.s2.p12","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La medida actúa sobre el conductor o sobre el paso de los animales?","grupos":[{"id":"g1","nombre":"Sobre el conductor"},{"id":"g2","nombre":"Sobre el paso de los animales"}],"items":[{"id":"i1","texto":"Tótems de control de velocidad"},{"id":"i2","texto":"Túneles bajo la ruta"},{"id":"i3","texto":"Reductores de velocidad"},{"id":"i4","texto":"Ecoductos"},{"id":"i5","texto":"Campañas de concientización"},{"id":"i6","texto":"Sogas aéreas para monos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos estrategias se complementan: menos velocidad y más pasos seguros."}},{"slug":"animales-5.s2.p13","orden":13,"grupo":"animales-5.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe vial y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Registramos todos los atropellamientos con coordenadas."},{"id":"s2","texto":"Como el tránsito crece, subiremos el límite a 100 km/h en el tramo de selva."},{"id":"s3","texto":"Construiremos pasafaunas en los puntos calientes."},{"id":"s4","texto":"No mediremos los resultados porque las obras ya están hechas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una ruta amigable con la fauna se diseña con datos y se evalúa con datos.","por_opcion":{"s2":"Más velocidad significa más atropellamientos.","s4":"Sin medir, no se sabe si funcionaron."}}},{"slug":"animales-5.s2.p14","orden":14,"grupo":"animales-5.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La principal causa de atropellamientos es la {{0}}; un paso por encima de la ruta con tierra y vegetación es un {{1}}; y los lugares donde se concentran las muertes son los puntos {{2}}.","banco":[{"id":"w1","texto":"velocidad"},{"id":"w2","texto":"ecoducto"},{"id":"w3","texto":"calientes"},{"id":"w4","texto":"lluvia"},{"id":"w5","texto":"túnel"},{"id":"w6","texto":"fríos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para hacer rutas que no maten."}}]},{"slug":"animales-5.s3","orden":3,"tipo":"leccion","titulo_es":"Predadores y ganado","bajada_es":"Pumas, zorros y perros asilvestrados: por qué el control letal suele fallar y qué alternativas funcionan.","minutos":12,"pasos":[{"slug":"animales-5.s3.p1","orden":1,"grupo":"animales-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El conflicto","cuerpo":["En la Patagonia y otras regiones, el puma, el zorro colorado y los perros asilvestrados atacan ovejas y cabras, y esas pérdidas pueden ser muy duras para familias ganaderas. La respuesta tradicional fue matar a los predadores: con trampas, cebos envenenados o incentivos para cazarlos. Pero ese control letal tiene problemas: los venenos matan a muchas otras especies (lo viste con los cóndores), no siempre reduce las pérdidas y, al eliminar a un predador adulto, a veces su territorio lo ocupan jóvenes más inexpertos que atacan más al ganado."]},"solucion":{}},{"slug":"animales-5.s3.p2","orden":2,"grupo":"animales-5.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un cebo envenenado puede empeorar las cosas.","items":[{"id":"i1","texto":"Se pone un cebo envenenado para un zorro"},{"id":"i2","texto":"Lo comen zorros, pero también cóndores, águilas y perros"},{"id":"i3","texto":"Mueren especies que no atacaban al ganado"},{"id":"i4","texto":"Se pierden carroñeros y predadores que regulaban plagas"},{"id":"i5","texto":"El problema de fondo sigue igual"},{"id":"i6","texto":"El veneno solo afecta a los zorros"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El veneno no elige: mata en cadena y deja el problema sin resolver."}},{"slug":"animales-5.s3.p3","orden":3,"grupo":"animales-5.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Perros protectores","cuerpo":["Una alternativa que da muy buenos resultados son los perros protectores de ganado: razas seleccionadas durante siglos para vivir con las majadas y ahuyentar a los predadores, como el maremmano abruzzese y el montaña de los Pirineos. El INTA Bariloche trabaja con ellos desde 2013. Según el INTA, cuando se incorporan de forma apropiada, reducen hasta un 95 % las muertes de animales por depredación, sin matar fauna silvestre."],"destacado":{"valor":"hasta 95 %","texto":"menos muertes de ganado por depredación con perros protectores bien incorporados, según el INTA."}},"solucion":{}},{"slug":"animales-5.s3.p4","orden":4,"grupo":"animales-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia perdía 80 animales por año por depredación. Con perros protectores, las pérdidas bajan un 95 %. ¿Cuántos animales pierde ahora?","unidad":"animales","decimales":0,"contexto":"80 animales perdidos; reducción del 95 %."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"80 × 5 % = 4 animales por año. Una mejora enorme para la familia y sin matar fauna silvestre."}},{"slug":"animales-5.s3.p4.v2","orden":4,"grupo":"animales-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia perdía 60 animales por año por depredación. Con perros protectores, las pérdidas bajan un 90 %. ¿Cuántos animales pierde ahora?","unidad":"animales","decimales":0,"contexto":"60 animales perdidos; reducción del 90 %."},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"60 × 10 % = 6 animales por año. Una mejora enorme para la familia y sin matar fauna silvestre."}},{"slug":"animales-5.s3.p4.v3","orden":4,"grupo":"animales-5.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia perdía 120 animales por año por depredación. Con perros protectores, las pérdidas bajan un 80 %. ¿Cuántos animales pierde ahora?","unidad":"animales","decimales":0,"contexto":"120 animales perdidos; reducción del 80 %."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"120 × 20 % = 24 animales por año. Una mejora enorme para la familia y sin matar fauna silvestre."}},{"slug":"animales-5.s3.p5","orden":5,"grupo":"animales-5.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo funciona un perro protector","cuerpo":["El perro protector no es un perro pastor: no arrea, sino que vive con el ganado como si fuera parte de la majada. Para eso hace falta la impronta: criarlo desde cachorro junto a las ovejas o cabras, respetando un tiempo de familiarización en los primeros meses. Después se adapta al trabajo en el campo, con el compromiso de toda la familia. Si se cría mal, puede no proteger o incluso causar problemas."]},"solucion":{}},{"slug":"animales-5.s3.p6","orden":6,"grupo":"animales-5.s3.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para incorporar un perro protector.","items":[{"id":"i1","texto":"Elegir un cachorro de una raza protectora"},{"id":"i2","texto":"Criarlo desde pequeño junto al ganado (impronta)"},{"id":"i3","texto":"Respetar el tiempo de familiarización"},{"id":"i4","texto":"Adaptarlo de a poco al trabajo en el campo"},{"id":"i5","texto":"Acompañarlo hasta que madure"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La crianza correcta es la clave: un buen perro protector se forma, no se compra hecho."}},{"slug":"animales-5.s3.p7","orden":7,"grupo":"animales-5.s3.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un perro protector de ganado cumple la misma función que un perro pastor.","razones":[{"id":"r1","texto":"Porque el protector vive con la majada y la defiende, no la arrea"},{"id":"r2","texto":"Porque el perro protector caza a los pumas"},{"id":"r3","texto":"Porque el perro pastor vive solo en la ciudad"}]},"solucion":{"valor":false,"explicacion":"El perro pastor arrea el ganado siguiendo órdenes; el protector vive con la majada y la defiende de los predadores. Son razas y crianzas distintas.","clave":["r1"]}},{"slug":"animales-5.s3.p8","orden":8,"grupo":"animales-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Mantener un perro protector cuesta unos 400 dólares por año entre alimento y veterinario. Si evita la muerte de 30 ovejas de 120 dólares cada una, ¿cuánto gana la familia por año, ya descontado el costo del perro?","unidad":"dólares","decimales":0,"contexto":"Perro: 400 dólares por año; 30 ovejas salvadas a 120 dólares."},"solucion":{"valor":3200,"tolerancia":64,"explicacion":"30 × 120 = 3.600 dólares salvados; − 400 = 3.200 dólares. Valores de ejemplo: la prevención suele pagarse sola."}},{"slug":"animales-5.s3.p8.v2","orden":8,"grupo":"animales-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Mantener un perro protector cuesta unos 500 dólares por año entre alimento y veterinario. Si evita la muerte de 20 ovejas de 150 dólares cada una, ¿cuánto gana la familia por año, ya descontado el costo del perro?","unidad":"dólares","decimales":0,"contexto":"Perro: 500 dólares por año; 20 ovejas salvadas a 150 dólares."},"solucion":{"valor":2500,"tolerancia":50,"explicacion":"20 × 150 = 3.000 dólares salvados; − 500 = 2.500 dólares. Valores de ejemplo: la prevención suele pagarse sola."}},{"slug":"animales-5.s3.p8.v3","orden":8,"grupo":"animales-5.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Mantener un perro protector cuesta unos 300 dólares por año entre alimento y veterinario. Si evita la muerte de 15 ovejas de 100 dólares cada una, ¿cuánto gana la familia por año, ya descontado el costo del perro?","unidad":"dólares","decimales":0,"contexto":"Perro: 300 dólares por año; 15 ovejas salvadas a 100 dólares."},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"15 × 100 = 1.500 dólares salvados; − 300 = 1.200 dólares. Valores de ejemplo: la prevención suele pagarse sola."}},{"slug":"animales-5.s3.p9","orden":9,"grupo":"animales-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Otras herramientas","cuerpo":["Otras medidas no letales incluyen encerrar el ganado de noche en corrales seguros, concentrar las pariciones en épocas y lugares más vigilados, usar luces o sonidos que ahuyentan, y cercos eléctricos. Muchas veces la mejor estrategia combina varias. También ayudan los seguros o fondos que compensan pérdidas, para que una mala temporada no empuje a las familias a usar venenos."]},"solucion":{}},{"slug":"animales-5.s3.p10","orden":10,"grupo":"animales-5.s3.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un método letal o no letal?","grupos":[{"id":"g1","nombre":"No letal"},{"id":"g2","nombre":"Letal"}],"items":[{"id":"i1","texto":"Perros protectores"},{"id":"i2","texto":"Cebos envenenados"},{"id":"i3","texto":"Corrales nocturnos"},{"id":"i4","texto":"Trampas de lazo"},{"id":"i5","texto":"Luces que ahuyentan"},{"id":"i6","texto":"Recompensas por matar pumas"},{"id":"i7","texto":"Cercos eléctricos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"Los métodos no letales protegen el ganado sin dañar a la fauna silvestre."}},{"slug":"animales-5.s3.p11","orden":11,"grupo":"animales-5.s3.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué matar a un puma adulto a veces aumenta los ataques al ganado?","opciones":[{"id":"o1","texto":"Su territorio puede ocuparlo un joven más inexperto"},{"id":"o2","texto":"Porque los pumas muertos atraen más ovejas"},{"id":"o3","texto":"Porque así los pumas se vuelven vegetarianos"},{"id":"o4","texto":"Porque los zorros dejan de cazar"}]},"solucion":{"clave":["o1"],"explicacion":"Los predadores jóvenes y dispersantes suelen ser los que más atacan presas fáciles como el ganado.","por_opcion":{"o3":"No cambia su dieta; cambia quién ocupa el territorio."}}},{"slug":"animales-5.s3.p12","orden":12,"grupo":"animales-5.s3.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los perros asilvestrados pueden ser un problema tan grave como los predadores silvestres para el ganado y la fauna.","razones":[{"id":"r1","texto":"Porque atacan ganado y fauna silvestre"},{"id":"r2","texto":"Porque los perros nunca atacan ganado"},{"id":"r3","texto":"Porque los perros asilvestrados son nativos"}]},"solucion":{"valor":true,"explicacion":"En muchas zonas atacan ganado y fauna silvestre. La tenencia responsable de perros es parte de la solución, como viste en la unidad de fauna urbana.","clave":["r1"]}},{"slug":"animales-5.s3.p13","orden":13,"grupo":"animales-5.s3.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué combinación de medidas conviene para una familia con pérdidas por pumas? Marcá todo.","opciones":[{"id":"o1","texto":"Perros protectores bien criados"},{"id":"o2","texto":"Corrales nocturnos"},{"id":"o3","texto":"Pariciones en potreros vigilados"},{"id":"o4","texto":"Un fondo que compense pérdidas extraordinarias"},{"id":"o5","texto":"Cebos envenenados en todo el campo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Varias medidas no letales juntas protegen mejor que una sola, y sin daños colaterales."}},{"slug":"animales-5.s3.p14","orden":14,"grupo":"animales-5.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de un vecino y marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Encerrá las ovejas de noche en un corral seguro."},{"id":"s2","texto":"Poné veneno en una oveja muerta para matar al zorro."},{"id":"s3","texto":"Probá con un perro protector criado junto a las ovejas."},{"id":"s4","texto":"Cualquier perro sirve como protector, aunque no esté criado con el ganado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las mejores soluciones protegen a la familia y a la fauna a la vez.","por_opcion":{"s2":"Mata cóndores, águilas y otras especies; además es ilegal.","s4":"Necesita raza adecuada e impronta con el ganado."}}},{"slug":"animales-5.s3.p15","orden":15,"grupo":"animales-5.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Criar un perro desde cachorro con el ganado se llama {{0}}; según el INTA, los perros protectores reducen hasta un {{1}} % las muertes por depredación; y los cebos envenenados matan también a los {{2}}.","banco":[{"id":"w1","texto":"impronta"},{"id":"w2","texto":"95"},{"id":"w3","texto":"cóndores"},{"id":"w4","texto":"adiestramiento"},{"id":"w5","texto":"9"},{"id":"w6","texto":"caballos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para reducir la depredación sin matar fauna."}}]},{"slug":"animales-5.s4","orden":4,"tipo":"leccion","titulo_es":"Herbívoros: competir o aprovechar","bajada_es":"Guanacos y ovejas, vicuñas y chaku: cuando la fauna compite con la producción o se vuelve un recurso sostenible.","minutos":11,"pasos":[{"slug":"animales-5.s4.p1","orden":1,"grupo":"animales-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Guanacos y ovejas","cuerpo":["En la Patagonia, muchos productores ven al guanaco como un competidor de las ovejas por el pasto. La discusión científica sobre cuánto compiten es compleja: depende de la carga total de animales, del estado de los pastizales y del clima. Lo que sí está claro es que el sobrepastoreo, sumando ovejas y guanacos, degrada los pastizales y acelera la desertificación. Por eso la clave es manejar la carga total del campo, y no solo culpar a una especie."]},"solucion":{}},{"slug":"animales-5.s4.p2","orden":2,"grupo":"animales-5.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el sobrepastoreo degrada un campo patagónico.","items":[{"id":"i1","texto":"Hay más animales de los que el pastizal puede sostener"},{"id":"i2","texto":"Los pastos se comen antes de recuperarse"},{"id":"i3","texto":"El suelo queda desnudo"},{"id":"i4","texto":"El viento y el agua se llevan el suelo"},{"id":"i5","texto":"El campo produce menos pasto para todos"},{"id":"i6","texto":"Más animales hacen crecer más pasto"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo viste con el suelo: el sobrepastoreo es una de las causas de la desertificación patagónica."}},{"slug":"animales-5.s4.p3","orden":3,"grupo":"animales-5.s4.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo puede sostener el equivalente a 1.000 ovejas. Tiene 900 ovejas y 300 guanacos, y cada guanaco come como una oveja y media. ¿Cuántos \"equivalentes oveja\" supera su capacidad?","unidad":"equivalentes oveja","decimales":0,"contexto":"Capacidad 1000; 900 ovejas; 300 guanacos a 1,5 cada uno."},"solucion":{"valor":350,"tolerancia":7,"explicacion":"900 + 300 × 1,5 = 1.350; − 1.000 = 350 de exceso. Valores de ejemplo: la carga total, no una especie sola, es lo que degrada el campo."}},{"slug":"animales-5.s4.p3.v2","orden":3,"grupo":"animales-5.s4.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo puede sostener el equivalente a 2.000 ovejas. Tiene 1.500 ovejas y 600 guanacos, y cada guanaco come como una oveja y media. ¿Cuántos \"equivalentes oveja\" supera su capacidad?","unidad":"equivalentes oveja","decimales":0,"contexto":"Capacidad 2000; 1500 ovejas; 600 guanacos a 1,5 cada uno."},"solucion":{"valor":400,"tolerancia":8,"explicacion":"1.500 + 600 × 1,5 = 2.400; − 2.000 = 400 de exceso. Valores de ejemplo: la carga total, no una especie sola, es lo que degrada el campo."}},{"slug":"animales-5.s4.p3.v3","orden":3,"grupo":"animales-5.s4.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un campo puede sostener el equivalente a 500 ovejas. Tiene 350 ovejas y 200 guanacos, y cada guanaco come como una oveja y media. ¿Cuántos \"equivalentes oveja\" supera su capacidad?","unidad":"equivalentes oveja","decimales":0,"contexto":"Capacidad 500; 350 ovejas; 200 guanacos a 1,5 cada uno."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"350 + 200 × 1,5 = 650; − 500 = 150 de exceso. Valores de ejemplo: la carga total, no una especie sola, es lo que degrada el campo."}},{"slug":"animales-5.s4.p4","orden":4,"grupo":"animales-5.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un productor dice que su campo está degradado \"por culpa de los guanacos\". ¿Qué habría que mirar primero?","opciones":[{"id":"o1","texto":"La carga total de animales frente al pasto disponible"},{"id":"o2","texto":"Solo cuántos guanacos cruzaron el alambrado este año"},{"id":"o3","texto":"El color del pelaje de los guanacos de la zona"},{"id":"o4","texto":"La cantidad de lluvia de un único día de verano"}]},"solucion":{"clave":["o1"],"explicacion":"Ovejas, guanacos, clima y estado del pastizal se evalúan juntos: la carga total es lo que degrada.","por_opcion":{"o3":"No tiene relación con la degradación del pastizal."}}},{"slug":"animales-5.s4.p5","orden":5,"grupo":"animales-5.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Alambrados que atrapan","cuerpo":["Los alambrados también afectan a los herbívoros silvestres. Los guanacos saltan alambrados, pero a veces quedan enganchados de las patas y mueren. Hay diseños de alambrados más amigables, con el hilo superior más bajo o sin púas, y lugares para cruzar, que reducen esas muertes sin perder el manejo del ganado."]},"solucion":{}},{"slug":"animales-5.s4.p6","orden":6,"grupo":"animales-5.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cómo puede un productor reducir las muertes de guanacos en sus alambrados?","opciones":[{"id":"o1","texto":"Con diseños más bajos y lisos arriba, y pasos"},{"id":"o2","texto":"Poniendo más hilos de púa en la parte de arriba"},{"id":"o3","texto":"Sacando todos los alambrados del campo"},{"id":"o4","texto":"Electrificando todos los hilos a gran voltaje"}]},"solucion":{"clave":["o1"],"explicacion":"Pequeños cambios de diseño pueden salvar muchos animales sin afectar la producción.","por_opcion":{"o3":"Puede no ser posible para el manejo del ganado; hay diseños intermedios."}}},{"slug":"animales-5.s4.p7","orden":7,"grupo":"animales-5.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La vicuña: de casi extinta a recurso sostenible","cuerpo":["La vicuña, pariente silvestre del guanaco que vive en la Puna, estuvo al borde de la extinción por la caza para obtener su fibra, una de las más finas y valiosas del mundo. Con protección y controles del comercio internacional, sus poblaciones se recuperaron. Hoy, en Jujuy y Catamarca, comunidades y equipos técnicos practican el chaku: una técnica de origen prehispánico en la que se captura a las vicuñas silvestres, se las esquila y se las libera. La fibra se vende con autorización de la CITES, y la vicuña vale más viva que muerta."]},"solucion":{}},{"slug":"animales-5.s4.p8","orden":8,"grupo":"animales-5.s4.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del chaku.","items":[{"id":"i1","texto":"Arrear a las vicuñas silvestres hacia un corral de captura"},{"id":"i2","texto":"Revisar a cada animal con cuidado veterinario"},{"id":"i3","texto":"Esquilar su fibra"},{"id":"i4","texto":"Liberarlas en su ambiente"},{"id":"i5","texto":"Vender la fibra con autorización y trazabilidad"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un uso sostenible que no mata a ningún animal y da ingresos a las comunidades."}},{"slug":"animales-5.s4.p9","orden":9,"grupo":"animales-5.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el chaku ayuda a conservar la vicuña.","items":[{"id":"i1","texto":"Las comunidades obtienen ingresos por la fibra"},{"id":"i2","texto":"Las vicuñas vivas pasan a ser valiosas para ellas"},{"id":"i3","texto":"Las comunidades cuidan a las poblaciones y denuncian la caza"},{"id":"i4","texto":"Disminuye la caza furtiva"},{"id":"i5","texto":"Las poblaciones se mantienen sanas"},{"id":"i6","texto":"Matar vicuñas da más fibra que esquilarlas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cuando la fauna viva genera beneficios locales, su conservación gana aliados."}},{"slug":"animales-5.s4.p10","orden":10,"grupo":"animales-5.s4.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En el chaku se mata a las vicuñas para obtener su fibra.","razones":[{"id":"r1","texto":"Porque se las esquila y se las libera"},{"id":"r2","texto":"Porque la fibra solo se obtiene de animales muertos"},{"id":"r3","texto":"Porque la vicuña es un animal doméstico"}]},"solucion":{"valor":false,"explicacion":"Se las captura, se las esquila y se las libera. Es justamente lo que lo hace sostenible: la misma vicuña puede volver a esquilarse en otro chaku.","clave":["r1"]}},{"slug":"animales-5.s4.p11","orden":11,"grupo":"animales-5.s4.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herbívoro con su situación.","izquierda":[{"id":"a1","texto":"Vicuña"},{"id":"a2","texto":"Guanaco"},{"id":"a3","texto":"Oveja"},{"id":"a4","texto":"Liebre europea"}],"derecha":[{"id":"b1","texto":"Se recuperó y hoy se esquila en chakus"},{"id":"b2","texto":"Debate sobre su competencia con el ganado"},{"id":"b3","texto":"Ganado cuyo exceso degrada pastizales"},{"id":"b4","texto":"Herbívoro exótico que se expandió"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Nativos, domésticos y exóticos: cada herbívoro plantea desafíos distintos."}},{"slug":"animales-5.s4.p12","orden":12,"grupo":"animales-5.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué condiciones hacen sostenible el uso de una especie silvestre? Marcá todas.","opciones":[{"id":"o1","texto":"Que no se reduzca la población"},{"id":"o2","texto":"Que haya control y trazabilidad del producto"},{"id":"o3","texto":"Que los beneficios lleguen a las comunidades locales"},{"id":"o4","texto":"Que se cuide el bienestar de los animales"},{"id":"o5","texto":"Que se extraiga todo lo posible cada año"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El uso sostenible convierte a la fauna viva en un recurso que conviene cuidar."}},{"slug":"animales-5.s4.p13","orden":13,"grupo":"animales-5.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en un foro de productores y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La vicuña se recuperó gracias a la protección y al control del comercio."},{"id":"s2","texto":"El único problema de los pastizales patagónicos son los guanacos."},{"id":"s3","texto":"En el chaku, las vicuñas se liberan después de la esquila."},{"id":"s4","texto":"Los alambrados no afectan a la fauna silvestre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los conflictos con herbívoros se resuelven mejor mirando todo el sistema.","por_opcion":{"s2":"Importa la carga total de animales, incluidas las ovejas.","s4":"Los guanacos pueden quedar enganchados y morir."}}},{"slug":"animales-5.s4.p14","orden":14,"grupo":"animales-5.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La captura, esquila y liberación de vicuñas se llama {{0}}; el exceso de animales que degrada un pastizal es el {{1}}; y la fibra de vicuña se vende con autorización de la {{2}}.","banco":[{"id":"w1","texto":"chaku"},{"id":"w2","texto":"sobrepastoreo"},{"id":"w3","texto":"CITES"},{"id":"w4","texto":"rodeo"},{"id":"w5","texto":"reciclaje"},{"id":"w6","texto":"FIFA"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la relación entre herbívoros y producción."}}]},{"slug":"animales-5.s5","orden":5,"tipo":"leccion","titulo_es":"Acuerdos para coexistir","bajada_es":"Datos, compensaciones, participación y beneficios: cómo pasar del conflicto a la convivencia.","minutos":11,"pasos":[{"slug":"animales-5.s5.p1","orden":1,"grupo":"animales-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Coexistir no es resignarse","cuerpo":["La coexistencia no significa que los productores tengan que aceptar pérdidas sin ayuda, ni que la fauna tenga que desaparecer. Significa buscar formas de producir y conservar a la vez: con herramientas no letales, compensaciones justas, reglas claras y beneficios compartidos. Lo viste con los conflictos ambientales: los acuerdos duraderos se construyen con todas las partes."]},"solucion":{}},{"slug":"animales-5.s5.p2","orden":2,"grupo":"animales-5.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué elementos tiene un buen acuerdo de coexistencia con la fauna? Marcá todos.","opciones":[{"id":"o1","texto":"Herramientas no letales para proteger el ganado"},{"id":"o2","texto":"Compensaciones justas por pérdidas"},{"id":"o3","texto":"Participación de productores, técnicos y comunidades"},{"id":"o4","texto":"Monitoreo de pérdidas y de fauna"},{"id":"o5","texto":"Eliminar a todos los predadores de la región"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La coexistencia combina protección de la producción y de la fauna."}},{"slug":"animales-5.s5.p3","orden":3,"grupo":"animales-5.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Compensaciones","cuerpo":["Algunos programas compensan a los productores por las pérdidas causadas por fauna protegida, o pagan por la presencia de fauna en sus campos. Para que funcionen, hay que verificar las pérdidas de forma rápida y justa, y combinarlas con medidas preventivas: si solo se paga por los animales muertos, no hay incentivo para prevenir. Otra opción son los pagos por resultados: el productor recibe más si en su campo se registran pumas o yaguaretés y sus pérdidas son bajas."]},"solucion":{}},{"slug":"animales-5.s5.p4","orden":4,"grupo":"animales-5.s5.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene que una compensación por depredación esté ligada a medidas de prevención?","opciones":[{"id":"o1","texto":"Para que no se pierda el incentivo a prevenir"},{"id":"o2","texto":"Para que el productor gane más si pierde más"},{"id":"o3","texto":"Para que las compensaciones sean imposibles de cobrar"},{"id":"o4","texto":"Para que se usen más venenos"}]},"solucion":{"clave":["o1"],"explicacion":"Pagar solo por lo perdido puede desalentar la prevención; combinarlos da mejores resultados.","por_opcion":{"o3":"No se trata de dificultar, sino de combinar prevención y ayuda."}}},{"slug":"animales-5.s5.p5","orden":5,"grupo":"animales-5.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un esquema de pago por resultados, ¿qué hace que un productor cobre más?","opciones":[{"id":"o1","texto":"Registrar pumas en su campo y tener pérdidas bajas"},{"id":"o2","texto":"Perder muchas ovejas por los ataques de pumas"},{"id":"o3","texto":"Demostrar que eliminó a los pumas de su campo"},{"id":"o4","texto":"Cerrar su campo al paso de todos los animales"}]},"solucion":{"clave":["o1"],"explicacion":"Se paga por lograr lo que se busca: fauna presente y ganado protegido a la vez.","por_opcion":{"o4":"Aislar el campo no es el objetivo: se premia convivir."}}},{"slug":"animales-5.s5.p6","orden":6,"grupo":"animales-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un fondo compensa el 50 % del valor de los animales perdidos por depredación, si el productor usa medidas preventivas. Si perdió 20 ovejas de 150 dólares cada una, ¿cuánto recibe?","unidad":"dólares","decimales":0,"contexto":"20 ovejas de 150 dólares; compensación del 50 %."},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"20 × 150 × 50 % = 1.500 dólares. Alivia una mala temporada y sostiene la prevención. Valores de ejemplo."}},{"slug":"animales-5.s5.p6.v2","orden":6,"grupo":"animales-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un fondo compensa el 60 % del valor de los animales perdidos por depredación, si el productor usa medidas preventivas. Si perdió 40 ovejas de 120 dólares cada una, ¿cuánto recibe?","unidad":"dólares","decimales":0,"contexto":"40 ovejas de 120 dólares; compensación del 60 %."},"solucion":{"valor":2880,"tolerancia":57.6,"explicacion":"40 × 120 × 60 % = 2.880 dólares. Alivia una mala temporada y sostiene la prevención. Valores de ejemplo."}},{"slug":"animales-5.s5.p6.v3","orden":6,"grupo":"animales-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un fondo compensa el 70 % del valor de los animales perdidos por depredación, si el productor usa medidas preventivas. Si perdió 10 ovejas de 200 dólares cada una, ¿cuánto recibe?","unidad":"dólares","decimales":0,"contexto":"10 ovejas de 200 dólares; compensación del 70 %."},"solucion":{"valor":1400,"tolerancia":28,"explicacion":"10 × 200 × 70 % = 1.400 dólares. Alivia una mala temporada y sostiene la prevención. Valores de ejemplo."}},{"slug":"animales-5.s5.p7","orden":7,"grupo":"animales-5.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Beneficios de la fauna viva","cuerpo":["La fauna también puede generar ingresos: el turismo de avistaje de pumas, cóndores, yaguaretés o guanacos crece en varias regiones, y los visitantes pagan por ver animales en libertad. Cuando esos ingresos llegan a quienes viven y producen en el lugar, la fauna pasa de ser un problema a ser un valor. Lo viste con la ballena franca en Península Valdés y con la vicuña."]},"solucion":{}},{"slug":"animales-5.s5.p8","orden":8,"grupo":"animales-5.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el turismo de fauna puede cambiar la mirada de un productor.","items":[{"id":"i1","texto":"Llegan visitantes a ver pumas en la zona"},{"id":"i2","texto":"El productor ofrece alojamiento o guías en su campo"},{"id":"i3","texto":"Obtiene ingresos gracias a la presencia de pumas"},{"id":"i4","texto":"Le conviene que los pumas sigan en su campo"},{"id":"i5","texto":"Adopta medidas no letales para proteger su ganado"},{"id":"i6","texto":"El turismo obliga a eliminar a los pumas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La fauna viva que genera ingresos locales gana defensores."}},{"slug":"animales-5.s5.p9","orden":9,"grupo":"animales-5.s5.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida previene el conflicto o repara el daño?","grupos":[{"id":"g1","nombre":"Previene"},{"id":"g2","nombre":"Repara"}],"items":[{"id":"i1","texto":"Perros protectores"},{"id":"i2","texto":"Compensación por ovejas perdidas"},{"id":"i3","texto":"Corrales nocturnos"},{"id":"i4","texto":"Seguro ganadero"},{"id":"i5","texto":"Pasafaunas en rutas"},{"id":"i6","texto":"Rehabilitación de fauna herida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Prevenir y reparar se complementan; la prevención suele ser más barata."}},{"slug":"animales-5.s5.p10","orden":10,"grupo":"animales-5.s5.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los acuerdos de coexistencia funcionan mejor si los diseñan solo técnicos, sin productores.","razones":[{"id":"r1","texto":"Porque los productores conocen el terreno y aplican las medidas"},{"id":"r2","texto":"Porque los productores no tienen conocimientos"},{"id":"r3","texto":"Porque los técnicos nunca participan"}]},"solucion":{"valor":false,"explicacion":"Los productores conocen el terreno y son quienes aplican las medidas. Sin su participación, los acuerdos suelen fallar.","clave":["r1"]}},{"slug":"animales-5.s5.p11","orden":11,"grupo":"animales-5.s5.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas estrategias frente a la depredación, de la más recomendable a la menos.","items":[{"id":"i1","texto":"Perros protectores y corrales, con apoyo técnico"},{"id":"i2","texto":"Compensación ligada a prevención"},{"id":"i3","texto":"Solo compensar sin prevenir"},{"id":"i4","texto":"Cebos envenenados"}],"extremos":["Más recomendable","Menos recomendable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Prevenir con métodos no letales, apoyar a las familias y nunca envenenar.","valores":{"i1":"la más recomendable","i2":"muy útil","i3":"incompleta","i4":"la peor"}}},{"slug":"animales-5.s5.p12","orden":12,"grupo":"animales-5.s5.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una herramienta de coexistencia.","izquierda":[{"id":"a1","texto":"Pumas que atacan majadas"},{"id":"a2","texto":"Fauna atropellada en rutas"},{"id":"a3","texto":"Guanacos enganchados en alambrados"},{"id":"a4","texto":"Pérdidas que empujan a usar veneno"}],"derecha":[{"id":"b1","texto":"Perros protectores"},{"id":"b2","texto":"Pasafaunas y control de velocidad"},{"id":"b3","texto":"Alambrados de diseño amigable"},{"id":"b4","texto":"Fondos de compensación"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada conflicto tiene herramientas concretas."}},{"slug":"animales-5.s5.p13","orden":13,"grupo":"animales-5.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta provincial y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Apoyaremos la cría de perros protectores con el INTA."},{"id":"s2","texto":"Pagaremos una recompensa por cada puma muerto."},{"id":"s3","texto":"Crearemos un fondo de compensación ligado a medidas preventivas."},{"id":"s4","texto":"Diseñaremos el programa sin consultar a los productores."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen programa de coexistencia protege a las familias y a la fauna.","por_opcion":{"s2":"Incentiva el control letal, que suele fallar y afecta a otras especies.","s4":"La participación es clave para que funcione."}}},{"slug":"animales-5.s5.p14","orden":14,"grupo":"animales-5.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Convivir con la fauna protegiendo la producción es la {{0}}; pagar por las pérdidas causadas por fauna es una {{1}}; y el turismo de fauna puede hacer que la fauna viva genere {{2}}.","banco":[{"id":"w1","texto":"coexistencia"},{"id":"w2","texto":"compensación"},{"id":"w3","texto":"ingresos"},{"id":"w4","texto":"resignación"},{"id":"w5","texto":"multa"},{"id":"w6","texto":"deudas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pasar del conflicto a la convivencia."}}]},{"slug":"animales-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: convivir con la fauna","bajada_es":"Corredores, rutas, predadores, herbívoros y acuerdos de coexistencia, mezclados.","minutos":8,"pasos":[{"slug":"animales-5.s6.p1","orden":1,"grupo":"animales-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Convivir con la fauna en el paisaje». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el valle de las ovejas y los pumas","bajada_es":"En un valle de la Norpatagonia, familias ganaderas pierden ovejas por pumas y zorros, y alguien propone usar veneno. Armá un plan de coexistencia.","minutos":10,"pasos":[{"slug":"animales-5.s7.p1","orden":1,"grupo":"animales-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["En el valle viven 12 familias con 300 ovejas y cabras cada una. Entre todas pierden unos 400 animales por año por depredación, sobre todo de noche y en la época de pariciones. Una ruta cruza el valle y allí se atropellan zorros y guanacos. Un grupo propone poner cebos envenenados. El INTA ofrece perros protectores y asesoramiento, y el municipio puede crear un pequeño fondo de compensación."]},"solucion":{}},{"slug":"animales-5.s7.p2","orden":2,"grupo":"animales-5.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de todas las ovejas y cabras del valle se pierde por año? Redondeá a un decimal.","unidad":"%","decimales":1,"contexto":"12 familias con 300 animales cada una; 400 perdidos."},"solucion":{"valor":11.1,"tolerancia":0.1,"explicacion":"12 × 300 = 3.600 animales; 400 ÷ 3.600 × 100 ≈ 11,1 %. Una pérdida muy alta para las familias."}},{"slug":"animales-5.s7.p3","orden":3,"grupo":"animales-5.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si con perros protectores y corrales las pérdidas bajan un 80 %, ¿cuántos animales se perderían por año?","unidad":"animales","decimales":0,"contexto":"400 animales perdidos; reducción del 80 %."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"400 × 20 % = 80 animales por año: 320 animales salvados, sin matar fauna silvestre."}},{"slug":"animales-5.s7.p4","orden":4,"grupo":"animales-5.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué no conviene la propuesta de los cebos envenenados?","opciones":[{"id":"o1","texto":"Matan otras especies, son ilegales y no resuelven el fondo"},{"id":"o2","texto":"Porque los venenos son muy caros para las familias"},{"id":"o3","texto":"Porque los zorros no comen carne"},{"id":"o4","texto":"Porque los pumas son inmunes al veneno"}]},"solucion":{"clave":["o1"],"explicacion":"El veneno mata cóndores, águilas y perros, contamina y deja el problema sin resolver.","por_opcion":{"o3":"Sí comen carne; el problema es que el veneno mata a muchas especies."}}},{"slug":"animales-5.s7.p5","orden":5,"grupo":"animales-5.s7.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el plan de coexistencia.","items":[{"id":"i1","texto":"Reunir a las 12 familias con el INTA y el municipio"},{"id":"i2","texto":"Registrar dónde y cuándo ocurren las pérdidas"},{"id":"i3","texto":"Incorporar perros protectores y corrales nocturnos"},{"id":"i4","texto":"Crear el fondo de compensación ligado a prevención"},{"id":"i5","texto":"Medir las pérdidas cada año y ajustar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Participación, datos, prevención, apoyo económico y evaluación."}},{"slug":"animales-5.s7.p6","orden":6,"grupo":"animales-5.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué más puede incluir el plan para la fauna del valle? Marcá todo.","opciones":[{"id":"o1","texto":"Reductores de velocidad y pasos de fauna en la ruta"},{"id":"o2","texto":"Alambrados amigables para los guanacos"},{"id":"o3","texto":"Control de perros sueltos y asilvestrados"},{"id":"o4","texto":"Recompensas por cada zorro muerto"},{"id":"o5","texto":"Quemar los pastizales para ahuyentar a los pumas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un plan de coexistencia mira todo el paisaje, no solo el corral."}},{"slug":"animales-5.s7.p7","orden":7,"grupo":"animales-5.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con perros protectores y corrales, ya no hace falta ningún apoyo económico a las familias.","razones":[{"id":"r1","texto":"Porque una mala temporada puede ser grave y el fondo da estabilidad"},{"id":"r2","texto":"Porque los perros eliminan todas las pérdidas"},{"id":"r3","texto":"Porque las familias no tienen gastos"}]},"solucion":{"valor":false,"explicacion":"Las medidas reducen mucho las pérdidas, pero una mala temporada puede ser grave. Un fondo ligado a la prevención da estabilidad y evita la tentación del veneno.","clave":["r1"]}},{"slug":"animales-5.s7.p8","orden":8,"grupo":"animales-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el acuerdo. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Las familias recibirán perros protectores y asesoramiento del INTA."},{"id":"s2","texto":"Se permitirá usar cebos envenenados como último recurso."},{"id":"s3","texto":"Se registrarán las pérdidas cada temporada."},{"id":"s4","texto":"El fondo pagará todas las pérdidas aunque no se use ninguna prevención."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un acuerdo sólido protege a las familias, a la fauna y a su propia continuidad.","por_opcion":{"s2":"Son ilegales y matan muchas especies: no deben ser una opción.","s4":"Debe estar ligado a medidas preventivas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"animales-6","rama":"animales","orden":6,"nivel":3,"titulo_es":"Una sola salud","bajada_es":"Hantavirus, gripe aviar, dengue y bacterias resistentes: por qué la salud de las personas depende de la de los animales y los ecosistemas.","objetivos_es":["Explicar el enfoque Una sola salud y qué es una zoonosis","Relacionar el desmonte y el tráfico de fauna con la aparición de enfermedades nuevas","Analizar brotes recientes en Argentina con datos y medidas de control","Explicar cómo surge la resistencia a los antimicrobianos y cómo frenarla","Aplicar hábitos de prevención frente a zoonosis y enfermedades ligadas al ambiente"],"repasa":["animales-5","animales-4","animales-2","agua-5"],"requiere_tronco":3,"fuentes":["omsa-una-salud","oms-una-salud","ipbes-pandemias","oms-resistencia","van-boeckel-2019","ue-promotores-2006","nejm-andes-2020","uhart-2024-elefantes","msal-hantavirus","msal-hidatidosis","msal-leptospirosis","msal-rabia","msal-dengue-2024","msal-suh-2026","ley-22421-fauna"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"animales-6.s1","orden":1,"tipo":"leccion","titulo_es":"Una sola salud","bajada_es":"Personas, animales y ambiente: por qué la salud de cada uno depende de la de los otros.","minutos":11,"pasos":[{"slug":"animales-6.s1.p1","orden":1,"grupo":"animales-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres saludes conectadas","cuerpo":["Durante mucho tiempo, la salud humana, la salud animal y el cuidado del ambiente se trabajaron por separado: médicos por un lado, veterinarios por otro y ecólogos por otro. Pero muchas enfermedades cruzan esas fronteras. Por eso surgió el enfoque Una sola salud, que la Organización Mundial de Sanidad Animal (OMSA) define como un enfoque integrado y unificador que busca equilibrar y optimizar de forma sostenible la salud de las personas, los animales y los ecosistemas.","Desde 2022, cuatro organismos internacionales lo impulsan juntos: la OMS (salud humana), la OMSA (sanidad animal), la FAO (alimentación y agricultura) y el PNUMA (ambiente)."]},"solucion":{}},{"slug":"animales-6.s1.p2","orden":2,"grupo":"animales-6.s1.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un problema ambiental puede terminar en un problema de salud humana.","items":[{"id":"i1","texto":"Una inundación cubre barrios y campos"},{"id":"i2","texto":"El agua arrastra orina de roedores y otros animales"},{"id":"i3","texto":"La bacteria de la leptospirosis sobrevive en el agua y el barro"},{"id":"i4","texto":"Vecinos limpian sin botas ni guantes"},{"id":"i5","texto":"Aparecen casos de leptospirosis"},{"id":"i6","texto":"La inundación elimina todas las bacterias del barrio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ambiente, animales y personas en una sola cadena: por eso se habla de una sola salud."}},{"slug":"animales-6.s1.p3","orden":3,"grupo":"animales-6.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Zoonosis","cuerpo":["Una zoonosis es una enfermedad que se transmite entre animales y personas. Según la OMSA, el 60 % de los agentes que causan enfermedades humanas proceden de animales domésticos o silvestres, y el 75 % de las enfermedades infecciosas emergentes tienen origen animal. Algunas se contagian por mordeduras (rabia); otras por alimentos (triquinosis, síndrome urémico hemolítico); por el agua o el barro (leptospirosis); o por el aire con polvo contaminado con excretas de roedores (hantavirus).","Otras enfermedades, como el dengue, no son zoonosis en las ciudades, pero también dependen del ambiente: las transmite un mosquito que se cría en agua acumulada."],"destacado":{"valor":"75 %","texto":"de las enfermedades infecciosas emergentes en personas tienen origen animal, según la OMSA."}},"solucion":{}},{"slug":"animales-6.s1.p4","orden":4,"grupo":"animales-6.s1.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada enfermedad con su forma principal de contagio.","izquierda":[{"id":"a1","texto":"Rabia"},{"id":"a2","texto":"Hantavirus"},{"id":"a3","texto":"Leptospirosis"},{"id":"a4","texto":"Hidatidosis"},{"id":"a5","texto":"Triquinosis"}],"derecha":[{"id":"b1","texto":"Mordedura o saliva de un animal infectado"},{"id":"b2","texto":"Aire con polvo de excretas de roedores"},{"id":"b3","texto":"Agua o barro con orina de animales infectados"},{"id":"b4","texto":"Huevos del parásito en heces de perros"},{"id":"b5","texto":"Carne de cerdo o jabalí sin control sanitario"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada zoonosis tiene su camino de contagio, y conocerlo es la base para prevenirla."}},{"slug":"animales-6.s1.p5","orden":5,"grupo":"animales-6.s1.p5","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las enfermedades infecciosas emergentes en personas tienen origen animal.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Según la OMSA, el 75 %: tres de cada cuatro enfermedades nuevas vienen de animales domésticos o silvestres."}},{"slug":"animales-6.s1.p6","orden":6,"grupo":"animales-6.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Todas las enfermedades que compartimos con los animales vienen de la fauna silvestre.","razones":[{"id":"r1","texto":"Porque muchas vienen de animales domésticos y de producción"},{"id":"r2","texto":"Porque los animales domésticos no tienen microbios"},{"id":"r3","texto":"Porque las zoonosis solo existen en otros continentes"}]},"solucion":{"valor":false,"explicacion":"Muchas vienen de animales domésticos y de producción: la rabia puede venir de perros y gatos, la hidatidosis del ciclo entre perros y ovejas, y el síndrome urémico hemolítico de bacterias del intestino del ganado.","clave":["r1"]}},{"slug":"animales-6.s1.p7","orden":7,"grupo":"animales-6.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un ejemplo de manual: la hidatidosis","cuerpo":["La hidatidosis la causa un pequeño parásito que vive en el intestino de los perros. El perro infectado elimina miles de huevos en sus heces, que contaminan el pasto, el agua o las verduras. Las ovejas, vacas o cerdos los ingieren y se les forman quistes en los órganos. Si al carnear alguien le da esas vísceras crudas a un perro, el ciclo vuelve a empezar. Las personas, sobre todo niñas y niños, se contagian al tragar huevos por contacto con perros, verduras mal lavadas o agua no segura.","Según el Ministerio de Salud, se previene sin alimentar a los perros con vísceras crudas, desparasitándolos cada 45 días, lavando frutas y verduras con agua potable y lavándose las manos después de tocar un perro y antes de comer."]},"solucion":{}},{"slug":"animales-6.s1.p8","orden":8,"grupo":"animales-6.s1.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el ciclo de la hidatidosis a partir de un perro infectado.","items":[{"id":"i1","texto":"Un perro con el parásito elimina huevos en sus heces"},{"id":"i2","texto":"Los huevos contaminan el pasto, el agua o las verduras"},{"id":"i3","texto":"Una oveja los ingiere y se le forman quistes en los órganos"},{"id":"i4","texto":"Al carnear, alguien le da las vísceras crudas a un perro"},{"id":"i5","texto":"Ese perro se infecta y el ciclo vuelve a empezar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ciclo entre perros y ganado en el que las personas se contagian de rebote."}},{"slug":"animales-6.s1.p9","orden":9,"grupo":"animales-6.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la forma más eficaz de cortar el ciclo de la hidatidosis?","opciones":[{"id":"o1","texto":"No dar vísceras crudas a los perros y desparasitarlos"},{"id":"o2","texto":"Dejar de comer verduras de huerta para siempre"},{"id":"o3","texto":"Sacrificar a todas las ovejas del campo"},{"id":"o4","texto":"Tomar antibióticos cada vez que se toca un perro"}]},"solucion":{"clave":["o1"],"explicacion":"Si el perro no come vísceras con quistes y está desparasitado, el ciclo se corta.","por_opcion":{"o3":"No hace falta: alcanza con cortar el paso de las vísceras al perro."}}},{"slug":"animales-6.s1.p10","orden":10,"grupo":"animales-6.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Quiénes tienen que participar en un plan local contra la hidatidosis? Marcá todos.","opciones":[{"id":"o1","texto":"Veterinarios que desparasitan a los perros"},{"id":"o2","texto":"Médicos que diagnostican y notifican casos"},{"id":"o3","texto":"Productores que controlan la faena y las vísceras"},{"id":"o4","texto":"Escuelas que enseñan hábitos de higiene"},{"id":"o5","texto":"Solo el hospital, porque es una enfermedad humana"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El problema cruza sectores, así que la solución también: eso es una sola salud en la práctica."}},{"slug":"animales-6.s1.p11","orden":11,"grupo":"animales-6.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué agrega el enfoque Una sola salud frente a que cada sector trabaje por su cuenta?","opciones":[{"id":"o1","texto":"Detecta y previene problemas que cruzan sectores"},{"id":"o2","texto":"Reemplaza a los médicos por veterinarios en los hospitales"},{"id":"o3","texto":"Se ocupa solo de las mascotas de la casa"},{"id":"o4","texto":"Elimina la necesidad de tener vacunas y medicamentos"}]},"solucion":{"clave":["o1"],"explicacion":"Ver el sistema completo permite actuar antes y en el punto donde es más fácil cortar el problema.","por_opcion":{"o3":"Abarca personas, animales domésticos, silvestres y ecosistemas."}}},{"slug":"animales-6.s1.p12","orden":12,"grupo":"animales-6.s1.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El síndrome urémico hemolítico, ligado a una bacteria del intestino del ganado, es un ejemplo de zoonosis transmitida por alimentos.","razones":[{"id":"r1","texto":"Porque la bacteria vive en el ganado y llega por los alimentos"},{"id":"r2","texto":"Porque se contagia solo entre personas, sin animales"},{"id":"r3","texto":"Porque lo transmite un mosquito"}]},"solucion":{"valor":true,"explicacion":"La bacteria Escherichia coli productora de toxina Shiga vive en el intestino de los bovinos y llega a las personas por carne poco cocida, lácteos sin pasteurizar o agua no segura.","clave":["r1"]}},{"slug":"animales-6.s1.p13","orden":13,"grupo":"animales-6.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este folleto municipal y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Desparasitá a tu perro cada 45 días."},{"id":"s2","texto":"Las vísceras crudas son un buen alimento para el perro de campo."},{"id":"s3","texto":"Lavá frutas y verduras con agua potable."},{"id":"s4","texto":"La hidatidosis es un tema de los veterinarios; los médicos no intervienen."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen mensaje de prevención reúne todos los eslabones del ciclo.","por_opcion":{"s2":"Es justamente la vía por la que el perro se infecta de hidatidosis.","s4":"Hace falta el trabajo conjunto de salud humana y animal."}}},{"slug":"animales-6.s1.p14","orden":14,"grupo":"animales-6.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una enfermedad que pasa entre animales y personas es una {{0}}; el enfoque que integra la salud de personas, animales y ecosistemas se llama Una sola {{1}}; y para prevenir la hidatidosis hay que {{2}} a los perros.","banco":[{"id":"w1","texto":"zoonosis"},{"id":"w2","texto":"salud"},{"id":"w3","texto":"desparasitar"},{"id":"w4","texto":"epidemia"},{"id":"w5","texto":"ciencia"},{"id":"w6","texto":"bañar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas de base que vas a usar en toda la unidad."}}]},{"slug":"animales-6.s2","orden":2,"tipo":"leccion","titulo_es":"Del bosque al contagio","bajada_es":"Desmontes, tráfico de fauna y granjas sin controles: cómo aparecen las enfermedades nuevas.","minutos":12,"pasos":[{"slug":"animales-6.s2.p1","orden":1,"grupo":"animales-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El salto entre especies","cuerpo":["Muchos microbios viven en animales silvestres sin enfermarlos. El problema aparece cuando aumenta el contacto entre fauna, animales domésticos y personas: un virus puede \"saltar\" a una especie nueva, adaptarse y empezar a contagiarse entre personas. Según el informe sobre biodiversidad y pandemias de la plataforma científica IPBES (2020), más del 70 % de las enfermedades emergentes y casi todas las pandemias conocidas, como las de gripe, el SIDA o la COVID-19, tienen origen en microbios de animales.","El mismo informe estima que en mamíferos y aves hay hasta 1,7 millones de virus todavía no descubiertos, de los cuales entre 631.000 y 827.000 podrían infectar a personas."],"destacado":{"valor":"1,7 millones","texto":"de virus sin descubrir se estima que hay en mamíferos y aves; hasta 827.000 podrían infectar a personas (IPBES, 2020)."}},"solucion":{}},{"slug":"animales-6.s2.p2","orden":2,"grupo":"animales-6.s2.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un desmonte puede terminar en una enfermedad nueva.","items":[{"id":"i1","texto":"Se desmonta un bosque para cultivos o ganado"},{"id":"i2","texto":"Aumenta el contacto entre fauna, ganado y personas"},{"id":"i3","texto":"Un virus de un animal silvestre llega a animales domésticos o personas"},{"id":"i4","texto":"El virus se adapta y empieza a pasar entre personas"},{"id":"i5","texto":"Aparece una enfermedad nueva"},{"id":"i6","texto":"Menos bosque significa menos contacto con la fauna"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El desmonte no solo destruye hábitat: también multiplica los encuentros que permiten el salto."}},{"slug":"animales-6.s2.p3","orden":3,"grupo":"animales-6.s2.p3","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos virus sin descubrir podría haber en mamíferos y aves.","min":1000,"max":100000000,"paso":1,"unidad":"virus","escala":"log"},"solucion":{"valor":1700000,"banda":"log","explicacion":"El IPBES estima hasta 1,7 millones: conocemos una fracción mínima de la diversidad de virus que existe."}},{"slug":"animales-6.s2.p4","orden":4,"grupo":"animales-6.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los motores","cuerpo":["El IPBES atribuye más del 30 % de las enfermedades infecciosas emergentes al cambio de uso del suelo, la expansión agrícola y la urbanización. También pesan el comercio de fauna silvestre, que en 2019 movió más de 100.000 millones de dólares de forma legal, más un comercio ilegal difícil de medir, y la producción animal intensiva sin bioseguridad, donde miles de animales juntos permiten que un virus se propague rápido.","La conclusión del informe es fuerte: aunque los microbios vienen de animales, la aparición de las pandemias está impulsada por actividades humanas."]},"solucion":{}},{"slug":"animales-6.s2.p5","orden":5,"grupo":"animales-6.s2.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta actividad aumenta o reduce el riesgo de que surja una zoonosis nueva?","grupos":[{"id":"g1","nombre":"Aumenta el riesgo"},{"id":"g2","nombre":"Reduce el riesgo"}],"items":[{"id":"i1","texto":"Desmonte de selvas para cultivos"},{"id":"i2","texto":"Conservar los bosques nativos"},{"id":"i3","texto":"Tráfico de fauna silvestre"},{"id":"i4","texto":"Controles sanitarios en las granjas"},{"id":"i5","texto":"Mercados con animales vivos de muchas especies"},{"id":"i6","texto":"Vigilancia de la salud de la fauna"},{"id":"i7","texto":"Galpones con miles de aves sin bioseguridad"},{"id":"i8","texto":"Combatir el tráfico de fauna"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Las mismas acciones que protegen la biodiversidad reducen el riesgo de nuevas enfermedades."}},{"slug":"animales-6.s2.p6","orden":6,"grupo":"animales-6.s2.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada motor de enfermedades nuevas con un ejemplo.","izquierda":[{"id":"a1","texto":"Cambio de uso del suelo"},{"id":"a2","texto":"Comercio de fauna silvestre"},{"id":"a3","texto":"Producción intensiva sin bioseguridad"},{"id":"a4","texto":"Urbanización"}],"derecha":[{"id":"b1","texto":"Desmonte de selva para cultivos"},{"id":"b2","texto":"Loros capturados que se venden en ferias"},{"id":"b3","texto":"Galpones con miles de aves cerca de humedales"},{"id":"b4","texto":"Barrios nuevos sobre bordes de monte"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los cuatro motores tienen algo en común: más contacto entre especies que antes no se cruzaban."}},{"slug":"animales-6.s2.p7","orden":7,"grupo":"animales-6.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las pandemias son fenómenos puramente naturales en los que las actividades humanas no influyen.","razones":[{"id":"r1","texto":"Porque las actividades humanas aumentan el contacto que permite el salto"},{"id":"r2","texto":"Porque los virus aparecen de la nada en las ciudades"},{"id":"r3","texto":"Porque las pandemias solo las causan bacterias"}]},"solucion":{"valor":false,"explicacion":"El IPBES concluye que la aparición de pandemias está impulsada por actividades humanas: cambio de uso del suelo, comercio de fauna y producción intensiva.","clave":["r1"]}},{"slug":"animales-6.s2.p8","orden":8,"grupo":"animales-6.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir es mucho más barato","cuerpo":["Hoy el mundo responde a las pandemias cuando ya empezaron, con vacunas y tratamientos: un camino lento e incierto. El IPBES estimó que la COVID-19 había costado entre 8 y 16 billones de dólares hasta julio de 2020, y que reducir los riesgos para prevenir pandemias costaría unas 100 veces menos que responder a ellas. Prevenir significa, sobre todo, frenar el desmonte, controlar el comercio de fauna y vigilar la salud animal."]},"solucion":{}},{"slug":"animales-6.s2.p9","orden":9,"grupo":"animales-6.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si responder a una pandemia cuesta 8.000 miles de millones de dólares y prevenirla cuesta 100 veces menos, ¿cuántos miles de millones de dólares cuesta prevenirla?","unidad":"miles de millones de dólares","decimales":0,"contexto":"Respuesta: 8000 miles de millones; prevención 100 veces menos."},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"8.000 ÷ 100 = 80 miles de millones de dólares. Con la proporción del IPBES, prevenir es una inversión mucho más barata que reaccionar."}},{"slug":"animales-6.s2.p9.v2","orden":9,"grupo":"animales-6.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si responder a una pandemia cuesta 12.000 miles de millones de dólares y prevenirla cuesta 100 veces menos, ¿cuántos miles de millones de dólares cuesta prevenirla?","unidad":"miles de millones de dólares","decimales":0,"contexto":"Respuesta: 12000 miles de millones; prevención 100 veces menos."},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"12.000 ÷ 100 = 120 miles de millones de dólares. Con la proporción del IPBES, prevenir es una inversión mucho más barata que reaccionar."}},{"slug":"animales-6.s2.p9.v3","orden":9,"grupo":"animales-6.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si responder a una pandemia cuesta 16.000 miles de millones de dólares y prevenirla cuesta 100 veces menos, ¿cuántos miles de millones de dólares cuesta prevenirla?","unidad":"miles de millones de dólares","decimales":0,"contexto":"Respuesta: 16000 miles de millones; prevención 100 veces menos."},"solucion":{"valor":160,"tolerancia":3.2,"explicacion":"16.000 ÷ 100 = 160 miles de millones de dólares. Con la proporción del IPBES, prevenir es una inversión mucho más barata que reaccionar."}},{"slug":"animales-6.s2.p10","orden":10,"grupo":"animales-6.s2.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mascotas que no deberían serlo","cuerpo":["Comprar un loro, un mono o una tortuga capturados en la naturaleza vacía las poblaciones silvestres, y muchos animales mueren en el traslado. Además, en esos viajes van estresados, amontonados y mezclados con otras especies: condiciones ideales para que se propaguen microbios. Un ejemplo es la psitacosis, una bacteria que transmiten loros y otras aves y que puede causar neumonía en las personas. En Argentina, capturar y comerciar fauna silvestre sin autorización está prohibido por la ley de fauna."]},"solucion":{}},{"slug":"animales-6.s2.p11","orden":11,"grupo":"animales-6.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Por qué no conviene comprar un loro capturado en la naturaleza? Marcá todo.","opciones":[{"id":"o1","texto":"Puede transmitir enfermedades como la psitacosis"},{"id":"o2","texto":"Alimenta el tráfico que vacía las poblaciones silvestres"},{"id":"o3","texto":"Muchos animales mueren durante el traslado"},{"id":"o4","texto":"Es ilegal comerciarlo sin autorización"},{"id":"o5","texto":"Porque los loros silvestres viven más tiempo en jaula"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fauna silvestre no es mascota: el tráfico daña a las especies y a la salud pública."}},{"slug":"animales-6.s2.p12","orden":12,"grupo":"animales-6.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los mercados con animales vivos de muchas especies son de alto riesgo?","opciones":[{"id":"o1","texto":"Juntan especies estresadas que nunca se cruzarían"},{"id":"o2","texto":"Porque allí todos los animales están vacunados"},{"id":"o3","texto":"Porque venden solo animales domésticos"},{"id":"o4","texto":"Porque el aire libre elimina todos los virus"}]},"solucion":{"clave":["o1"],"explicacion":"Estrés, hacinamiento y mezcla de especies: la receta para que un microbio salte.","por_opcion":{"o3":"Suelen mezclar animales silvestres y domésticos."}}},{"slug":"animales-6.s2.p13","orden":13,"grupo":"animales-6.s2.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Según el IPBES, ¿qué medida ataca la causa de fondo de las zoonosis nuevas?","opciones":[{"id":"o1","texto":"Reducir el desmonte y el comercio de fauna silvestre"},{"id":"o2","texto":"Esperar cada brote y desarrollar una vacuna nueva"},{"id":"o3","texto":"Cerrar todos los parques nacionales al público"},{"id":"o4","texto":"Eliminar a los murciélagos de todo el país"}]},"solucion":{"clave":["o1"],"explicacion":"Las vacunas son vitales, pero llegan tarde: prevenir el contacto evita que el brote empiece.","por_opcion":{"o4":"Matar fauna no resuelve el problema y puede dispersar los virus."}}},{"slug":"animales-6.s2.p14","orden":14,"grupo":"animales-6.s2.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota de opinión y marcá las afirmaciones equivocadas.","segmentos":[{"id":"s1","texto":"Más del 70 % de las enfermedades emergentes tienen origen animal."},{"id":"s2","texto":"Como los virus vienen de los animales, la culpa de las pandemias es de la fauna."},{"id":"s3","texto":"Conservar los bosques ayuda a reducir el riesgo de pandemias."},{"id":"s4","texto":"Prevenir pandemias sale más caro que responder cuando ya empezaron."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El problema no son los animales, sino cómo nos relacionamos con ellos y con sus hábitats.","por_opcion":{"s2":"Según el IPBES, lo que impulsa el salto son las actividades humanas.","s4":"Es al revés: prevenir cuesta unas 100 veces menos."}}},{"slug":"animales-6.s2.p15","orden":15,"grupo":"animales-6.s2.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando un virus pasa de una especie a otra se habla de un {{0}}; el IPBES atribuye más del 30 % de las enfermedades emergentes al cambio de uso del {{1}}; y prevenir pandemias cuesta unas {{2}} veces menos que responder.","banco":[{"id":"w1","texto":"salto"},{"id":"w2","texto":"suelo"},{"id":"w3","texto":"100"},{"id":"w4","texto":"golpe"},{"id":"w5","texto":"agua"},{"id":"w6","texto":"10"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para explicar de dónde vienen las enfermedades nuevas."}}]},{"slug":"animales-6.s3","orden":3,"tipo":"leccion","titulo_es":"Brotes cerca de casa","bajada_es":"El hantavirus en Epuyén, las ratadas del colihue y la gripe aviar en Península Valdés.","minutos":12,"pasos":[{"slug":"animales-6.s3.p1","orden":1,"grupo":"animales-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hantavirus en la cordillera","cuerpo":["El hantavirus se transmite sobre todo al respirar polvo contaminado con orina, heces o saliva de roedores silvestres infectados, por ejemplo al entrar a galpones o cabañas cerradas. En el sur argentino circula el virus Andes, el único hantavirus en el que se comprobó contagio entre personas.","Entre noviembre de 2018 y febrero de 2019, en Epuyén (Chubut), un solo contagio desde un roedor desató un brote de 34 personas infectadas y 11 muertes. Según el estudio publicado en el New England Journal of Medicine, tres personas con síntomas que asistieron a reuniones sociales concurridas contagiaron a la mayoría."],"destacado":{"valor":"34 y 11","texto":"personas infectadas y muertes en el brote de hantavirus de Epuyén, Chubut (2018-2019)."}},"solucion":{}},{"slug":"animales-6.s3.p2","orden":2,"grupo":"animales-6.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En el brote de Epuyén hubo 34 personas infectadas y 11 muertes. ¿Qué porcentaje de las personas infectadas murió? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Brote de Epuyén: 34 infectados y 11 muertes."},"solucion":{"valor":32,"tolerancia":1,"explicacion":"11 ÷ 34 × 100 ≈ 32 %. Casi una de cada tres personas infectadas murió: por eso la prevención es tan importante."}},{"slug":"animales-6.s3.p3","orden":3,"grupo":"animales-6.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cortar la cadena de contagio","cuerpo":["El número reproductivo indica a cuántas personas contagia, en promedio, cada caso. Si es mayor que 1, el brote crece; si es menor que 1, se apaga. En Epuyén era de 2,12 antes de las medidas de control y bajó a 0,96 cuando se aislaron los casos y se pusieron en cuarentena sus contactos."]},"solucion":{}},{"slug":"animales-6.s3.p4","orden":4,"grupo":"animales-6.s3.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En Epuyén, el número reproductivo bajó de 2,12 a 0,96 tras aislar casos y contactos. ¿Qué significa?","opciones":[{"id":"o1","texto":"Cada caso contagiaba a menos de uno: el brote se apagaba"},{"id":"o2","texto":"Que el virus se volvió más contagioso que antes"},{"id":"o3","texto":"Que había el doble de casos que antes de las medidas"},{"id":"o4","texto":"Que la mitad de los roedores de la zona había muerto"}]},"solucion":{"clave":["o1"],"explicacion":"Bajar de 1 es la meta de todo control de brotes: cada contagio genera menos de un contagio nuevo.","por_opcion":{"o4":"El número reproductivo mide contagios entre personas."}}},{"slug":"animales-6.s3.p5","orden":5,"grupo":"animales-6.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ratadas","cuerpo":["La caña colihue, un bambú nativo de los bosques andinos, florece de forma masiva cada varias décadas y produce enormes cantidades de semillas. Con tanta comida, los ratones colilargos, principal reservorio del virus Andes, se multiplican: es lo que en la Patagonia llaman \"ratada\". Con más roedores cerca de las casas, aumenta el riesgo de hantavirus.","Según el Ministerio de Salud, antes de entrar a un lugar cerrado hay que ventilarlo al menos 30 minutos, humedecer el piso antes de barrer para no levantar polvo y desinfectar con una parte de lavandina en nueve partes de agua."]},"solucion":{}},{"slug":"animales-6.s3.p6","orden":6,"grupo":"animales-6.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una floración del colihue puede aumentar los casos de hantavirus.","items":[{"id":"i1","texto":"La caña colihue florece de forma masiva"},{"id":"i2","texto":"Hay una enorme cantidad de semillas en el bosque"},{"id":"i3","texto":"Los colilargos se multiplican"},{"id":"i4","texto":"Más roedores entran a galpones y cabañas"},{"id":"i5","texto":"Aumenta el riesgo de hantavirus para las personas"},{"id":"i6","texto":"Las semillas del colihue matan a los ratones"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un fenómeno de las plantas cambia la cantidad de roedores y, con ella, el riesgo para las personas."}},{"slug":"animales-6.s3.p7","orden":7,"grupo":"animales-6.s3.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo limpiar un galpón que estuvo cerrado en una zona con hantavirus.","items":[{"id":"i1","texto":"Abrir puertas y ventanas y ventilar al menos 30 minutos"},{"id":"i2","texto":"Entrar con guantes y barbijo adecuado"},{"id":"i3","texto":"Humedecer el piso y las excretas con agua con lavandina"},{"id":"i4","texto":"Retirar la suciedad con un trapo húmedo, sin barrer en seco"},{"id":"i5","texto":"Lavarse bien las manos al terminar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La clave es no levantar polvo: ventilar, humedecer y limpiar en húmedo."}},{"slug":"animales-6.s3.p8","orden":8,"grupo":"animales-6.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La solución para desinfectar se prepara con 1 parte de lavandina por cada 9 partes de agua. ¿Cuántos mililitros de lavandina hacen falta para preparar 1 litro de solución?","unidad":"mL","decimales":0,"contexto":"Proporción 1 a 9; 1 L de solución."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"1 + 9 = 10 partes; 1000 mL ÷ 10 = 100 mL de lavandina y 900 mL de agua."}},{"slug":"animales-6.s3.p8.v2","orden":8,"grupo":"animales-6.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La solución para desinfectar se prepara con 1 parte de lavandina por cada 9 partes de agua. ¿Cuántos mililitros de lavandina hacen falta para preparar 5 litros de solución?","unidad":"mL","decimales":0,"contexto":"Proporción 1 a 9; 5 L de solución."},"solucion":{"valor":500,"tolerancia":10,"explicacion":"1 + 9 = 10 partes; 5000 mL ÷ 10 = 500 mL de lavandina y 4500 mL de agua."}},{"slug":"animales-6.s3.p8.v3","orden":8,"grupo":"animales-6.s3.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La solución para desinfectar se prepara con 1 parte de lavandina por cada 9 partes de agua. ¿Cuántos mililitros de lavandina hacen falta para preparar 2 litros de solución?","unidad":"mL","decimales":0,"contexto":"Proporción 1 a 9; 2 L de solución."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"1 + 9 = 10 partes; 2000 mL ÷ 10 = 200 mL de lavandina y 1800 mL de agua."}},{"slug":"animales-6.s3.p9","orden":9,"grupo":"animales-6.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Gripe aviar en el mar","cuerpo":["En octubre de 2023, un virus de gripe aviar H5N1 llegó a la colonia de elefantes marinos del sur en Península Valdés. Se estima que murieron unas 17.400 crías, casi el 97 % de las nacidas esa temporada, además de muchos adultos. Un estudio publicado en Nature Communications encontró evidencias de que el virus se transmitió entre mamíferos, y no solo de aves a mamíferos. El mismo virus afectó a lobos marinos y a aves marinas como los gaviotines.","Es un caso de una sola salud: un virus de aves que golpea a mamíferos marinos, pone en riesgo a las granjas avícolas, afecta al turismo y exige cuidados a quienes trabajan con animales."]},"solucion":{}},{"slug":"animales-6.s3.p10","orden":10,"grupo":"animales-6.s3.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si unas 17.400 crías muertas eran cerca del 97 % de las nacidas, ¿cuántas crías habían nacido aproximadamente? Redondeá a la centena.","unidad":"crías","decimales":0,"contexto":"17.400 crías muertas, cerca del 97 % del total."},"solucion":{"valor":17900,"tolerancia":100,"explicacion":"17.400 ÷ 0,97 ≈ 17.938, o sea unas 17.900 crías: sobrevivió apenas un puñado de cada cien."}},{"slug":"animales-6.s3.p11","orden":11,"grupo":"animales-6.s3.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Por qué el brote de gripe aviar en Península Valdés es un problema de \"una sola salud\"? Marcá todo.","opciones":[{"id":"o1","texto":"Un virus de aves afectó a mamíferos marinos"},{"id":"o2","texto":"Pone en riesgo a las granjas avícolas"},{"id":"o3","texto":"Afecta al turismo y a la economía local"},{"id":"o4","texto":"Exige cuidados a quienes manipulan animales"},{"id":"o5","texto":"Porque solo afecta a las gallinas de corral"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un mismo virus toca la fauna, la producción, la economía y la salud de las personas."}},{"slug":"animales-6.s3.p12","orden":12,"grupo":"animales-6.s3.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si encontrás un lobo marino o un ave muerta en la playa, conviene tocarla para ver si todavía está viva.","razones":[{"id":"r1","texto":"Porque pueden transmitir enfermedades y hay que avisar a las autoridades"},{"id":"r2","texto":"Porque los animales marinos nunca tienen enfermedades"},{"id":"r3","texto":"Porque tocarlos es la mejor forma de ayudarlos"}]},"solucion":{"valor":false,"explicacion":"No hay que tocar animales muertos o enfermos: pueden transmitir enfermedades. Lo correcto es alejarse y avisar a las autoridades sanitarias o ambientales para que tomen muestras.","clave":["r1"]}},{"slug":"animales-6.s3.p13","orden":13,"grupo":"animales-6.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje en un grupo de vecinos y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Antes de entrar a la cabaña, la dejamos ventilar media hora."},{"id":"s2","texto":"Después barremos en seco para sacar rápido las cacas de ratón."},{"id":"s3","texto":"Si alguien tiene fiebre después de limpiar, que consulte y cuente dónde estuvo."},{"id":"s4","texto":"El hantavirus no se contagia entre personas, así que no hace falta aislar a nadie."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los detalles de la limpieza y del aislamiento salvan vidas.","por_opcion":{"s2":"Barrer en seco levanta polvo contaminado: hay que humedecer antes.","s4":"El virus Andes sí se contagia entre personas, como mostró Epuyén."}}},{"slug":"animales-6.s3.p14","orden":14,"grupo":"animales-6.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En el sur argentino circula el virus {{0}}, que se contagia entre personas; la multiplicación de roedores tras la floración del colihue se llama {{1}}; y en 2023 la gripe aviar mató a casi todas las crías de {{2}} marinos de Península Valdés.","banco":[{"id":"w1","texto":"Andes"},{"id":"w2","texto":"ratada"},{"id":"w3","texto":"elefantes"},{"id":"w4","texto":"Nilo"},{"id":"w5","texto":"cosecha"},{"id":"w6","texto":"pingüinos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de brotes recientes en la Patagonia."}}]},{"slug":"animales-6.s4","orden":4,"tipo":"leccion","titulo_es":"Antibióticos: un bien común","bajada_es":"Cómo surgen las bacterias resistentes, qué papel tiene la ganadería y qué podemos hacer.","minutos":11,"pasos":[{"slug":"animales-6.s4.p1","orden":1,"grupo":"animales-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando los remedios dejan de funcionar","cuerpo":["Los antimicrobianos, como los antibióticos, son medicamentos que combaten microbios. Pero las bacterias cambian: cuando se usa un antibiótico, mueren las sensibles y sobreviven las pocas que resisten, que se multiplican sin competencia. Es selección natural en acción, y cuanto más y peor se usan los antibióticos, más rápido avanza. Según la OMS, en 2021 la resistencia bacteriana estuvo asociada a más de 4,7 millones de muertes en el mundo, y el uso indebido y excesivo de antibióticos es uno de sus principales motores."],"destacado":{"valor":"4,7 millones","texto":"de muertes en el mundo estuvieron asociadas a bacterias resistentes en 2021, según la OMS."}},"solucion":{}},{"slug":"animales-6.s4.p2","orden":2,"grupo":"animales-6.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el mal uso de antibióticos genera resistencia.","items":[{"id":"i1","texto":"Se toma un antibiótico sin necesitarlo"},{"id":"i2","texto":"El antibiótico mata a las bacterias sensibles"},{"id":"i3","texto":"Sobreviven las pocas bacterias resistentes"},{"id":"i4","texto":"Las resistentes se multiplican sin competencia"},{"id":"i5","texto":"Una próxima infección ya no responde a ese antibiótico"},{"id":"i6","texto":"El antibiótico vuelve más fuerte al sistema inmune"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada uso innecesario es una ventaja regalada a las bacterias resistentes."}},{"slug":"animales-6.s4.p3","orden":3,"grupo":"animales-6.s4.p3","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los antibióticos sirven para curar resfríos y gripes.","razones":[{"id":"r1","texto":"Porque los causan virus y los antibióticos actúan contra bacterias"},{"id":"r2","texto":"Porque los antibióticos solo sirven para animales"},{"id":"r3","texto":"Porque la gripe la causa un hongo"}]},"solucion":{"valor":false,"explicacion":"Resfríos y gripes los causan virus, y los antibióticos actúan contra bacterias. Tomarlos sin necesidad no ayuda y favorece la resistencia.","clave":["r1"]}},{"slug":"animales-6.s4.p4","orden":4,"grupo":"animales-6.s4.p4","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Un antibiótico sirve o no sirve para esta enfermedad?","grupos":[{"id":"g1","nombre":"Puede servir (causa bacteriana)"},{"id":"g2","nombre":"No sirve (causa viral)"}],"items":[{"id":"i1","texto":"Infección urinaria bacteriana"},{"id":"i2","texto":"Resfrío común"},{"id":"i3","texto":"Neumonía bacteriana"},{"id":"i4","texto":"Gripe"},{"id":"i5","texto":"Angina por estreptococo"},{"id":"i6","texto":"COVID-19"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los antibióticos solo actúan contra bacterias; qué tratamiento corresponde lo decide un profesional."}},{"slug":"animales-6.s4.p5","orden":5,"grupo":"animales-6.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Resistencia en el campo","cuerpo":["Los antimicrobianos también se usan en animales: para curarlos, para prevenir enfermedades cuando viven amontonados y, en algunos países, para que engorden más rápido. Según un estudio publicado en Science en 2019, alrededor del 73 % de los antimicrobianos que se venden en el mundo se usan en animales criados para alimento.","Las bacterias resistentes y sus genes pasan entre animales, personas y ambiente: por los alimentos, por el contacto directo, por el estiércol y por el agua. Por eso la Unión Europea prohibió desde 2006 usar antibióticos como promotores de crecimiento. La alternativa es prevenir: vacunas, higiene, menos hacinamiento y uso solo con receta veterinaria."]},"solucion":{}},{"slug":"animales-6.s4.p6","orden":6,"grupo":"animales-6.s4.p6","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los antimicrobianos que se venden en el mundo se usan en animales criados para alimento.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":73,"banda":"lineal","explicacion":"Alrededor del 73 %, según el estudio publicado en Science en 2019: la mayor parte del uso mundial está en la ganadería."}},{"slug":"animales-6.s4.p7","orden":7,"grupo":"animales-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un país se vendieran 1.000 toneladas de antimicrobianos y, como en el promedio mundial, el 73 % fuera a animales de producción, ¿cuántas toneladas quedarían para todos los demás usos?","unidad":"toneladas","decimales":0,"contexto":"1000 toneladas; 73 % para animales de producción."},"solucion":{"valor":270,"tolerancia":5.4,"explicacion":"100 % − 73 % = 27 %; 1.000 × 27 % = 270 toneladas. Valores de ejemplo con la proporción mundial."}},{"slug":"animales-6.s4.p7.v2","orden":7,"grupo":"animales-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un país se vendieran 500 toneladas de antimicrobianos y, como en el promedio mundial, el 73 % fuera a animales de producción, ¿cuántas toneladas quedarían para todos los demás usos?","unidad":"toneladas","decimales":0,"contexto":"500 toneladas; 73 % para animales de producción."},"solucion":{"valor":135,"tolerancia":2.7,"explicacion":"100 % − 73 % = 27 %; 500 × 27 % = 135 toneladas. Valores de ejemplo con la proporción mundial."}},{"slug":"animales-6.s4.p7.v3","orden":7,"grupo":"animales-6.s4.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un país se vendieran 2.000 toneladas de antimicrobianos y, como en el promedio mundial, el 73 % fuera a animales de producción, ¿cuántas toneladas quedarían para todos los demás usos?","unidad":"toneladas","decimales":0,"contexto":"2000 toneladas; 73 % para animales de producción."},"solucion":{"valor":540,"tolerancia":10.8,"explicacion":"100 % − 73 % = 27 %; 2.000 × 27 % = 540 toneladas. Valores de ejemplo con la proporción mundial."}},{"slug":"animales-6.s4.p8","orden":8,"grupo":"animales-6.s4.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada vía con un ejemplo de cómo viaja la resistencia.","izquierda":[{"id":"a1","texto":"Alimentos"},{"id":"a2","texto":"Contacto directo"},{"id":"a3","texto":"Estiércol"},{"id":"a4","texto":"Agua"}],"derecha":[{"id":"b1","texto":"Carne mal cocida con bacterias resistentes"},{"id":"b2","texto":"Trabajadores que manejan animales"},{"id":"b3","texto":"Bacterias resistentes que llegan al suelo"},{"id":"b4","texto":"Efluentes que llegan a ríos y arroyos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La resistencia no respeta fronteras entre especies ni entre ambientes."}},{"slug":"animales-6.s4.p9","orden":9,"grupo":"animales-6.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la Unión Europea prohibió desde 2006 usar antibióticos como promotores de crecimiento?","opciones":[{"id":"o1","texto":"Para frenar la resistencia: no curaban, solo engordaban"},{"id":"o2","texto":"Porque los antibióticos hacían crecer menos a los animales"},{"id":"o3","texto":"Porque los animales ya no se enfermaban nunca"},{"id":"o4","texto":"Porque eran más caros que el alimento balanceado"}]},"solucion":{"clave":["o1"],"explicacion":"Usar antibióticos en animales sanos para engordarlos multiplica la resistencia sin curar a nadie.","por_opcion":{"o3":"Siguen enfermándose; tratarlos con receta sigue permitido."}}},{"slug":"animales-6.s4.p10","orden":10,"grupo":"animales-6.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué podemos hacer","cuerpo":["Cada persona puede ayudar: tomar antibióticos solo con receta, seguir las indicaciones del profesional sobre dosis y duración, no compartirlos ni usar los que sobraron, y no exigirlos ante un resfrío. Vacunarse y lavarse las manos también ayudan, porque cada infección evitada es un antibiótico que no hace falta. En la producción, lo mismo: prevenir con vacunas e higiene, y usar antimicrobianos solo cuando un veterinario lo indica."]},"solucion":{}},{"slug":"animales-6.s4.p11","orden":11,"grupo":"animales-6.s4.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conductas ayudan a frenar la resistencia? Marcá todas.","opciones":[{"id":"o1","texto":"Tomar antibióticos solo con receta"},{"id":"o2","texto":"Seguir las indicaciones sobre dosis y duración"},{"id":"o3","texto":"No usar sobrantes ni compartir antibióticos"},{"id":"o4","texto":"Mantener las vacunas al día"},{"id":"o5","texto":"Pedir antibióticos ante cualquier resfrío"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Usar bien los antibióticos es cuidar un recurso que compartimos todos."}},{"slug":"animales-6.s4.p12","orden":12,"grupo":"animales-6.s4.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las bacterias resistentes pueden pasar de los animales a las personas a través de los alimentos y el ambiente.","razones":[{"id":"r1","texto":"Porque viajan por alimentos, contacto, estiércol y agua"},{"id":"r2","texto":"Porque las bacterias de los animales son siempre inofensivas"},{"id":"r3","texto":"Porque solo se transmiten por el aire"}]},"solucion":{"valor":true,"explicacion":"Por eso la resistencia es un problema de una sola salud: lo que se usa en un corral puede terminar afectando a un hospital.","clave":["r1"]}},{"slug":"animales-6.s4.p13","orden":13,"grupo":"animales-6.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un grupo de chat y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Si te sobró antibiótico de la otra vez, tomalo cuando tengas fiebre."},{"id":"s2","texto":"Lavarte las manos reduce infecciones y el uso de antibióticos."},{"id":"s3","texto":"Si te sentís mejor, cortá el antibiótico sin consultar."},{"id":"s4","texto":"Las vacunas previenen infecciones, así que se usan menos antibióticos."}]},"solucion":{"clave":["s1","s3"],"explicacion":"Los consejos de chat pueden sonar prácticos y ser peligrosos: con antibióticos, manda la receta.","por_opcion":{"s1":"Puede no ser el adecuado y favorece la resistencia.","s3":"La duración la define el profesional."}}},{"slug":"animales-6.s4.p14","orden":14,"grupo":"animales-6.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando un antibiótico deja de funcionar hablamos de {{0}}; los antibióticos no sirven contra los {{1}}; y en el mundo, la mayor parte de los antimicrobianos se usa en {{2}} de producción.","banco":[{"id":"w1","texto":"resistencia"},{"id":"w2","texto":"virus"},{"id":"w3","texto":"animales"},{"id":"w4","texto":"inmunidad"},{"id":"w5","texto":"bacterias"},{"id":"w6","texto":"hospitales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender la resistencia como un problema compartido."}}]},{"slug":"animales-6.s5","orden":5,"tipo":"leccion","titulo_es":"Clima, agua y prevención cotidiana","bajada_es":"Inundaciones, dengue, la carne que comemos y las mascotas: la salud compartida en la vida diaria.","minutos":11,"pasos":[{"slug":"animales-6.s5.p1","orden":1,"grupo":"animales-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Después de la inundación","cuerpo":["La leptospirosis la causa una bacteria que eliminan en la orina roedores, perros, vacas, cerdos, caballos y fauna silvestre. Sobrevive en ambientes húmedos y protegidos de la luz, y se contagia por contacto con esa orina o con agua y barro contaminados. Por eso el riesgo sube mucho con las inundaciones, que el cambio climático vuelve más frecuentes en muchas regiones. Se previene evitando meterse en agua estancada, usando botas y guantes al limpiar, controlando los roedores y manteniendo los patios sin basura."]},"solucion":{}},{"slug":"animales-6.s5.p2","orden":2,"grupo":"animales-6.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"Después de una inundación, ¿qué medidas previenen la leptospirosis? Marcá todas.","opciones":[{"id":"o1","texto":"Usar botas y guantes para limpiar"},{"id":"o2","texto":"Evitar que los chicos jueguen en charcos"},{"id":"o3","texto":"Sacar la basura que atrae roedores"},{"id":"o4","texto":"Consultar si aparece fiebre después de estar en el agua"},{"id":"o5","texto":"Caminar descalzo para no arruinar el calzado"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El agua de una inundación puede estar contaminada aunque se vea limpia."}},{"slug":"animales-6.s5.p3","orden":3,"grupo":"animales-6.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dengue y un clima más cálido","cuerpo":["El dengue lo transmite el mosquito Aedes aegypti, que se cría en recipientes con agua acumulada. La temporada 2023-2024 fue la mayor epidemia registrada en Argentina: según el Ministerio de Salud, hubo 583.297 casos confirmados y 419 muertes. Temperaturas más altas y temporadas cálidas más largas ayudan al mosquito a reproducirse más rápido y a extenderse hacia zonas más frías y hacia más meses del año."],"destacado":{"valor":"583.297","texto":"casos confirmados de dengue en la temporada 2023-2024, la mayor epidemia registrada en Argentina."}},"solucion":{}},{"slug":"animales-6.s5.p4","orden":4,"grupo":"animales-6.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En la temporada 2023-2024 hubo 583.297 casos confirmados de dengue y 419 muertes. ¿Qué porcentaje de los casos murió? Redondeá a dos decimales.","unidad":"%","decimales":2,"contexto":"583.297 casos confirmados y 419 muertes."},"solucion":{"valor":0.07,"tolerancia":0.01,"explicacion":"419 ÷ 583.297 × 100 ≈ 0,07 %. Una letalidad baja, pero con tantos casos se traduce en cientos de muertes evitables."}},{"slug":"animales-6.s5.p5","orden":5,"grupo":"animales-6.s5.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el calentamiento puede extender el dengue.","items":[{"id":"i1","texto":"Las temperaturas medias suben"},{"id":"i2","texto":"Los veranos son más largos y cálidos"},{"id":"i3","texto":"El mosquito se reproduce más rápido y en más meses"},{"id":"i4","texto":"Llega a zonas donde antes hacía demasiado frío"},{"id":"i5","texto":"Aparecen casos donde antes no había"},{"id":"i6","texto":"El calor extremo elimina a todos los mosquitos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El clima cambia el mapa de muchas enfermedades transmitidas por insectos."}},{"slug":"animales-6.s5.p6","orden":6,"grupo":"animales-6.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En la cocina y en casa","cuerpo":["El síndrome urémico hemolítico (SUH) está asociado a una bacteria, Escherichia coli productora de toxina Shiga, que vive en el intestino del ganado. Llega a las personas por carne poco cocida, lácteos sin pasteurizar, agua no segura o manos sucias. Argentina tiene una de las tasas de SUH más altas del mundo y es la principal causa de insuficiencia renal aguda en niñas y niños pequeños. Se previene cocinando bien la carne picada, separando crudos de cocidos y lavándose las manos.","La rabia se transmite por la saliva de un animal infectado, sobre todo por mordeduras. En Argentina la transmiten principalmente murciélagos, perros y gatos, y una vez que aparecen los síntomas casi siempre es mortal. Por eso hay que vacunar a perros y gatos cada año desde los 3 meses, no tocar murciélagos caídos y, ante una mordedura, lavar con abundante agua y jabón y consultar de inmediato."]},"solucion":{}},{"slug":"animales-6.s5.p7","orden":7,"grupo":"animales-6.s5.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la carne picada es más riesgosa que un bife si queda poco cocida?","opciones":[{"id":"o1","texto":"Al picarla, las bacterias de la superficie pasan al interior"},{"id":"o2","texto":"Porque la carne picada viene de animales más enfermos"},{"id":"o3","texto":"Porque un bife nunca puede tener bacterias"},{"id":"o4","texto":"Porque la carne picada tiene más grasa que el bife"}]},"solucion":{"clave":["o1"],"explicacion":"En un bife las bacterias quedan afuera y se cocinan; en la picada están también en el centro, que debe quedar sin partes rosadas.","por_opcion":{"o3":"Puede tenerlas en la superficie, que se cocina bien."}}},{"slug":"animales-6.s5.p8","orden":8,"grupo":"animales-6.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué enfermedad ayuda a prevenir cada hábito?","grupos":[{"id":"g1","nombre":"SUH"},{"id":"g2","nombre":"Rabia"},{"id":"g3","nombre":"Hidatidosis"}],"items":[{"id":"i1","texto":"Cocinar bien la carne picada"},{"id":"i2","texto":"Vacunar al perro cada año"},{"id":"i3","texto":"No dar vísceras crudas al perro"},{"id":"i4","texto":"Tomar lácteos pasteurizados"},{"id":"i5","texto":"No tocar murciélagos caídos"},{"id":"i6","texto":"Desparasitar al perro cada 45 días"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Hábitos simples de cocina y de tenencia responsable cortan zoonosis muy distintas."}},{"slug":"animales-6.s5.p9","orden":9,"grupo":"animales-6.s5.p9","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Un perro que no conocés te muerde. Ordená qué hacer.","items":[{"id":"i1","texto":"Alejarte del animal para evitar otra mordedura"},{"id":"i2","texto":"Lavar la herida con abundante agua y jabón"},{"id":"i3","texto":"Ir de inmediato a un centro de salud"},{"id":"i4","texto":"Seguir el tratamiento que te indiquen"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lavar bien la herida y consultar enseguida es lo que previene la rabia."}},{"slug":"animales-6.s5.p10","orden":10,"grupo":"animales-6.s5.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un murciélago está caído en el piso durante el día, conviene levantarlo con la mano para ayudarlo.","razones":[{"id":"r1","texto":"Porque puede estar enfermo, incluso con rabia"},{"id":"r2","texto":"Porque los murciélagos nunca tienen enfermedades"},{"id":"r3","texto":"Porque los murciélagos caídos siempre están muertos"}]},"solucion":{"valor":false,"explicacion":"Un murciélago caído de día puede estar enfermo, incluso con rabia. No hay que tocarlo: se lo cubre con un recipiente sin tocarlo y se avisa al área de zoonosis del municipio.","clave":["r1"]}},{"slug":"animales-6.s5.p11","orden":11,"grupo":"animales-6.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se notificaron 209 casos de SUH en una población de 47.000.000 habitantes. ¿Cuál es la tasa cada 100.000 habitantes? Redondeá a dos decimales.","unidad":"casos cada 100.000","decimales":2,"contexto":"209 casos; 47.000.000 habitantes."},"solucion":{"valor":0.44,"tolerancia":0.01,"explicacion":"209 ÷ 47.000.000 × 100.000 ≈ 0,44. Las tasas permiten comparar lugares y años con poblaciones distintas."}},{"slug":"animales-6.s5.p11.v2","orden":11,"grupo":"animales-6.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se notificaron 350 casos de SUH en una población de 47.000.000 habitantes. ¿Cuál es la tasa cada 100.000 habitantes? Redondeá a dos decimales.","unidad":"casos cada 100.000","decimales":2,"contexto":"350 casos; 47.000.000 habitantes."},"solucion":{"valor":0.74,"tolerancia":0.01,"explicacion":"350 ÷ 47.000.000 × 100.000 ≈ 0,74. Las tasas permiten comparar lugares y años con poblaciones distintas."}},{"slug":"animales-6.s5.p11.v3","orden":11,"grupo":"animales-6.s5.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Se notificaron 60 casos de SUH en una población de 3.000.000 habitantes. ¿Cuál es la tasa cada 100.000 habitantes? Redondeá a dos decimales.","unidad":"casos cada 100.000","decimales":2,"contexto":"60 casos; 3.000.000 habitantes."},"solucion":{"valor":2,"tolerancia":0.01,"explicacion":"60 ÷ 3.000.000 × 100.000 ≈ 2. Las tasas permiten comparar lugares y años con poblaciones distintas."}},{"slug":"animales-6.s5.p12","orden":12,"grupo":"animales-6.s5.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada enfermedad con la situación que más aumenta su riesgo.","izquierda":[{"id":"a1","texto":"Leptospirosis"},{"id":"a2","texto":"Dengue"},{"id":"a3","texto":"Hantavirus"},{"id":"a4","texto":"Hidatidosis"},{"id":"a5","texto":"SUH"}],"derecha":[{"id":"b1","texto":"Barrios inundados con agua y barro"},{"id":"b2","texto":"Recipientes con agua acumulada en el patio"},{"id":"b3","texto":"Galpones cerrados con roedores"},{"id":"b4","texto":"Perros alimentados con vísceras crudas"},{"id":"b5","texto":"Carne picada poco cocida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Conocer la situación de riesgo es saber dónde actuar."}},{"slug":"animales-6.s5.p13","orden":13,"grupo":"animales-6.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este folleto de un centro de salud y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Vaciá los recipientes que acumulan agua para evitar el mosquito del dengue."},{"id":"s2","texto":"La carne picada puede quedar jugosa y rosada en el centro sin riesgo."},{"id":"s3","texto":"Vacuná a tu perro y a tu gato contra la rabia cada año."},{"id":"s4","texto":"Después de una inundación, limpiá descalzo para no ensuciar el calzado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un folleto de prevención tiene que ser preciso: un solo error puede costar caro.","por_opcion":{"s2":"Debe cocinarse hasta que no queden partes rosadas.","s4":"El barro puede tener la bacteria de la leptospirosis: botas y guantes."}}},{"slug":"animales-6.s5.p14","orden":14,"grupo":"animales-6.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La leptospirosis aumenta después de las {{0}}; el mosquito del dengue se cría en agua {{1}}; y la carne picada debe cocinarse hasta que no queden partes {{2}}.","banco":[{"id":"w1","texto":"inundaciones"},{"id":"w2","texto":"acumulada"},{"id":"w3","texto":"rosadas"},{"id":"w4","texto":"sequías"},{"id":"w5","texto":"salada"},{"id":"w6","texto":"doradas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres hábitos para cuidar la salud compartida en la vida diaria."}}]},{"slug":"animales-6.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: una sola salud","bajada_es":"Zoonosis, saltos entre especies, brotes, resistencia a los antimicrobianos y prevención, mezclados.","minutos":8,"pasos":[{"slug":"animales-6.s6.p1","orden":1,"grupo":"animales-6.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Una sola salud». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"animales-6.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el pueblo después del agua","bajada_es":"Un pueblo del Litoral sale de una inundación con varios problemas de salud a la vez. Armá un plan de una sola salud.","minutos":10,"pasos":[{"slug":"animales-6.s7.p1","orden":1,"grupo":"animales-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Un pueblo de 20.000 habitantes del Litoral estuvo varias semanas bajo el agua. Desde que bajó, se confirmaron 12 casos de leptospirosis. Hay basurales en los bordes del barrio más afectado y muchos perros sueltos sin vacunar ni desparasitar. En una laguna cercana aparecieron aves silvestres muertas. Y en el centro de salud notan que muchos vecinos llegan después de tomar antibióticos comprados sin receta \"por las dudas\"."]},"solucion":{}},{"slug":"animales-6.s7.p2","orden":2,"grupo":"animales-6.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la tasa de leptospirosis del pueblo, en casos cada 100.000 habitantes?","unidad":"casos cada 100.000","decimales":0,"contexto":"12 casos en un pueblo de 20.000 habitantes."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"12 ÷ 20.000 × 100.000 = 60 casos cada 100.000 habitantes: una tasa muy alta, típica de un brote después de una inundación."}},{"slug":"animales-6.s7.p3","orden":3,"grupo":"animales-6.s7.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con las aves muertas de la laguna?","opciones":[{"id":"o1","texto":"No tocarlas y avisar al SENASA para que tome muestras"},{"id":"o2","texto":"Juntarlas a mano y tirarlas en el basural del barrio"},{"id":"o3","texto":"Esperar a que se descompongan solas en la orilla"},{"id":"o4","texto":"Dárselas a los perros sueltos como alimento"}]},"solucion":{"clave":["o1"],"explicacion":"Las mortandades de aves pueden ser gripe aviar: hay que avisar sin tocar, para proteger personas, fauna y granjas.","por_opcion":{"o3":"Sin muestras no se sabe si hay gripe aviar u otra causa."}}},{"slug":"animales-6.s7.p4","orden":4,"grupo":"animales-6.s7.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué sector debería liderar cada acción?","grupos":[{"id":"g1","nombre":"Salud humana"},{"id":"g2","nombre":"Sanidad animal"},{"id":"g3","nombre":"Ambiente"}],"items":[{"id":"i1","texto":"Atender y notificar los casos de leptospirosis"},{"id":"i2","texto":"Vacunar y desparasitar a los perros"},{"id":"i3","texto":"Limpiar los basurales que atraen roedores"},{"id":"i4","texto":"Informar sobre el uso correcto de antibióticos"},{"id":"i5","texto":"Tomar muestras de las aves muertas"},{"id":"i6","texto":"Recuperar el drenaje de los barrios"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada sector lidera algo, pero el plan funciona solo si coordinan entre todos."}},{"slug":"animales-6.s7.p5","orden":5,"grupo":"animales-6.s7.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del plan de una sola salud.","items":[{"id":"i1","texto":"Armar una mesa con salud, veterinaria, ambiente y vecinos"},{"id":"i2","texto":"Reunir datos de casos humanos, animales y ambientales"},{"id":"i3","texto":"Definir las acciones prioritarias y quién las lidera"},{"id":"i4","texto":"Comunicar las medidas a toda la población"},{"id":"i5","texto":"Evaluar los resultados y ajustar el plan"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Coordinación, datos, acción, comunicación y evaluación: el mismo método de siempre, con todos los sectores."}},{"slug":"animales-6.s7.p6","orden":6,"grupo":"animales-6.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué mensajes deberían recibir los vecinos? Marcá todos.","opciones":[{"id":"o1","texto":"Limpiar con botas y guantes y consultar si aparece fiebre"},{"id":"o2","texto":"Vacunar y desparasitar a los perros"},{"id":"o3","texto":"No tocar animales muertos y avisar si aparecen"},{"id":"o4","texto":"Usar antibióticos solo con receta"},{"id":"o5","texto":"Tomar antibióticos por las dudas después de mojarse"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Mensajes claros y concretos que cubren las personas, los animales y el ambiente."}},{"slug":"animales-6.s7.p7","orden":7,"grupo":"animales-6.s7.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los casos de leptospirosis son humanos, el plan solo necesita al hospital.","razones":[{"id":"r1","texto":"Porque el origen está en animales y ambiente"},{"id":"r2","texto":"Porque la leptospirosis se contagia solo entre personas"},{"id":"r3","texto":"Porque los hospitales no atienden leptospirosis"}]},"solucion":{"valor":false,"explicacion":"La bacteria viene de animales y se propaga por el ambiente: sin control de roedores, basurales, drenaje y animales, los casos van a seguir apareciendo.","clave":["r1"]}},{"slug":"animales-6.s7.p8","orden":8,"grupo":"animales-6.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Se hará una campaña de vacunación y desparasitación de perros."},{"id":"s2","texto":"Se repartirán antibióticos sin receta a todos los que estuvieron en el agua."},{"id":"s3","texto":"Se limpiarán los basurale